# ── Silent alert dialogs ─────────────────────────────────────────────────────
# Windows' native message dialogs play a system "ding" for every info/warning/
# error/question popup. We replace tkinter.messagebox.* with Tk-drawn dialogs
# that look the same but never beep. Every existing messagebox.<fn>(...) call is
# transparently routed here (no per-call-site changes needed).
_SILENT_MSG_ICONS = {
    "info": ("\u2139", "#1d4ed8"),
    "warning": ("\u26a0", "#b45309"),
    "error": ("\u2716", "#b91c1c"),
    "question": ("?", "#1d4ed8"),
}


def _silent_message_dialog(kind, buttons, default_value, cancel_value, title, message, options):
    """Modal, soundless replacement for a native message dialog.

    ``buttons`` is a list of (label, return_value) ordered left→right.
    Returns the chosen value (or ``cancel_value`` if closed/Escaped).
    """
    parent = options.get("parent")
    if parent is None:
        parent = getattr(tkinter, "_default_root", None)
    glyph, color = _SILENT_MSG_ICONS.get(
        options.get("icon", kind), _SILENT_MSG_ICONS.get(kind, ("", "#333333"))
    )
    full_msg = message or ""
    detail = options.get("detail")
    if detail:
        full_msg = f"{full_msg}\n\n{detail}" if full_msg else detail

    result = {"value": cancel_value}
    # Use app design-system colors (resolved at call-time, after constants are set).
    _bg  = globals().get("SFM_APP_BG",  "#f0f4fa")
    _sfg = globals().get("SFM_TEXT",    "#0f1623")
    _brd = globals().get("SFM_BORDER",  "#d0d7e3")
    try:
        win = tkinter.Toplevel(parent) if parent is not None else tkinter.Toplevel()
    except tkinter.TclError:
        return cancel_value
    win.title(title or "")
    win.configure(bg=_bg)
    win.resizable(False, False)
    try:
        win.transient(parent)
    except tkinter.TclError:
        pass

    # Thin accent bar at top — matches the app's card style
    _accent_clr = globals().get("SFM_ACCENT", "#1a56db")
    tkinter.Frame(win, bg=_accent_clr, height=3).pack(fill="x", side="top")

    body = tkinter.Frame(win, bg=_bg)
    body.pack(fill="both", expand=True, padx=16, pady=(14, 8))
    if glyph:
        tkinter.Label(
            body, text=glyph, font=("Segoe UI", 22), fg=color, bg=_bg
        ).pack(side="left", padx=(0, 14), anchor="n")
    tkinter.Label(
        body, text=full_msg, font=("Segoe UI", 10), bg=_bg, fg=_sfg,
        justify="left", wraplength=460,
    ).pack(side="left", fill="both", expand=True)

    # Separator above buttons
    tkinter.Frame(win, bg=_brd, height=1).pack(fill="x", padx=0)
    btn_bar = tkinter.Frame(win, bg=_bg)
    btn_bar.pack(fill="x", padx=16, pady=(8, 14))

    def _choose(value):
        result["value"] = value
        try:
            win.grab_release()
        except tkinter.TclError:
            pass
        win.destroy()

    default_btn = None
    for label, value in buttons:
        is_default = (value == default_value)
        style = "Accent.TButton" if is_default else "TButton"
        b = ttk.Button(
            btn_bar, text=label, width=9, style=style,
            command=lambda v=value: _choose(v),
        )
        b.pack(side="right", padx=(6, 0))
        if is_default:
            default_btn = b

    win.protocol("WM_DELETE_WINDOW", lambda: _choose(cancel_value))
    win.bind("<Escape>", lambda _e: _choose(cancel_value))
    win.bind("<Return>", lambda _e: _choose(default_value))
    win.bind("<KP_Enter>", lambda _e: _choose(default_value))

    win.update_idletasks()
    try:
        w, h = win.winfo_width(), win.winfo_height()
        if parent is not None and parent.winfo_viewable():
            x = parent.winfo_rootx() + (parent.winfo_width() - w) // 2
            y = parent.winfo_rooty() + (parent.winfo_height() - h) // 3
        else:
            x = (win.winfo_screenwidth() - w) // 2
            y = (win.winfo_screenheight() - h) // 3
        win.geometry(f"+{max(0, x)}+{max(0, y)}")
    except tkinter.TclError:
        pass

    try:
        win.grab_set()
    except tkinter.TclError:
        pass
    if default_btn is not None:
        try:
            default_btn.focus_set()
        except tkinter.TclError:
            pass
    win.wait_window()
    return result["value"]


def _install_silent_messageboxes():
    """Override tkinter.messagebox.* with the soundless dialogs above."""
    def showinfo(title=None, message=None, **o):
        return _silent_message_dialog("info", [("OK", "ok")], "ok", "ok", title, message, o)

    def showwarning(title=None, message=None, **o):
        return _silent_message_dialog("warning", [("OK", "ok")], "ok", "ok", title, message, o)

    def showerror(title=None, message=None, **o):
        return _silent_message_dialog("error", [("OK", "ok")], "ok", "ok", title, message, o)

    def askquestion(title=None, message=None, **o):
        return _silent_message_dialog(
            "question", [("No", "no"), ("Yes", "yes")], "yes", "no", title, message, o
        )

    def askyesno(title=None, message=None, **o):
        return _silent_message_dialog(
            "question", [("No", False), ("Yes", True)], True, False, title, message, o
        )

    def askokcancel(title=None, message=None, **o):
        return _silent_message_dialog(
            "question", [("Cancel", False), ("OK", True)], True, False, title, message, o
        )

    def askretrycancel(title=None, message=None, **o):
        return _silent_message_dialog(
            "warning", [("Cancel", False), ("Retry", True)], True, False, title, message, o
        )

    def askyesnocancel(title=None, message=None, **o):
        return _silent_message_dialog(
            "question", [("Cancel", None), ("No", False), ("Yes", True)], True, None, title, message, o
        )

    messagebox.showinfo = showinfo
    messagebox.showwarning = showwarning
    messagebox.showerror = showerror
    messagebox.askquestion = askquestion
    messagebox.askyesno = askyesno
    messagebox.askokcancel = askokcancel
    messagebox.askretrycancel = askretrycancel
    messagebox.askyesnocancel = askyesnocancel


_install_silent_messageboxes()


# Characters not allowed in Windows folder names
INVALID_WIN_FILENAME_CHARS = frozenset('\\/:*?"<>|')


def apply_text_case(text: str, mode: str) -> str:
    """Apply folder-name / rename case mode to *text*."""
    if not text or mode in ("", "original"):
        return text
    if mode == "upper":
        return text.upper()
    if mode == "lower":
        return text.lower()
    if mode == "title":
        return text.title()
    if mode == "sentence":
        lowered = text.lower()
        return re.sub(
            r"(^|[.!?]\s+)(\w)",
            lambda m: m.group(1) + m.group(2).upper(),
            lowered,
        )
    if mode == "toggle":
        return text.swapcase()
    return text

