def _parse_document_rename_pairs_from_text(text: str) -> list[tuple[str, str]]:
    """Parse `English-Korean` lines (split on last `-`); one side may be blank."""
    out: list[tuple[str, str]] = []
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        if "-" not in line:
            continue
        en, ko = line.rsplit("-", 1)
        en_b, ko_b = en.strip(), ko.strip()
        if en_b or ko_b:
            out.append((en_b, ko_b))
    return out


def _parse_document_rename_pairs() -> list[tuple[str, str]]:
    return _parse_document_rename_pairs_from_text(_RAW_DOCUMENT_RENAME_LINES)


DOCUMENT_RENAME_PAIRS: list[tuple[str, str]] = _parse_document_rename_pairs()
_BUILTIN_DOCUMENT_RENAME_SET = frozenset(DOCUMENT_RENAME_PAIRS)

