def document_rename_user_file_path() -> str:
    """Portable: next to the .exe when frozen, else next to this script."""
    if getattr(sys, "frozen", False):
        base = os.path.dirname(sys.executable)
    else:
        base = os.path.dirname(os.path.abspath(__file__))
    return os.path.join(base, "document_name_templates.txt")


# ---------------------------------------------------------------------------
# Lightweight app-settings persistence (JSON, next to exe / script)
# ---------------------------------------------------------------------------

import json as _json


def _settings_path() -> str:
    """Path to the JSON settings file (next to exe when frozen, else next to script)."""
    if getattr(sys, "frozen", False):
        base = os.path.dirname(sys.executable)
    else:
        base = os.path.dirname(os.path.abspath(__file__))
    return os.path.join(base, "sfm_settings.json")


def _open_file_with_os(path: str) -> None:
    """Open a file with the default OS application (cross-platform)."""
    try:
        import subprocess as _sub
        if sys.platform == "win32":
            os.startfile(os.path.normpath(path))  # type: ignore[attr-defined]
        elif sys.platform == "darwin":
            _sub.Popen(["open", path])
        else:
            _sub.Popen(["xdg-open", path])
    except Exception:
        pass


def _load_settings() -> dict:
    """Load persisted settings; return {} on any error."""
    try:
        with open(_settings_path(), encoding="utf-8") as f:
            data = _json.load(f)
        if isinstance(data, dict):
            return data
    except (OSError, _json.JSONDecodeError, ValueError):
        pass
    return {}


def _save_settings(data: dict) -> None:
    """Save settings dict to disk; silently ignore errors."""
    try:
        with open(_settings_path(), "w", encoding="utf-8", newline="\n") as f:
            _json.dump(data, f, ensure_ascii=False, indent=2)
    except OSError:
        pass




def _get_openai_api_key() -> str:
    """Return OpenAI API key: .env file first, then settings, then env var."""
    import os as _os
    # 1. .env file next to the app
    for base in (
        _os.path.dirname(_os.path.abspath(__file__)),
        _os.getcwd(),
    ):
        env_path = _os.path.join(base, ".env")
        if _os.path.isfile(env_path):
            try:
                with open(env_path, encoding="utf-8") as _f:
                    for line in _f:
                        line = line.strip()
                        if line.startswith("OPENAI_API_KEY"):
                            _, _, val = line.partition("=")
                            val = val.strip().strip('"\'\' ')
                            if val:
                                return val
            except OSError:
                pass
    # 2. Persisted settings
    saved = _load_settings().get("openai_api_key", "")
    if saved:
        return saved
    # 3. Environment variable
    return _os.environ.get("OPENAI_API_KEY", "")


def _set_openai_api_key(key: str) -> None:
    """Persist OpenAI API key to settings."""
    s = _load_settings()
    s["openai_api_key"] = key.strip()
    _save_settings(s)


def _show_expiry_heatmap(
    parent: tkinter.Misc,
    date_results: dict,
) -> None:
    """
    Feature 6 — Document expiry heat map.

    Shows a colour-coded card grid (green / yellow / red) for each date-sensitive
    document found in the Smart Split output.  Non-blocking (no modal grab).
    """
    top = tkinter.Toplevel(parent)
    top.title("Document Expiry — Heat Map")
    top.resizable(False, False)
    top.attributes("-topmost", True)

    # Use app design-system tokens (resolved at call-time)
    _app_bg  = SFM_APP_BG
    _surface = SFM_SURFACE
    _text    = SFM_TEXT
    _muted   = SFM_MUTED
    _border  = SFM_BORDER
    _accent  = SFM_ACCENT

    top.configure(bg=_app_bg)

    # Accent bar + header
    tkinter.Frame(top, bg=_accent, height=3).pack(fill=X)
    hdr_f = tkinter.Frame(top, bg=_app_bg)
    hdr_f.pack(fill=X, padx=SP_12, pady=(SP_8, SP_4))
    tkinter.Label(
        hdr_f, text="📅  Document Validity Overview",
        font=FONT_LG, anchor="w", bg=_app_bg, fg=_text,
    ).pack(side=LEFT)
    ttk.Button(hdr_f, text="✕ Close", command=top.destroy, style="TButton").pack(side=RIGHT)
    ttk.Separator(top, orient=HORIZONTAL).pack(fill=X, padx=SP_12, pady=(0, SP_4))

    # Legend row — uses app SFM constants, not Bootstrap hex
    _STATUS_COLORS = {
        "VALID":         SFM_SUCCESS,
        "EXPIRING SOON": SFM_WARNING,
        "EXPIRES TODAY": "#c2550a",   # darker orange, distinct from warning
        "EXPIRED":       SFM_DANGER,
        "UNKNOWN":       SFM_MUTED,
        "PARSE ERROR":   SFM_MUTED,
    }
    _STATUS_FG = {
        "VALID":         "#ffffff",
        "EXPIRING SOON": "#ffffff",
        "EXPIRES TODAY": "#ffffff",
        "EXPIRED":       "#ffffff",
        "UNKNOWN":       "#ffffff",
        "PARSE ERROR":   "#ffffff",
    }
    leg_f = tkinter.Frame(top, bg=_app_bg, padx=SP_12, pady=SP_4)
    leg_f.pack(fill=X)
    for col, lbl in (
        (SFM_SUCCESS, "≥ 14 days — Valid"),
        (SFM_WARNING, "< 14 days — Expiring"),
        (SFM_DANGER,  "Expired / Unknown"),
    ):
        lf = tkinter.Frame(leg_f, bg=_app_bg)
        lf.pack(side=LEFT, padx=(0, SP_16))
        tkinter.Label(lf, text="  ", bg=col, relief="flat").pack(side=LEFT, padx=(0, SP_4))
        tkinter.Label(lf, text=lbl, font=FONT_XS, bg=_app_bg, fg=_muted).pack(side=LEFT)

    # Cards frame (scrollable if many docs)
    canvas = tkinter.Canvas(top, borderwidth=0, highlightthickness=0, bg=_app_bg)
    vsb = ttk.Scrollbar(top, orient=VERTICAL, command=canvas.yview)
    canvas.configure(yscrollcommand=vsb.set)
    vsb.pack(side=RIGHT, fill=Y, padx=(0, SP_4), pady=SP_4)
    canvas.pack(side=LEFT, fill=BOTH, expand=True, padx=SP_12, pady=SP_6)
    cards_frame = tkinter.Frame(canvas, bg=_app_bg)
    canvas.create_window((0, 0), window=cards_frame, anchor="nw")

    if not date_results:
        tkinter.Label(
            cards_frame,
            text="No date-sensitive documents found in this output.",
            font=FONT_SM, fg=_muted, bg=_app_bg, padx=SP_8, pady=SP_16,
        ).pack()
    else:
        for key, info in date_results.items():
            status  = info.get("status", "UNKNOWN")
            bg_col  = _STATUS_COLORS.get(status, SFM_MUTED)
            fg_col  = _STATUS_FG.get(status, "#ffffff")
            dl      = info.get("days_left")

            # Card: white surface with left colour border
            card_outer = tkinter.Frame(cards_frame, bg=bg_col, pady=0, padx=0)
            card_outer.pack(fill=X, pady=(0, SP_6))
            card = tkinter.Frame(card_outer, bg=_surface, pady=SP_8, padx=SP_12)
            card.pack(fill=X, padx=(4, 0))  # 4 px left strip = status colour

            # Top row: label + status badge
            top_row = tkinter.Frame(card, bg=_surface)
            top_row.pack(fill=X)
            tkinter.Label(top_row, text=info["label"], bg=_surface, fg=_text,
                          font=FONT_MD, anchor="w").pack(side=LEFT)
            badge_txt = status
            if dl is not None and info.get("detail"):
                badge_txt += f"  ({info['detail']})"
            tkinter.Label(top_row, text=badge_txt, bg=bg_col, fg=fg_col,
                          font=FONT_XS, anchor="e", padx=SP_6, pady=2).pack(side=RIGHT)

            # Details row
            det_parts = []
            if info.get("file"):
                det_parts.append(f"File: {info['file']}")
            if info.get("issue") and info["issue"] != "?":
                det_parts.append(f"Issued: {info['issue']}")
            if info.get("expiry") and info["expiry"] != "?":
                det_parts.append(f"Expires: {info['expiry']}")
            if info.get("validity_days"):
                det_parts.append(f"Valid for {info['validity_days']} days from issue")
            tkinter.Label(card, text="   ".join(det_parts), bg=_surface, fg=_muted,
                          font=FONT_XS, anchor="w", wraplength=500).pack(anchor="w")

            # Progress bar using a ratio Canvas (no .place() — no fragile pixel math)
            if dl is not None and info.get("validity_days"):
                used_pct = max(0.0, min(1.0, 1.0 - dl / info["validity_days"]))
                bar_cvs = tkinter.Canvas(
                    card, height=6, bg="#e5e7eb",
                    highlightthickness=0, bd=0,
                )
                bar_cvs.pack(fill=X, pady=(SP_4, 0))
                bar_cvs.update_idletasks()
                bw = bar_cvs.winfo_width() or 300
                bar_clr = SFM_SUCCESS if used_pct < 0.85 else SFM_DANGER
                bar_cvs.create_rectangle(0, 0, int(bw * used_pct), 6, fill=bar_clr, outline="")
                # redraw on resize
                def _redraw(e, c=bar_cvs, p=used_pct, cl=bar_clr):
                    c.delete("all")
                    c.create_rectangle(0, 0, int(e.width * p), 6, fill=cl, outline="")
                bar_cvs.bind("<Configure>", _redraw)

    cards_frame.update_idletasks()
    canvas.configure(scrollregion=canvas.bbox("all"))

    # Dynamic height — cap at 540px
    needed_h = min(540, cards_frame.winfo_reqheight() + 120)
    top.geometry(f"580x{needed_h}")


def _show_duplicate_pages_dialog(
    parent: tkinter.Misc,
    duplicates: list,
    pdf_paths: list[str],
) -> bool:
    """
    Show a dialog listing detected duplicate pages before Smart Split.

    Returns True  → user wants to proceed anyway (ignore duplicates).
    Returns False → user chose to cancel the Smart Split operation.
    """
    dlg = tkinter.Toplevel(parent)
    dlg.title("Duplicate Pages Detected")
    dlg.resizable(True, True)
    dlg.grab_set()
    try:
        dlg.attributes("-topmost", True)
    except tkinter.TclError:
        pass

    ttk.Label(
        dlg,
        text=f"⚠  {len(duplicates)} near-identical page pair(s) found.\n"
             "These may be accidental double-scans.  Review them before processing.",
        font=("Segoe UI", 9), justify="left", padding=(12, 8),
    ).pack(fill=X)

    # Treeview listing duplicates
    cols = ("file_a", "pg_a", "file_b", "pg_b", "dist")
    tv = ttk.Treeview(dlg, columns=cols, show="headings", height=min(len(duplicates), 10))
    tv.heading("file_a", text="File A",    anchor="w")
    tv.heading("pg_a",   text="Page A",   anchor="center")
    tv.heading("file_b", text="File B",    anchor="w")
    tv.heading("pg_b",   text="Page B",   anchor="center")
    tv.heading("dist",   text="Similarity", anchor="center")
    tv.column("file_a", width=180, anchor="w")
    tv.column("pg_a",   width=60,  anchor="center")
    tv.column("file_b", width=180, anchor="w")
    tv.column("pg_b",   width=60,  anchor="center")
    tv.column("dist",   width=80,  anchor="center")

    for pa, ia, pb, ib, dist in duplicates:
        sim = "Identical" if dist == 0 else f"{100 - int(dist / 64 * 100)}% similar"
        tv.insert("", "end", values=(
            os.path.basename(pa), f"p.{ia + 1}",
            os.path.basename(pb), f"p.{ib + 1}",
            sim,
        ))

    sb = ttk.Scrollbar(dlg, orient=VERTICAL, command=tv.yview)
    tv.configure(yscrollcommand=sb.set)
    tv.pack(side=LEFT, fill=BOTH, expand=True, padx=(12, 0), pady=(0, 8))
    sb.pack(side=LEFT, fill=Y, padx=(0, 12), pady=(0, 8))

    ttk.Label(
        dlg,
        text="Tip: close this dialog, open the source PDFs, remove duplicates, then re-run Smart Split.",
        font=("Segoe UI", 8), foreground="#555", padding=(12, 4),
    ).pack(fill=X)

    result = {"proceed": False}

    btn_row = ttk.Frame(dlg)
    btn_row.pack(fill=X, padx=12, pady=(4, 10))

    def _proceed() -> None:
        result["proceed"] = True
        dlg.destroy()

    def _cancel() -> None:
        result["proceed"] = False
        dlg.destroy()

    ttk.Button(btn_row, text="Process Anyway (ignore duplicates)", command=_proceed).pack(side=LEFT)
    ttk.Button(btn_row, text="Cancel — I'll fix duplicates first", command=_cancel).pack(side=RIGHT)

    dlg.wait_window()
    return result["proceed"]


def _ask_report_metadata(parent: tkinter.Misc) -> dict:
    """Show a small dialog to collect University / Program / Applicant / Agency
    for the checklist Word report header.  Returns a dict (values may be blank)."""
    result: dict = {}
    dlg = tkinter.Toplevel(parent)
    dlg.title("Report Details")
    dlg.resizable(False, False)
    dlg.grab_set()
    try:
        dlg.attributes("-topmost", True)
    except tkinter.TclError:
        pass

    ttk.Label(dlg, text="Fill in the report header details.\n(All fields are optional — leave blank if unknown.)",
              wraplength=340, justify="left", padding=(12, 8, 12, 4)).pack()

    form_frame = ttk.Frame(dlg, padding=(12, 4, 12, 4))
    form_frame.pack(fill=X)

    fields = [
        ("University",          "university"),
        ("Program / Visa Type", "program"),
        ("Applicant Name",      "applicant"),
        ("유학원  (Agency)",    "agency"),
    ]
    entries: dict[str, StringVar] = {}
    for row_idx, (label, key) in enumerate(fields):
        ttk.Label(form_frame, text=label, width=20, anchor="w").grid(
            row=row_idx, column=0, sticky=W, pady=3)
        var = StringVar()
        entries[key] = var
        ent = ttk.Entry(form_frame, textvariable=var, width=32)
        ent.grid(row=row_idx, column=1, sticky=(W, E), pady=3, padx=(6, 0))
        if row_idx == 0:
            ent.focus_set()

    def _on_ok(_e=None) -> None:
        for key, var in entries.items():
            result[key] = var.get().strip()
        dlg.grab_release()
        dlg.destroy()

    def _on_skip() -> None:
        dlg.grab_release()
        dlg.destroy()

    btn_frame = ttk.Frame(dlg, padding=(12, 6, 12, 10))
    btn_frame.pack()
    ttk.Button(btn_frame, text="Continue →", command=_on_ok).pack(side=LEFT, padx=4)
    ttk.Button(btn_frame, text="Skip", command=_on_skip).pack(side=LEFT, padx=4)

    dlg.bind("<Return>", _on_ok)
    dlg.bind("<KP_Enter>", _on_ok)

    # Centre on parent
    try:
        px = parent.winfo_rootx()
        py = parent.winfo_rooty()
        pw = parent.winfo_width()
        ph = parent.winfo_height()
        dlg.update_idletasks()
        dw = dlg.winfo_width()
        dh = dlg.winfo_height()
        dlg.geometry(f"+{px + (pw - dw) // 2}+{py + (ph - dh) // 2}")
    except tkinter.TclError:
        pass

    parent.wait_window(dlg)
    return result


def document_rename_load_user_templates() -> None:
    global _DOCUMENT_RENAME_USER_PAIRS
    path = document_rename_user_file_path()
    if not os.path.isfile(path):
        _DOCUMENT_RENAME_USER_PAIRS = []
        return
    try:
        with open(path, encoding="utf-8") as f:
            raw = f.read()
    except OSError:
        _DOCUMENT_RENAME_USER_PAIRS = []
        return
    _DOCUMENT_RENAME_USER_PAIRS = _parse_document_rename_pairs_from_text(raw)


def document_rename_get_user_pairs() -> list[tuple[str, str]]:
    return list(_DOCUMENT_RENAME_USER_PAIRS)


def document_rename_save_user_templates(pairs: list[tuple[str, str]]) -> tuple[bool, str]:
    """Write user-only templates; reloads merged list into memory."""
    path = document_rename_user_file_path()
    lines: list[str] = [
        "# Custom document rename templates (English-Korean, one per line).",
        "# One side may be blank for English-only or Korean-only templates.",
        "# Split is on the last hyphen. Lines starting with # are ignored.",
        "",
    ]
    for en, ko in pairs:
        en_b, ko_b = str(en).strip(), str(ko).strip()
        if not en_b and not ko_b:
            continue
        if any(c in en_b + ko_b for c in "\n\r"):
            continue
        lines.append(f"{en_b}-{ko_b}")
    body = "\n".join(lines).rstrip() + "\n"
    try:
        with open(path, "w", encoding="utf-8", newline="\n") as f:
            f.write(body)
    except OSError as e:
        return False, str(e)
    document_rename_load_user_templates()
    return True, path


def document_rename_stem_for_ocr_type(
    doc_type: str,
    page_text: str = "",
) -> str | None:
    """Bilingual filename stem (KR-EN) for an OCR-detected checklist document type."""
    if not doc_type or not str(doc_type).strip():
        return None
    key = str(doc_type).strip().upper()
    text = page_text or ""

    # Applicant vs parent passport / NID
    if key == "PASSPORT":
        if re.search(r"\bFATHER\b", text, re.IGNORECASE) or "아버지" in text:
            key = "PASSPORT"
            candidates = ("father passport",)
        elif re.search(r"\bMOTHER\b", text, re.IGNORECASE) or "어머니" in text:
            candidates = ("mother passport",)
        else:
            candidates = ("passport",)
        pairs = document_rename_merged_pairs()
        for cand in candidates:
            for en, ko in pairs:
                if en.lower() == cand or cand in en.lower():
                    return _document_rename_stem(en, ko)
    if key == "FATHER NID":
        candidates = ("father id",)
    elif key == "MOTHER NID":
        candidates = ("mother id",)
    else:
        candidates = list(_OCR_DOC_TYPE_TEMPLATE_KEYS.get(key, ()))
    if not candidates:
        candidates = [doc_type.strip().lower()]
    pairs = document_rename_merged_pairs()
    for cand in candidates:
        c_low = cand.lower()
        for en, ko in pairs:
            if en.lower() == c_low or c_low in en.lower():
                return _document_rename_stem(en, ko)
    # Loose match: any template whose English label shares a significant word
    words = [w for w in key.replace("&", " ").split() if len(w) > 3]
    if words:
        for en, ko in pairs:
            hay = en.lower()
            if sum(1 for w in words if w.lower() in hay) >= min(2, len(words)):
                return _document_rename_stem(en, ko)
    return None


def document_rename_merged_pairs() -> list[tuple[str, str]]:
    """User templates first, then built-in; drop exact duplicate (en, ko)."""
    seen: set[tuple[str, str]] = set()
    out: list[tuple[str, str]] = []
    for en, ko in _DOCUMENT_RENAME_USER_PAIRS + DOCUMENT_RENAME_PAIRS:
        key = (en, ko)
        if key in seen:
            continue
        seen.add(key)
        out.append(key)
    return out


def _find_adobe_photoshop_executable() -> str | None:
    """Return a Photoshop.exe (Windows), .app executable (macOS), or PATH name; None if not found."""
    if sys.platform == "win32":
        roots: list[str] = []
        for key in ("PROGRAMFILES", "PROGRAMFILES(X86)"):
            v = os.environ.get(key)
            if v:
                roots.append(v)
        roots.extend([r"C:\Program Files", r"C:\Program Files (x86)"])
        seen: set[str] = set()
        candidates: list[str] = []
        for root in roots:
            adobe = os.path.join(root, "Adobe")
            if not os.path.isdir(adobe):
                continue
            for p in glob.glob(os.path.join(adobe, "Adobe Photoshop*", "Photoshop.exe")):
                ap = os.path.normpath(p)
                if os.path.isfile(ap) and ap.lower() not in seen:
                    seen.add(ap.lower())
                    candidates.append(ap)
            beta = os.path.join(adobe, "Adobe Photoshop (Beta)", "Photoshop.exe")
            if os.path.isfile(beta):
                ap = os.path.normpath(beta)
                if ap.lower() not in seen:
                    seen.add(ap.lower())
                    candidates.append(ap)
        if not candidates:
            w = shutil.which("Photoshop.exe")
            return os.path.normpath(w) if w and os.path.isfile(w) else None
        return max(candidates, key=lambda p: os.path.getmtime(p))
    if sys.platform == "darwin":
        apps = "/Applications"
        if not os.path.isdir(apps):
            return None
        bundles: list[str] = []
        for name in os.listdir(apps):
            if not name.endswith(".app"):
                continue
            if "Photoshop" not in name:
                continue
            full = os.path.join(apps, name)
            if os.path.isdir(full):
                bundles.append(full)
        if not bundles:
            return None
        return max(bundles, key=lambda p: os.path.getmtime(p))
    w = shutil.which("photoshop") or shutil.which("Photoshop")
    return w if w and os.path.isfile(w) else None


def _normalize_template_query(s: str) -> str:
    """Lowercase + common Unicode dashes → ASCII for substring matching."""
    t = s.strip().lower()
    for u in ("\u2010", "\u2011", "\u2212", "\u2013", "\u2014"):
        t = t.replace(u, "-")
    return t


def _contains_hangul(text: str) -> bool:
    return bool(re.search(r"[가-힣ㄱ-ㅎㅏ-ㅣ]", text))


def _contains_latin(text: str) -> bool:
    return bool(re.search(r"[A-Za-z]", text))


def _document_rename_label(en: str, ko: str) -> str:
    en_b, ko_b = en.strip(), ko.strip()
    if ko_b and en_b:
        return f"{ko_b}  ·  {en_b}"
    return ko_b or en_b


def _document_rename_stem(en: str, ko: str) -> str:
    """Filename stem: Korean-English (KR-EN) when both exist, else single-language."""
    en_b, ko_b = en.strip(), ko.strip()
    parts: list[str] = []
    if ko_b:
        parts.append(ko_b)
    if en_b and en_b != ko_b:
        parts.append(en_b)
    raw = "-".join(parts) if parts else ""
    return "".join(c if c not in INVALID_WIN_FILENAME_CHARS else "_" for c in raw)


def _template_pair_from_name_text(text: str) -> tuple[str, str] | None:
    raw = str(text).strip()
    if not raw:
        return None
    candidates: list[tuple[int, int, int, str, str]] = []
    for idx, ch in enumerate(raw):
        if ch != "-":
            continue
        left = raw[:idx].strip()
        right = raw[idx + 1 :].strip()
        if not left or not right:
            continue
        left_h, right_h = _contains_hangul(left), _contains_hangul(right)
        if left_h == right_h:
            continue
        mixed_penalty = int(left_h and _contains_latin(left)) + int(right_h and _contains_latin(right))
        order_penalty = 0 if left_h and not right_h else 1
        candidates.append((mixed_penalty, order_penalty, idx, left, right))
    if candidates:
        _mixed, order, _idx, left, right = min(candidates, key=lambda t: (t[0], t[1], t[2]))
        return (right, left) if order == 0 else (left, right)
    if _contains_hangul(raw):
        return ("", raw)
    return (raw, "")


def _rename_query_has_single_char_tokens(q_raw: str) -> bool:
    """Spaced names like 'b c app' are custom labels — do not match document templates."""
    return any(len(tok) == 1 for tok in q_raw.split() if tok.strip())


def _filter_document_renames_scored(
    query: str, *, limit: int = 80
) -> list[tuple[int, str, str, str]]:
    """Match document templates; return (priority, en, ko, stem). Lower priority = stronger match."""
    q_raw = query.strip()
    q = _normalize_template_query(q_raw)
    pairs = document_rename_merged_pairs()

    def pack_browse(items: list[tuple[str, str]]) -> list[tuple[int, str, str, str]]:
        return [(0, en, ko, _document_rename_stem(en, ko)) for en, ko in items]

    if not q:
        return pack_browse(pairs[:limit])

    if _rename_query_has_single_char_tokens(q_raw):
        return []

    matches: list[tuple[int, int, str, str, str]] = []
    for idx, (en, ko) in enumerate(pairs):
        stem = _document_rename_stem(en, ko)
        en_l = en.lower()
        stem_l = stem.lower()
        ko_t = ko.strip()
        ko_l = ko_t.lower()
        if q == en_l or q == ko_l or q == stem_l:
            prio = 0
        elif (
            (len(q) >= 2 and (en_l.startswith(q) or stem_l.startswith(q) or ko_t.startswith(q_raw)))
            or (len(q) >= 3 and (q in ko_t or q in en_l or q in stem_l))
        ):
            if en_l.startswith(q) or stem_l.startswith(q) or ko_t.startswith(q_raw):
                prio = 1
            else:
                prio = 2
        else:
            continue
        matches.append((prio, idx, en, ko, stem))
    matches.sort(key=lambda t: (t[0], t[1]))
    return [(p, en, ko, st) for p, _i, en, ko, st in matches[:limit]]


def _filter_document_renames(query: str, *, limit: int = 80) -> list[tuple[str, str, str]]:
    """Match pairs by English, Korean, or full stem; return (en, ko, stem) with KR-EN stem."""
    return [(en, ko, st) for _p, en, ko, st in _filter_document_renames_scored(query, limit=limit)]


def _maximize_toplevel(widget: tkinter.Misc) -> None:
    """Maximize the main window (Windows: zoomed state; Linux: -zoomed when supported)."""
    root = widget.winfo_toplevel()
    try:
        root.state("zoomed")
    except tkinter.TclError:
        try:
            root.attributes("-zoomed", True)
        except tkinter.TclError:
            pass


def _bind_mousewheel_yview(widget: tkinter.Misc, yview_scroll) -> None:
    """Vertical scroll with mouse wheel (Windows / macOS / Linux)."""

    def on_wheel(event: tkinter.Event) -> str:
        if sys.platform == "darwin":
            yview_scroll(-1 if event.delta > 0 else 1, "units")
        else:
            d = event.delta
            if d:
                yview_scroll(int(-1 * (d / 120)), "units")
        return "break"

    def on_up(_event: tkinter.Event) -> str:
        yview_scroll(-3, "units")
        return "break"

    def on_down(_event: tkinter.Event) -> str:
        yview_scroll(3, "units")
        return "break"

    widget.bind("<MouseWheel>", on_wheel, add="+")
    widget.bind("<Button-4>", on_up, add="+")
    widget.bind("<Button-5>", on_down, add="+")


def _wheel_delta_units(event: tkinter.Event) -> int:
    """Signed integer scroll steps (positive = scroll down / right on Windows)."""
    if sys.platform == "darwin":
        return -1 if event.delta > 0 else 1
    d = getattr(event, "delta", 0) or 0
    if d:
        return int(-1 * (d / 120))
    return 0


def _preview_wheel_fractional_steps(event: tkinter.Event) -> float:
    """
    Signed smooth zoom steps for preview: positive = zoom in (scroll up on Windows).
    Uses raw delta so trackpads / high-res wheels move zoom continuously.
    """
    d = float(getattr(event, "delta", 0) or 0)
    if abs(d) < 1e-9:
        return 0.0
    if sys.platform == "darwin":
        return d / 48.0
    return d / 120.0


def _event_shift_down(event: tkinter.Event) -> bool:
    st = getattr(event, "state", 0) or 0
    return (st & 0x0001) != 0


def _event_ctrl_down(event: tkinter.Event) -> bool:
    st = getattr(event, "state", 0) or 0
    return (st & 0x0004) != 0


def _event_alt_down(event: tkinter.Event) -> bool:
    """Alt / Option — mask varies slightly by platform."""
    st = getattr(event, "state", 0) or 0
    return (st & 0x20000) != 0 or (st & 0x0008) != 0 or (st & 0x80000) != 0


def _resolve_icon_path() -> str | None:
    """icon.ico next to the script, PyInstaller bundle (_MEIPASS), or exe directory."""
    candidates: list[str] = []
    if getattr(sys, "frozen", False):
        meipass = getattr(sys, "_MEIPASS", None)
        if meipass:
            candidates.append(os.path.join(meipass, "icon.ico"))
        exedir = os.path.dirname(os.path.abspath(sys.executable))
        candidates.append(os.path.join(exedir, "icon.ico"))
    here = os.path.dirname(os.path.abspath(__file__))
    candidates.append(os.path.join(here, "icon.ico"))
    for path in candidates:
        if path and os.path.isfile(path):
            try:
                return os.path.normpath(path)
            except (OSError, ValueError):
                return path
    return None


