def _windows_volume_caption(drive_with_colon: str) -> str:
    """Best-effort friendly drive label, e.g. ``My Data (D:)``; falls back to ``D:\\``."""
    d = (drive_with_colon or "").strip()
    if not d:
        return d
    root = d.rstrip("\\/") + "\\"
    if sys.platform != "win32":
        return root
    try:
        import ctypes

        buf = ctypes.create_unicode_buffer(256)
        if ctypes.windll.kernel32.GetVolumeInformationW(
            ctypes.c_wchar_p(root), buf, len(buf), None, None, None, None, 0
        ):
            label = buf.value.strip()
            letter = d.rstrip("\\/")[:2] if len(d) >= 2 else d
            if label:
                return f"{label} ({letter})"
    except Exception:
        pass
    return root


def fs_breadcrumb_segments(abs_dir: str) -> list[tuple[str, str]]:
    """Return ``(label, absolute_path)`` from volume/root through ``abs_dir``."""
    if not abs_dir:
        return []
    raw = os.path.normpath(abs_dir)
    if sys.platform == "win32" and raw.startswith("\\\\") and not raw.startswith("\\\\?\\"):
        body = raw[2:]
        parts = [p for p in body.split("\\") if p]
        if len(parts) < 2:
            return [(raw, raw)]
        base = "\\\\" + parts[0] + "\\" + parts[1]
        out: list[tuple[str, str]] = [(parts[0] + " · " + parts[1], base)]
        cur = base
        for name in parts[2:]:
            cur = cur + "\\" + name
            out.append((name, cur))
        return out
    ap = os.path.abspath(raw)
    if not os.path.isdir(ap):
        return []
    if os.name == "nt":
        drive, tail = os.path.splitdrive(ap)
        if drive:
            root = drive + "\\"
            bits = [b for b in tail.lstrip(os.sep).split(os.sep) if b]
            cap = _windows_volume_caption(drive)
            crumbs: list[tuple[str, str]] = [(cap, root)]
            cur = root
            for b in bits:
                cur = os.path.join(cur, b)
                crumbs.append((b, cur))
            return crumbs
        return [(os.path.basename(ap.rstrip(os.sep)) or ap, ap)]
    if ap == os.path.abspath(os.sep):
        return [(os.sep, ap)]
    parts = [p for p in ap.split(os.sep) if p]
    crumbs = []
    cur = os.path.abspath(os.sep)
    for name in parts:
        cur = os.path.join(cur, name)
        crumbs.append((name, cur))
    return crumbs


class Tooltip:
    """Lightweight hover tooltip for any Tkinter widget.

    Usage::

        Tooltip(widget, "Back to previous folder (Alt+Left)")
    """

    _DELAY_MS  = 600    # ms before tooltip appears
    _SHOW_MS   = 4000   # ms before it auto-hides
    _PAD       = (SP_8, SP_4)

    def __init__(self, widget: tkinter.Widget, text: str) -> None:
        self._widget = widget
        self._text   = text
        self._win: tkinter.Toplevel | None = None
        self._after_show: str | None = None
        self._after_hide: str | None = None
        widget.bind("<Enter>",    self._on_enter,  add="+")
        widget.bind("<Leave>",    self._on_leave,  add="+")
        widget.bind("<Button-1>", self._on_leave,  add="+")
        widget.bind("<Destroy>",  self._on_destroy, add="+")

    # ── public ────────────────────────────────────────────────────────────────

    def update_text(self, text: str) -> None:
        self._text = text
        if self._win is not None:
            try:
                self._win.children.get("!label") and None  # type guard
                for w in self._win.winfo_children():
                    if isinstance(w, tkinter.Label):
                        w.configure(text=text)
            except tkinter.TclError:
                pass

    # ── internals ─────────────────────────────────────────────────────────────

    def _on_enter(self, event: tkinter.Event | None = None) -> None:
        self._cancel_pending()
        self._after_show = self._widget.after(self._DELAY_MS, self._show)

    def _on_leave(self, event: tkinter.Event | None = None) -> None:
        self._cancel_pending()
        self._hide()

    def _on_destroy(self, event: tkinter.Event | None = None) -> None:
        self._cancel_pending()
        self._hide()

    def _cancel_pending(self) -> None:
        if self._after_show is not None:
            try:
                self._widget.after_cancel(self._after_show)
            except (ValueError, tkinter.TclError):
                pass
            self._after_show = None
        if self._after_hide is not None:
            try:
                self._widget.after_cancel(self._after_hide)
            except (ValueError, tkinter.TclError):
                pass
            self._after_hide = None

    def _show(self) -> None:
        self._hide()
        try:
            self._win = tkinter.Toplevel(self._widget)
        except tkinter.TclError:
            return
        self._win.wm_overrideredirect(True)
        self._win.attributes("-topmost", True)
        lbl = tkinter.Label(
            self._win, text=self._text,
            font=FONT_XS,
            bg="#fffbe6", fg=SFM_TEXT,
            relief="solid", borderwidth=1,
            padx=self._PAD[0], pady=self._PAD[1],
            wraplength=320,
        )
        lbl.pack()
        self._win.update_idletasks()
        # Position just below the widget
        try:
            wx = self._widget.winfo_rootx()
            wy = self._widget.winfo_rooty() + self._widget.winfo_height() + 4
            sw = self._win.winfo_screenwidth()
            tw = self._win.winfo_width()
            x  = min(wx, sw - tw - 4)
            self._win.geometry(f"+{max(0, x)}+{max(0, wy)}")
        except tkinter.TclError:
            pass
        self._after_hide = self._widget.after(self._SHOW_MS, self._hide)

    def _hide(self) -> None:
        if self._win is not None:
            try:
                self._win.destroy()
            except tkinter.TclError:
                pass
            self._win = None


