# ---------------------------------------------------------------------------
# A4 page placer: white A4 + draggable selection (PDF page 1 or image), no I/O dialogs
# ---------------------------------------------------------------------------

_A4_PAGE_PIX_W = 2480
_A4_PAGE_PIX_H = 3508
_A4_PLACER_IMAGE_EXT = frozenset(
    {".jpg", ".jpeg", ".png", ".bmp", ".tif", ".tiff", ".webp", ".gif"}
)



# ---------------------------------------------------------------------------
# Native Windows file-type icon extraction (used by FilesWorkspaceFrame)
# ---------------------------------------------------------------------------

def _windows_extract_file_icon(ext: str, *, size: int = 16):
    """Return a PIL ``Image`` of the Windows native icon for a file extension.

    Uses shell32's ``SHGetFileInfoW`` with ``SHGFI_USEFILEATTRIBUTES`` so we
    only need the extension string — no real file required. Falls back
    through pywin32 → ctypes paths and returns ``None`` on any failure
    (non-Windows, missing deps, unusual permissions, etc.) so the caller
    can use a generic icon.
    """
    if sys.platform != "win32":
        return None
    if not ext:
        ext = ".file"
    elif not ext.startswith("."):
        ext = "." + ext

    try:
        from PIL import Image  # type: ignore
    except ImportError:
        return None

    try:
        import ctypes
        from ctypes import wintypes
    except (ImportError, OSError):
        return None

    SHGFI_ICON = 0x000000100
    SHGFI_USEFILEATTRIBUTES = 0x000000010
    SHGFI_SMALLICON = 0x000000001
    SHGFI_LARGEICON = 0x000000000
    FILE_ATTRIBUTE_NORMAL = 0x00000080

    class SHFILEINFO(ctypes.Structure):
        _fields_ = [
            ("hIcon", wintypes.HICON),
            ("iIcon", ctypes.c_int),
            ("dwAttributes", wintypes.DWORD),
            ("szDisplayName", wintypes.WCHAR * 260),
            ("szTypeName", wintypes.WCHAR * 80),
        ]

    shfi = SHFILEINFO()
    flags = SHGFI_ICON | SHGFI_USEFILEATTRIBUTES | (
        SHGFI_SMALLICON if size <= 16 else SHGFI_LARGEICON
    )
    fake_path = "x" + ext  # extension-only lookup

    try:
        shell32 = ctypes.windll.shell32
        user32 = ctypes.windll.user32
    except (AttributeError, OSError):
        return None

    res = shell32.SHGetFileInfoW(
        fake_path,
        FILE_ATTRIBUTE_NORMAL,
        ctypes.byref(shfi),
        ctypes.sizeof(shfi),
        flags,
    )
    if not res or not shfi.hIcon:
        return None

    pil_img = None
    try:
        # Preferred: pywin32 — produces clean RGBA with alpha.
        try:
            import win32gui
            import win32ui
            import win32con  # noqa: F401  (kept for clarity / parity with snippets)
        except ImportError:
            win32gui = None  # type: ignore[assignment]
            win32ui = None  # type: ignore[assignment]

        if win32gui is not None and win32ui is not None:
            try:
                screen_dc_handle = win32gui.GetDC(0)
                screen_dc = win32ui.CreateDCFromHandle(screen_dc_handle)
                hbmp = win32ui.CreateBitmap()
                hbmp.CreateCompatibleBitmap(screen_dc, size, size)
                mem_dc = screen_dc.CreateCompatibleDC()
                old = mem_dc.SelectObject(hbmp)
                # Transparent fill before drawing the icon.
                brush = win32gui.GetStockObject(0)  # WHITE_BRUSH=0; fine because we use mask
                mem_dc.FillSolidRect((0, 0, size, size), 0xFFFFFF)
                win32gui.DrawIconEx(
                    mem_dc.GetSafeHdc(), 0, 0, shfi.hIcon, size, size, 0, 0, 0x0003
                )
                bmpinfo = hbmp.GetInfo()
                bmpstr = hbmp.GetBitmapBits(True)
                pil_img = Image.frombuffer(
                    "RGB",
                    (bmpinfo["bmWidth"], bmpinfo["bmHeight"]),
                    bmpstr,
                    "raw",
                    "BGRX",
                    0,
                    1,
                )
                # Treat pure white as transparent so the tree's row striping
                # shows through (most icons have a true alpha mask which we'd
                # need GetIconInfo for — this approximation is good enough
                # for the small 16x16 size).
                pil_img = pil_img.convert("RGBA")
                datas = pil_img.getdata()
                new_data = []
                for px in datas:
                    if px[0] >= 250 and px[1] >= 250 and px[2] >= 250:
                        new_data.append((255, 255, 255, 0))
                    else:
                        new_data.append(px)
                pil_img.putdata(new_data)
                mem_dc.SelectObject(old)
                mem_dc.DeleteDC()
                win32gui.ReleaseDC(0, screen_dc_handle)
                win32gui.DeleteObject(hbmp.GetHandle())
            except Exception:
                pil_img = None
    finally:
        try:
            user32.DestroyIcon(shfi.hIcon)
        except Exception:
            pass

    return pil_img


