def _load_pil_from_pdf_or_image_path(path: str):
    """Return PIL RGB image for first PDF page or raster file; None on failure."""
    from PIL import Image

    ext = os.path.splitext(path)[1].lower()
    if ext == ".pdf":
        fitz = fo.get_fitz()
        if not fitz:
            return None
        try:
            doc = fitz.open(path)
        except OSError:
            return None
        try:
            if doc.page_count < 1:
                return None
            page = doc[0]
            zoom = 300.0 / 72.0
            mat = fitz.Matrix(zoom, zoom)
            pix = page.get_pixmap(matrix=mat, alpha=False, colorspace=fitz.csRGB)
            return Image.frombytes("RGB", [pix.width, pix.height], pix.samples)
        finally:
            doc.close()
    if ext in _A4_PLACER_IMAGE_EXT:
        try:
            return Image.open(path).convert("RGB")
        except OSError:
            return None
    return None


def _render_pdf_tree_thumbnail(
    path: str,
    *,
    box: tuple[int, int] = (28, 36),
    badge_text: str | None = None,
):
    """Return a small first-page PDF thumbnail PIL image for the file tree/gallery."""
    fitz = fo.get_fitz()
    if not fitz:
        return None
    try:
        from PIL import Image, ImageOps, ImageDraw, ImageFont
    except ImportError:
        return None

    # Reuse the shared document cache (do NOT close it) so building a gallery of
    # many PDFs doesn't reopen/parse the same files repeatedly.
    doc = fo.get_cached_fitz_doc(path)
    if doc is None:
        return None
    try:
        if doc.page_count < 1:
            return None
        page = doc[0]
        # Render at ~2.5x the on-screen tile size, then downsample with LANCZOS so
        # the page looks crisp like the Combine PDFs organizer (instead of soft).
        bw_t, bh_t = box
        rect = page.rect
        pw = float(rect.width) or 1.0
        ph = float(rect.height) or 1.0
        ss = 2.5
        scale = min((bw_t * ss) / pw, (bh_t * ss) / ph)
        scale = max(0.3, min(scale, 4.0))
        mat = fitz.Matrix(scale, scale)
        pix = page.get_pixmap(matrix=mat, alpha=False, colorspace=fitz.csRGB)
        src = Image.frombytes("RGB", [pix.width, pix.height], pix.samples)
    except Exception:
        return None

    bw, bh = box
    page_img = ImageOps.contain(src, (max(1, bw - 4), max(1, bh - 4)), Image.Resampling.LANCZOS)
    card = Image.new("RGBA", (bw, bh), (255, 255, 255, 0))
    x = (bw - page_img.width) // 2
    y = (bh - page_img.height) // 2
    card.paste(page_img.convert("RGBA"), (x, y))
    draw = ImageDraw.Draw(card)
    draw.rounded_rectangle([1, 1, bw - 2, bh - 2], radius=3, fill=None, outline="#94a3b8", width=1)
    draw.line([4, 6, bw - 5, 6], fill="#e2e8f0", width=1)
    if badge_text:
        font_px = max(9, min(18, int(round(min(bw, bh) * 0.12))))
        font = None
        win = os.environ.get("WINDIR", r"C:\Windows")
        fonts_dir = os.path.join(win, "Fonts")
        for name in ("segoeui.ttf", "arial.ttf", "tahoma.ttf", "calibri.ttf"):
            try:
                probe = os.path.join(fonts_dir, name)
                if os.path.isfile(probe):
                    font = ImageFont.truetype(probe, font_px)
                    break
            except OSError:
                continue
        if font is None:
            try:
                font = ImageFont.load_default()
            except OSError:
                font = None
        if font is not None:
            tb = draw.textbbox((0, 0), badge_text, font=font)
            tw = max(1, tb[2] - tb[0])
            th = max(1, tb[3] - tb[1])
            pad_x = max(4, int(round(bw * 0.05)))
            pad_y = max(2, int(round(bh * 0.03)))
            bx1 = max(3, bw - tw - pad_x * 2 - 4)
            by1 = max(3, bh - th - pad_y * 2 - 4)
            bx2 = bw - 3
            by2 = bh - 3
            draw.rounded_rectangle(
                [bx1, by1, bx2, by2],
                radius=max(4, int(round(min(bw, bh) * 0.06))),
                fill=(15, 23, 42, 210),
            )
            tx = bx1 + pad_x - tb[0]
            ty = by1 + pad_y - tb[1]
            draw.text((tx, ty), badge_text, fill="#f8fafc", font=font)
    return card


def _render_pdf_page_direct(
    path: str, page_index: int, max_w: int, max_h: int, max_zoom: float = 4.0,
):
    """Render one PDF page to a PIL Image using a *fresh* (non-cached) fitz document.

    Safe to call from a background thread — does NOT touch the shared LRU cache,
    so there is no risk of cache eviction racing with an in-progress render.
    """
    try:
        fitz = fo.get_fitz()
        PIL_Image = fo.get_pillow()
        if not fitz or not PIL_Image:
            return None
        # _fitz_open_document handles long / non-ASCII paths via a byte-stream fallback.
        doc = fo._fitz_open_document(fitz, path)
        if doc is None:
            return None
        try:
            if page_index < 0 or page_index >= len(doc):
                return None
            pg = doc.load_page(page_index)
            r = pg.rect
            pw = max(float(r.width), 1.0)
            ph_ = max(float(r.height), 1.0)
            zoom = min(float(max_w) / pw, float(max_h) / ph_, float(max_zoom))
            if not (zoom > 0 and zoom == zoom):   # NaN / negative guard
                zoom = 1.0
            mat = fitz.Matrix(zoom, zoom)
            pix = pg.get_pixmap(matrix=mat, alpha=False, colorspace=fitz.csRGB)
            return PIL_Image.frombytes("RGB", [pix.width, pix.height], pix.samples)
        finally:
            try:
                doc.close()
            except Exception:
                pass
    except Exception:
        return None


class A4PagePlacerDialog(Toplevel):
    """Full-window, Photoshop-style A4 sheet editor.

    A white A4 page with a 1-inch grid, page border and 1-inch margin guide. The
    document sits in a bounding box that can be moved and resized via 8 handles
    (4 corners + 4 edges), with editor-standard modifiers:
      • Shift           – keep aspect ratio (anchored to the opposite side)
      • Alt             – resize from the center (symmetric)
      • Shift+Alt       – keep ratio AND resize from the center
    Export writes a 300 DPI PDF.
    """

    _HANDLE_HALF = 7
    _MIN_DOC_L = 48
    _DPI = 300
    _MARGIN_PX = 300  # 1 inch @ 300 DPI
    _GRID_PX = 300    # 1-inch grid spacing
    # Default box aspect 88:125 (W:H), centered on logical A4
    _PROFILE_W = 88
    _PROFILE_H = 125

    @staticmethod
    def _fit_size_in_max_ratio(max_w: int, max_h: int, rw: int, rh: int) -> tuple[int, int]:
        ar = rw / float(rh)
        dw = min(float(max_w), float(max_h) * ar)
        dh = dw / ar
        if dh > max_h:
            dh = float(max_h)
            dw = dh * ar
        return max(1, int(round(dw))), max(1, int(round(dh)))

    def __init__(self, master: tkinter.Misc, pil_image, basename: str, source_path: str | None = None) -> None:
        super().__init__(master)
        self.title(f"A4 page — {basename}")
        self._basename = basename
        # Folder to auto-save the exported A4 PDF into (next to the source file).
        self._source_dir = (
            os.path.dirname(os.path.abspath(source_path)) if source_path else os.getcwd()
        )
        self._pil_source = pil_image.copy().convert("RGB")
        self._photo: object | None = None
        self._photo_key: tuple[int, int] | None = None
        # Page→canvas transform (recomputed each redraw to fill the window).
        self._scale = 0.2
        self._ox = 0.0
        self._oy = 0.0
        # Logical rect on A4: [lx, ly, lw, lh] in full-res page pixels
        self._lr: list[int] = self._initial_centered_profile_rect()
        self._drag_mode: str | None = None
        self._drag_data: dict[str, float | int] | None = None
        self._resize_anchor: dict | None = None
        self._configure_job = None
        self._show_grid = BooleanVar(value=True)
        self._show_margin = BooleanVar(value=True)
        self._snap_on = BooleanVar(value=True)
        self._snap_lines: list[tuple[str, float]] = []
        self._snap_grid_mm: float = 5.0   # mm per grid line (default 5 mm)

        self.configure(bg="#3a3f44")
        fr = tkinter.Frame(self, bg="#3a3f44")
        fr.pack(fill=BOTH, expand=True)

        # ── All controls live in the top toolbar ─────────────────────────────
        topbar = tkinter.Frame(fr, bg="#2f3338")
        topbar.pack(side=TOP, fill=X)

        ttk.Button(topbar, text="88 : 125", command=self._reset_profile_rect).pack(side=LEFT, padx=(8, 0), pady=4)
        ttk.Button(topbar, text="Fit to margin", command=self._fit_to_margin).pack(side=LEFT, padx=(4, 0), pady=4)

        _sep1 = tkinter.Frame(topbar, bg="#4b5158", width=1)
        _sep1.pack(side=LEFT, fill=Y, padx=8, pady=4)

        tkinter.Label(topbar, text="Align:", bg="#2f3338", fg="#cbd5e1", font=("Segoe UI", 9)).pack(side=LEFT, padx=(0, 4))
        for _txt, _mode in (
            ("Left", "left"),
            ("Ctr", "centerh"),
            ("Right", "right"),
            ("Top", "top"),
            ("Mid", "middlev"),
            ("Bot", "bottom"),
        ):
            ttk.Button(
                topbar, text=_txt, width=4, command=lambda mm=_mode: self._align(mm),
            ).pack(side=LEFT, padx=1, pady=4)

        _sep2 = tkinter.Frame(topbar, bg="#4b5158", width=1)
        _sep2.pack(side=LEFT, fill=Y, padx=8, pady=4)

        for _label, _var in (("Snap", self._snap_on), ("Grid", self._show_grid), ("Margin", self._show_margin)):
            tkinter.Checkbutton(
                topbar, text=_label, variable=_var, command=self._redraw,
                bg="#2f3338", fg="#e5e7eb", selectcolor="#2f3338",
                activebackground="#2f3338", activeforeground="#ffffff",
                highlightthickness=0, font=("Segoe UI", 9),
            ).pack(side=LEFT, padx=(0, 4), pady=2)

        # Grid-size picker
        _sep3 = tkinter.Frame(topbar, bg="#4b5158", width=1)
        _sep3.pack(side=LEFT, fill=Y, padx=(8, 4), pady=4)
        tkinter.Label(topbar, text="Grid:", bg="#2f3338", fg="#cbd5e1",
                      font=("Segoe UI", 9)).pack(side=LEFT, padx=(0, 3))
        self._snap_grid_var = StringVar(value="5 mm")
        _grid_sizes = ["0.5 mm", "1 mm", "2 mm", "5 mm", "10 mm", "25 mm (1″)"]
        _grid_cb = ttk.Combobox(topbar, textvariable=self._snap_grid_var,
                                values=_grid_sizes, state="readonly", width=11)
        _grid_cb.pack(side=LEFT, pady=2)

        def _on_grid_size_change(_e=None):
            txt = self._snap_grid_var.get()
            try:
                self._snap_grid_mm = float(txt.split()[0])
            except (ValueError, IndexError):
                self._snap_grid_mm = 5.0
            self._redraw()

        _grid_cb.bind("<<ComboboxSelected>>", _on_grid_size_change)

        # OK (auto-saves) + Close on the right.
        ttk.Button(topbar, text="Close", command=self.destroy).pack(side=RIGHT, padx=(4, 8), pady=4)
        self._ok_btn = ttk.Button(topbar, text="OK", command=self._ok)
        self._ok_btn.pack(side=RIGHT, padx=(0, 0), pady=4)

        # Hint line.
        tkinter.Label(
            fr,
            text=("Drag to move · corner/edge handles resize · Shift = keep ratio · "
                  "Alt = from center · Shift+Alt = both · Enter = OK"),
            bg="#23262a", fg="#9ca3af", font=("Segoe UI", 8), anchor=W,
        ).pack(side=TOP, fill=X, padx=0, pady=0)

        self._canvas = tkinter.Canvas(
            fr, bg="#3a3f44", highlightthickness=0, borderwidth=0,
        )
        self._canvas.pack(side=TOP, fill=BOTH, expand=True)
        self._canvas.bind("<ButtonPress-1>", self._on_canvas_press)
        self._canvas.bind("<B1-Motion>", self._on_canvas_motion)
        self._canvas.bind("<ButtonRelease-1>", self._on_canvas_release)
        self._canvas.bind("<Motion>", self._on_canvas_hover)
        self._canvas.bind("<Configure>", self._on_canvas_configure)
        self.bind("<Return>", lambda _e: self._ok())
        self.bind("<KP_Enter>", lambda _e: self._ok())
        self.bind("<Escape>", lambda _e: self.destroy())

        self.transient(master)
        self.resizable(True, True)
        self.minsize(720, 600)
        self.update_idletasks()
        if sys.platform == "win32":
            try:
                self.state("zoomed")
            except tkinter.TclError:
                pass
        else:
            try:
                sw = self.winfo_screenwidth()
                sh = self.winfo_screenheight()
                self.geometry(f"{max(720, sw - 80)}x{max(600, sh - 120)}+20+20")
            except tkinter.TclError:
                pass
        self.after(60, self._redraw)

    def _initial_centered_profile_rect(self) -> list[int]:
        aw, ah = _A4_PAGE_PIX_W, _A4_PAGE_PIX_H
        max_w, max_h = int(aw * 0.88), int(ah * 0.88)
        lw, lh = self._fit_size_in_max_ratio(max_w, max_h, self._PROFILE_W, self._PROFILE_H)
        lx = (aw - lw) // 2
        ly = (ah - lh) // 2
        return [lx, ly, lw, lh]

    def _reset_profile_rect(self) -> None:
        self._lr = self._initial_centered_profile_rect()
        self._redraw()

    def _fit_to_margin(self) -> None:
        """Scale the document to fit inside the 1-inch margins, keeping its ratio."""
        aw, ah = _A4_PAGE_PIX_W, _A4_PAGE_PIX_H
        avail_w = aw - 2 * self._MARGIN_PX
        avail_h = ah - 2 * self._MARGIN_PX
        sw, sh = self._pil_source.size
        nw, nh = self._fit_size_in_max_ratio(avail_w, avail_h, max(1, sw), max(1, sh))
        lx = (aw - nw) // 2
        ly = (ah - nh) // 2
        self._lr[:] = [lx, ly, nw, nh]
        self._redraw()

    def _align(self, mode: str) -> None:
        """Align the document box to the 1-inch margins (edges) / page center."""
        aw, ah = _A4_PAGE_PIX_W, _A4_PAGE_PIX_H
        mg = self._MARGIN_PX
        lx, ly, lw, lh = self._clamp_rect()
        if mode == "left":
            lx = mg
        elif mode == "right":
            lx = aw - mg - lw
        elif mode == "centerh":
            lx = (aw - lw) // 2
        elif mode == "top":
            ly = mg
        elif mode == "bottom":
            ly = ah - mg - lh
        elif mode == "middlev":
            ly = (ah - lh) // 2
        self._lr[:] = [lx, ly, lw, lh]
        self._redraw()

    def _snap_grid_px(self) -> float:
        """Current snap-grid step in A4 page pixels."""
        mm = max(0.5, getattr(self, "_snap_grid_mm", 5.0))
        return mm * (_A4_PAGE_PIX_W / 210.0)

    def _snap_targets_x(self) -> list[float]:
        aw = _A4_PAGE_PIX_W
        targets = [0.0, float(self._MARGIN_PX), aw / 2.0, float(aw - self._MARGIN_PX), float(aw)]
        step = self._snap_grid_px()
        x = step
        while x < aw:
            targets.append(x)
            x += step
        return targets

    def _snap_targets_y(self) -> list[float]:
        ah = _A4_PAGE_PIX_H
        targets = [0.0, float(self._MARGIN_PX), ah / 2.0, float(ah - self._MARGIN_PX), float(ah)]
        step = self._snap_grid_px()
        y = step
        while y < ah:
            targets.append(y)
            y += step
        return targets

    def _snap_threshold(self) -> float:
        # ~8 screen px, converted to logical page pixels.
        return 8.0 / max(self._scale, 0.001)

    def _snap_one(self, value: float, targets: list[float]) -> tuple[float, float | None]:
        """Return (snapped_value, snapped_target_or_None)."""
        thr = self._snap_threshold()
        best_t = None
        best_d = thr
        for t in targets:
            d = abs(t - value)
            if d <= best_d:
                best_d = d
                best_t = t
        if best_t is None:
            return value, None
        return best_t, best_t

    def _clamp_rect(self) -> tuple[int, int, int, int]:
        lx, ly, lw, lh = self._lr
        aw, ah = _A4_PAGE_PIX_W, _A4_PAGE_PIX_H
        lw = max(self._MIN_DOC_L, min(int(lw), aw))
        lh = max(self._MIN_DOC_L, min(int(lh), ah))
        lx = max(0, min(int(lx), aw - lw))
        ly = max(0, min(int(ly), ah - lh))
        self._lr[:] = [lx, ly, lw, lh]
        return lx, ly, lw, lh

    def _recompute_layout(self) -> None:
        cw = max(self._canvas.winfo_width(), 50)
        ch = max(self._canvas.winfo_height(), 50)
        pad = 28
        aw, ah = _A4_PAGE_PIX_W, _A4_PAGE_PIX_H
        scale = min((cw - 2 * pad) / aw, (ch - 2 * pad) / ah)
        self._scale = max(scale, 0.02)
        pw = aw * self._scale
        ph = ah * self._scale
        self._ox = (cw - pw) / 2.0
        self._oy = (ch - ph) / 2.0

    def _to_logic_xy(self, cx: float, cy: float) -> tuple[float, float]:
        return (cx - self._ox) / self._scale, (cy - self._oy) / self._scale

    def _to_canvas_xy(self, lx: float, ly: float) -> tuple[float, float]:
        return self._ox + lx * self._scale, self._oy + ly * self._scale

    def _on_canvas_configure(self, _event: tkinter.Event | None = None) -> None:
        job = self._configure_job
        if job is not None:
            try:
                self.after_cancel(job)
            except (ValueError, tkinter.TclError):
                pass
        self._configure_job = self.after(60, self._redraw)

    def _redraw(self) -> None:
        from PIL import Image, ImageTk

        self._configure_job = None
        self._recompute_layout()
        lx, ly, lw, lh = self._clamp_rect()
        c = self._canvas
        c.delete("all")
        aw, ah = _A4_PAGE_PIX_W, _A4_PAGE_PIX_H

        px0, py0 = self._to_canvas_xy(0, 0)
        px1, py1 = self._to_canvas_xy(aw, ah)
        # Page shadow + white page.
        c.create_rectangle(px0 + 6, py0 + 6, px1 + 6, py1 + 6, fill="#23262a", outline="", tags=("page",))
        c.create_rectangle(px0, py0, px1, py1, fill="#ffffff", outline="#1f2937", width=1, tags=("page",))

        # Grid lines (size set by grid-size picker in toolbar).
        if self._show_grid.get():
            gx = self._snap_grid_px()
            # Clamp grid lines to at least 4 screen-px apart to avoid visual clutter
            screen_step = gx * self._scale
            if screen_step >= 4:
                x = gx
                while x < aw:
                    cxg = self._ox + x * self._scale
                    c.create_line(cxg, py0, cxg, py1, fill="#e2e8f0", tags=("grid",))
                    x += gx
                y = gx
                while y < ah:
                    cyg = self._oy + y * self._scale
                    c.create_line(px0, cyg, px1, cyg, fill="#e2e8f0", tags=("grid",))
                    y += gx

        # 1-inch margin guide.
        if self._show_margin.get():
            mx0, my0 = self._to_canvas_xy(self._MARGIN_PX, self._MARGIN_PX)
            mx1, my1 = self._to_canvas_xy(aw - self._MARGIN_PX, ah - self._MARGIN_PX)
            c.create_rectangle(mx0, my0, mx1, my1, outline="#06b6d4", dash=(6, 4), width=1, tags=("margin",))

        # Active snap guides (magenta) while dragging.
        for kind, val in self._snap_lines:
            if kind == "v":
                sx = self._ox + val * self._scale
                c.create_line(sx, py0, sx, py1, fill="#ec4899", width=1, tags=("snapline",))
            else:
                sy = self._oy + val * self._scale
                c.create_line(px0, sy, px1, sy, fill="#ec4899", width=1, tags=("snapline",))

        # Document preview (resize source straight to display size; cache by size).
        doc_disp_w = max(1, int(round(lw * self._scale)))
        doc_disp_h = max(1, int(round(lh * self._scale)))
        cx0, cy0 = self._to_canvas_xy(lx, ly)
        cx0 = int(round(cx0))
        cy0 = int(round(cy0))
        key = (doc_disp_w, doc_disp_h)
        if key != self._photo_key or self._photo is None:
            thumb = self._pil_source.resize((doc_disp_w, doc_disp_h), Image.Resampling.LANCZOS)
            self._photo = ImageTk.PhotoImage(thumb)
            self._photo_key = key
        c.create_image(cx0, cy0, image=self._photo, anchor="nw", tags=("doc",))

        # Bounding box.
        c.create_rectangle(
            cx0, cy0, cx0 + doc_disp_w, cy0 + doc_disp_h,
            outline="#2563eb", width=2, dash=(5, 4), tags=("doc",),
        )
        # Handles: 4 corners + 4 edge midpoints.
        hh = self._HANDLE_HALF
        midx = cx0 + doc_disp_w // 2
        midy = cy0 + doc_disp_h // 2
        handles = {
            "nw": (cx0, cy0),
            "ne": (cx0 + doc_disp_w, cy0),
            "sw": (cx0, cy0 + doc_disp_h),
            "se": (cx0 + doc_disp_w, cy0 + doc_disp_h),
            "n": (midx, cy0),
            "s": (midx, cy0 + doc_disp_h),
            "w": (cx0, midy),
            "e": (cx0 + doc_disp_w, midy),
        }
        for tag, (hx, hy) in handles.items():
            c.create_rectangle(
                hx - hh, hy - hh, hx + hh, hy + hh,
                outline="#1d4ed8", fill="#eff6ff", width=2,
                tags=("handles", f"h_{tag}"),
            )

    def _hit_handle(self, x: int, y: int) -> str | None:
        t = self._HANDLE_HALF + 4
        # Corners first (priority over edges where they overlap on tiny boxes).
        for tag in ("nw", "ne", "sw", "se", "n", "s", "w", "e"):
            found = self._canvas.find_withtag(f"h_{tag}")
            if not found:
                continue
            b = self._canvas.bbox(found[0])
            if b and b[0] - t <= x <= b[2] + t and b[1] - t <= y <= b[3] + t:
                return tag
        return None

    _CURSOR_FOR_HANDLE = {
        "nw": "size_nw_se", "se": "size_nw_se",
        "ne": "size_ne_sw", "sw": "size_ne_sw",
        "n": "sb_v_double_arrow", "s": "sb_v_double_arrow",
        "w": "sb_h_double_arrow", "e": "sb_h_double_arrow",
    }

    def _on_canvas_hover(self, event: tkinter.Event) -> None:
        if self._drag_mode is not None:
            return
        h = self._hit_handle(event.x, event.y)
        cursor = self._CURSOR_FOR_HANDLE.get(h or "", "")
        if not cursor:
            lx, ly, lw, lh = self._lr
            cx0, cy0 = self._to_canvas_xy(lx, ly)
            dw = lw * self._scale
            dh = lh * self._scale
            if cx0 <= event.x <= cx0 + dw and cy0 <= event.y <= cy0 + dh:
                cursor = "fleur"
        try:
            self._canvas.configure(cursor=cursor)
        except tkinter.TclError:
            pass

    def _on_canvas_press(self, event: tkinter.Event) -> None:
        lx, ly, lw, lh = self._clamp_rect()
        mx, my = event.x, event.y
        h = self._hit_handle(mx, my)
        if h:
            self._drag_mode = "resize"
            self._resize_anchor = {"handle": h, "lx": lx, "ly": ly, "lw": lw, "lh": lh}
            self._drag_data = None
            return
        cx0, cy0 = self._to_canvas_xy(lx, ly)
        dw = lw * self._scale
        dh = lh * self._scale
        if cx0 <= mx <= cx0 + dw and cy0 <= my <= cy0 + dh:
            self._drag_mode = "move"
            self._resize_anchor = None
            mx_l, my_l = self._to_logic_xy(float(mx), float(my))
            self._drag_data = {"lx": lx, "ly": ly, "mx": mx_l, "my": my_l}
            return
        self._drag_mode = None
        self._drag_data = None
        self._resize_anchor = None

    def _apply_resize(
        self, handle: str, mx: float, my: float,
        orig: tuple[int, int, int, int], from_center: bool, keep_ratio: bool,
    ) -> None:
        lx0, ly0, lw0, lh0 = orig
        aw, ah = _A4_PAGE_PIX_W, _A4_PAGE_PIX_H
        m = float(self._MIN_DOC_L)
        ratio = max(0.01, float(lw0) / float(max(lh0, 1)))  # w / h
        cx = lx0 + lw0 / 2.0
        cy = ly0 + lh0 / 2.0

        ctrl_x = handle in ("e", "w", "ne", "nw", "se", "sw")
        ctrl_y = handle in ("n", "s", "ne", "nw", "se", "sw")
        fixed_left = handle in ("e", "ne", "se")    # dragging the right side
        fixed_top = handle in ("s", "sw", "se")     # dragging the bottom side

        # Desired raw sizes from the cursor.
        if ctrl_x:
            if from_center:
                new_w = 2.0 * abs(mx - cx)
            else:
                fx = float(lx0) if fixed_left else float(lx0 + lw0)
                new_w = abs(mx - fx)
        else:
            new_w = float(lw0)
        if ctrl_y:
            if from_center:
                new_h = 2.0 * abs(my - cy)
            else:
                fy = float(ly0) if fixed_top else float(ly0 + lh0)
                new_h = abs(my - fy)
        else:
            new_h = float(lh0)

        if keep_ratio:
            if ctrl_x and ctrl_y:
                s = max(new_w / max(lw0, 1), new_h / max(lh0, 1))
                new_w = lw0 * s
                new_h = lh0 * s
            elif ctrl_x:
                new_h = new_w / ratio
            elif ctrl_y:
                new_w = new_h * ratio

        new_w = max(m, new_w)
        new_h = max(m, new_h)

        # Position.
        if from_center:
            nlx = cx - new_w / 2.0
            nly = cy - new_h / 2.0
        else:
            if ctrl_x:
                nlx = float(lx0) if fixed_left else (float(lx0 + lw0) - new_w)
            else:
                nlx = (cx - new_w / 2.0) if (keep_ratio and ctrl_y) else float(lx0)
            if ctrl_y:
                nly = float(ly0) if fixed_top else (float(ly0 + lh0) - new_h)
            else:
                nly = (cy - new_h / 2.0) if (keep_ratio and ctrl_x) else float(ly0)

        new_w = min(new_w, float(aw))
        new_h = min(new_h, float(ah))
        nlx = max(0.0, min(nlx, aw - new_w))
        nly = max(0.0, min(nly, ah - new_h))
        self._lr[:] = [int(round(nlx)), int(round(nly)), int(round(new_w)), int(round(new_h))]

    def _on_canvas_motion(self, event: tkinter.Event) -> None:
        mx_l, my_l = self._to_logic_xy(float(event.x), float(event.y))
        aw, ah = _A4_PAGE_PIX_W, _A4_PAGE_PIX_H

        if self._drag_mode == "move" and self._drag_data:
            lx = int(self._drag_data["lx"])
            ly = int(self._drag_data["ly"])
            ox = float(self._drag_data["mx"])
            oy = float(self._drag_data["my"])
            lw, lh = self._lr[2], self._lr[3]
            nlx = float(lx + mx_l - ox)
            nly = float(ly + my_l - oy)
            nlx, nly = self._snap_move(nlx, nly, float(lw), float(lh))
            nlx = max(0, min(int(round(nlx)), aw - lw))
            nly = max(0, min(int(round(nly)), ah - lh))
            self._lr[:] = [nlx, nly, lw, lh]
            self._drag_data = {"lx": nlx, "ly": nly, "mx": mx_l, "my": my_l}
            self._redraw()
            return

        if self._drag_mode == "resize" and self._resize_anchor:
            a = self._resize_anchor
            orig = (int(a["lx"]), int(a["ly"]), int(a["lw"]), int(a["lh"]))
            if self._snap_on.get():
                mx_l, my_l = self._snap_resize(str(a["handle"]), mx_l, my_l)
            self._apply_resize(
                str(a["handle"]), mx_l, my_l, orig,
                from_center=_event_alt_down(event),
                keep_ratio=_event_shift_down(event),
            )
            self._redraw()

    def _snap_move(self, nlx: float, nly: float, lw: float, lh: float) -> tuple[float, float]:
        """Snap box edges/center to grid, margins and page center while moving."""
        self._snap_lines = []
        if not self._snap_on.get():
            return nlx, nly
        tx = self._snap_targets_x()
        ty = self._snap_targets_y()
        # X: try left, center, right edges; keep the closest snap.
        candidates_x = ((nlx, 0.0), (nlx + lw / 2.0, lw / 2.0), (nlx + lw, lw))
        best_dx = None
        best_line_x = None
        for edge_val, off in candidates_x:
            snapped, target = self._snap_one(edge_val, tx)
            if target is not None:
                d = snapped - edge_val
                if best_dx is None or abs(d) < abs(best_dx):
                    best_dx = d
                    best_line_x = target
        if best_dx is not None:
            nlx += best_dx
            if best_line_x is not None:
                self._snap_lines.append(("v", best_line_x))
        candidates_y = ((nly, 0.0), (nly + lh / 2.0, lh / 2.0), (nly + lh, lh))
        best_dy = None
        best_line_y = None
        for edge_val, off in candidates_y:
            snapped, target = self._snap_one(edge_val, ty)
            if target is not None:
                d = snapped - edge_val
                if best_dy is None or abs(d) < abs(best_dy):
                    best_dy = d
                    best_line_y = target
        if best_dy is not None:
            nly += best_dy
            if best_line_y is not None:
                self._snap_lines.append(("h", best_line_y))
        return nlx, nly

    def _snap_resize(self, handle: str, mx_l: float, my_l: float) -> tuple[float, float]:
        """Snap the dragged edge/corner to grid, margins and page center."""
        self._snap_lines = []
        if "e" in handle or "w" in handle:
            snapped, target = self._snap_one(mx_l, self._snap_targets_x())
            if target is not None:
                mx_l = snapped
                self._snap_lines.append(("v", target))
        if "n" in handle or "s" in handle:
            snapped, target = self._snap_one(my_l, self._snap_targets_y())
            if target is not None:
                my_l = snapped
                self._snap_lines.append(("h", target))
        return mx_l, my_l

    def _on_canvas_release(self, _event: tkinter.Event) -> None:
        self._drag_mode = None
        self._drag_data = None
        self._resize_anchor = None
        if self._snap_lines:
            self._snap_lines = []
            self._redraw()

    def _ok(self) -> None:
        """Auto-save the composed A4 PDF next to the source (no location prompt)."""
        from PIL import Image

        lx, ly, lw, lh = self._clamp_rect()
        page = Image.new("RGB", (_A4_PAGE_PIX_W, _A4_PAGE_PIX_H), (255, 255, 255))
        doc = self._pil_source.resize((lw, lh), Image.Resampling.LANCZOS)
        page.paste(doc, (lx, ly))
        stem = os.path.splitext(self._basename)[0]
        base_dir = self._source_dir if os.path.isdir(self._source_dir) else os.getcwd()
        path = os.path.join(base_dir, f"{stem}_A4.pdf")
        n = 1
        while os.path.exists(path):
            path = os.path.join(base_dir, f"{stem}_A4_{n}.pdf")
            n += 1
        try:
            page.save(path, "PDF", resolution=300.0)
        except Exception as e:
            messagebox.showerror("A4 PDF", f"Could not save:\n{e}", parent=self)
            return
        try:
            if sys.platform == "win32":
                os.startfile(path)  # type: ignore[attr-defined]
            elif sys.platform == "darwin":
                subprocess.Popen(["open", path], close_fds=True)
            else:
                subprocess.Popen(["xdg-open", path], close_fds=True)
        except OSError:
            pass
        self.destroy()



