class StudentFoldersFrame(ttk.Frame):
    """Paste names, pick destination, generate folders."""

    def __init__(self, parent) -> None:
        super().__init__(parent)
        _s = _load_settings()
        _saved_dest = _s.get("last_destination", "")
        self.destination_path = StringVar(value=_saved_dest if isinstance(_saved_dest, str) and os.path.isdir(_saved_dest) else "")
        self.case_mode = StringVar(value="original")
        self.prefix_var = StringVar(value="")
        self.suffix_var = StringVar(value="")
        self.open_after_var = BooleanVar(value=True)

        self.columnconfigure(0, weight=1)
        self.rowconfigure(0, weight=1)
        self.rowconfigure(1, weight=1)

        self._build_ui()
        # Keep live preview in sync when options change
        self.case_mode.trace_add("write", lambda *_: self._update_live_preview())
        self.prefix_var.trace_add("write", lambda *_: self._update_live_preview())
        self.suffix_var.trace_add("write", lambda *_: self._update_live_preview())
        self.log_message("Paste names, set output folder, Generate.")

    def _build_ui(self) -> None:
        mid = ttk.Frame(self, padding=(16, 14, 16, 8))
        mid.grid(row=0, column=0, sticky=(N, S, W, E))
        mid.columnconfigure(0, weight=1)
        mid.columnconfigure(1, weight=1)
        mid.rowconfigure(0, weight=1)

        left = ttk.LabelFrame(mid, text=" Names ", padding=12, style="Card.TLabelframe")
        left.grid(row=0, column=0, sticky=(N, S, W, E), padx=(0, 8))
        left.rowconfigure(0, weight=1)
        left.columnconfigure(0, weight=1)

        self.names_text = Text(
            left,
            wrap="word",
            font=("Consolas", 11),
            undo=True,
            height=10,
            padx=8,
            pady=8,
            relief="flat",
            highlightthickness=1,
            highlightbackground=SFM_BORDER,
            highlightcolor=SFM_ACCENT,
        )
        self.names_text.grid(row=0, column=0, sticky=(N, S, W, E))
        sy = ttk.Scrollbar(left, orient=VERTICAL, command=self.names_text.yview)
        sy.grid(row=0, column=1, sticky=(N, S))
        self.names_text.configure(yscrollcommand=sy.set)
        _bind_mousewheel_yview(self.names_text, self.names_text.yview_scroll)

        # Live preview strip: shows first few sanitized folder names as you type
        preview_wrap = ttk.LabelFrame(left, text=" Preview (first 5) ", padding=(8, 4), style="Card.TLabelframe")
        preview_wrap.grid(row=1, column=0, columnspan=2, sticky=(W, E), pady=(6, 0))
        preview_wrap.columnconfigure(0, weight=1)
        self._preview_label_var = StringVar(value="— start typing names above —")
        ttk.Label(
            preview_wrap,
            textvariable=self._preview_label_var,
            style="Subtle.TLabel",
            wraplength=340,
            justify="left",
        ).grid(row=0, column=0, sticky=W)
        self._live_preview_job: str | None = None
        self.names_text.bind("<<Modified>>", self._on_names_modified)

        right = ttk.Frame(mid)
        right.grid(row=0, column=1, sticky=(N, S, W, E))
        right.columnconfigure(0, weight=1)

        dest_frame = ttk.LabelFrame(right, text=" Output ", padding=12, style="Card.TLabelframe")
        dest_frame.grid(row=0, column=0, sticky=(W, E), pady=(0, 10))
        dest_frame.columnconfigure(1, weight=1)

        ttk.Label(dest_frame, text="Folder:").grid(row=0, column=0, sticky=W, padx=(0, 8))
        self.dest_entry = ttk.Entry(dest_frame, textvariable=self.destination_path, state="readonly")
        self.dest_entry.grid(row=0, column=1, sticky=(W, E), padx=(0, 8))
        ttk.Button(dest_frame, text="Browse…", command=self.browse_folder).grid(row=0, column=2)

        opts = ttk.LabelFrame(right, text=" Options ", padding=12, style="Card.TLabelframe")
        opts.grid(row=1, column=0, sticky=(W, E), pady=(0, 10))
        opts.columnconfigure(1, weight=1)

        ttk.Label(opts, text="Name format:").grid(row=0, column=0, sticky=W, padx=(0, 8), pady=4)
        fmt_inner = ttk.Frame(opts)
        fmt_inner.grid(row=0, column=1, sticky=W, pady=4)
        for col, (label, val) in enumerate(
            (
                ("Keep original", "original"),
                ("UPPERCASE", "upper"),
                ("lowercase", "lower"),
                ("Title Case", "title"),
                ("Sentence case", "sentence"),
            )
        ):
            ttk.Radiobutton(fmt_inner, text=label, variable=self.case_mode, value=val).grid(
                row=col // 3, column=col % 3, sticky=W, padx=(0, 12), pady=1
            )

        ttk.Label(opts, text="Prefix:").grid(row=1, column=0, sticky=W, padx=(0, 8), pady=4)
        ttk.Entry(opts, textvariable=self.prefix_var).grid(row=1, column=1, sticky=(W, E), pady=4)

        ttk.Label(opts, text="Suffix:").grid(row=2, column=0, sticky=W, padx=(0, 8), pady=4)
        ttk.Entry(opts, textvariable=self.suffix_var).grid(row=2, column=1, sticky=(W, E), pady=4)

        ttk.Checkbutton(
            opts,
            text="Open output folder when done",
            variable=self.open_after_var,
        ).grid(row=3, column=0, columnspan=2, sticky=W, pady=(8, 0))

        bottom = ttk.Frame(self, padding=(16, 8, 16, 16))
        bottom.grid(row=1, column=0, sticky=(W, E, N, S))
        bottom.columnconfigure(0, weight=1)
        bottom.rowconfigure(1, weight=1)

        btn_row = ttk.Frame(bottom)
        btn_row.grid(row=0, column=0, sticky=(W, E), pady=(0, 8))

        ttk.Button(btn_row, text="Clear", command=self.clear_names).pack(side=LEFT, padx=(0, 6))
        ttk.Button(btn_row, text="Paste", command=self.paste_names_from_clipboard).pack(side=LEFT, padx=(0, 6))
        ttk.Button(btn_row, text="Sample", command=self.insert_sample_names).pack(side=LEFT, padx=(0, 6))
        ttk.Button(btn_row, text="Export log…", command=self.export_log).pack(side=LEFT, padx=(0, 6))
        self._name_count_var = StringVar(value="0 names")
        ttk.Label(btn_row, textvariable=self._name_count_var, style="Subtle.TLabel").pack(side=LEFT, padx=(10, 0))
        ttk.Button(
            btn_row,
            text="Generate",
            style="Accent.TButton",
            command=self.on_generate_clicked,
        ).pack(side=RIGHT)

        log_frame = ttk.LabelFrame(bottom, text=" Log ", padding=10, style="Card.TLabelframe")
        log_frame.grid(row=1, column=0, sticky=(N, S, W, E))
        log_frame.columnconfigure(0, weight=1)
        log_frame.rowconfigure(0, weight=1)

        self.log_text = scrolledtext.ScrolledText(
            log_frame,
            wrap="word",
            font=("Consolas", 9),
            height=8,
            state="disabled",
            padx=8,
            pady=8,
            relief="flat",
            highlightthickness=1,
            highlightbackground=SFM_BORDER,
        )
        self.log_text.grid(row=0, column=0, sticky=(N, S, W, E))
        _bind_mousewheel_yview(self.log_text, self.log_text.yview_scroll)

        self.status_var = StringVar(value="Ready")
        ttk.Label(bottom, textvariable=self.status_var, style="Status.TLabel").grid(row=2, column=0, sticky=W, pady=(6, 0))

    def browse_folder(self) -> None:
        try:
            path = filedialog.askdirectory(title="Select destination folder")
            if path:
                self.destination_path.set(path)
                self.log_message(f"Destination set to: {path}")
                self.status_var.set("Destination selected.")
                # Persist so next launch remembers the folder
                s = _load_settings()
                s["last_destination"] = path
                _save_settings(s)
                _maximize_toplevel(self)
        except Exception as e:
            self.log_message(f"Browse error: {e}")
            messagebox.showerror("Browse", str(e))

    def _on_names_modified(self, _event=None) -> None:
        """Debounced: schedule a live preview refresh 200 ms after last keystroke."""
        self.names_text.edit_modified(False)
        if self._live_preview_job is not None:
            try:
                self.after_cancel(self._live_preview_job)
            except Exception:
                pass
        self._live_preview_job = self.after(200, self._update_live_preview)

    def _update_live_preview(self) -> None:
        self._live_preview_job = None
        try:
            if not self.winfo_exists():
                return
        except tkinter.TclError:
            return
        clean = self.get_clean_names()
        # Update name count
        n = len(clean)
        self._name_count_var.set(f"{n} name{'s' if n != 1 else ''}")
        if not clean:
            self._preview_label_var.set("— start typing names above —")
            return
        preview_names: list[str] = []
        for raw in clean[:5]:
            final, _ = self._build_final_folder_name(raw)
            if final:
                preview_names.append(final)
        extra = len(clean) - 5
        lines = "\n".join(f"  📁 {n}" for n in preview_names)
        if extra > 0:
            lines += f"\n  … +{extra} more"
        self._preview_label_var.set(lines or "— all names invalid after sanitize —")

    def get_clean_names(self) -> list[str]:
        raw = self.names_text.get("1.0", END)
        lines = raw.splitlines()
        seen: set[str] = set()
        result: list[str] = []
        for line in lines:
            name = line.strip()
            if not name:
                continue
            key = name.casefold()
            if key in seen:
                continue
            seen.add(key)
            result.append(name)
        return result

    def sanitize_folder_name(self, name: str) -> tuple[str, bool]:
        original = name
        if not name or not name.strip():
            return "", True
        chars: list[str] = []
        modified = False
        for ch in name:
            if ch in INVALID_WIN_FILENAME_CHARS:
                chars.append("_")
                modified = True
            elif ord(ch) < 32:
                chars.append("_")
                modified = True
            else:
                chars.append(ch)
        s = "".join(chars)
        s = re.sub(r"_+", "_", s)
        s = s.strip(" .")
        if s != original:
            modified = True
        if not s:
            return "", True
        return s, modified

    def _apply_formatting(self, name: str) -> str:
        return apply_text_case(name, self.case_mode.get())

    def _build_final_folder_name(self, clean_name: str) -> tuple[str, list[str]]:
        warnings: list[str] = []
        formatted = self._apply_formatting(clean_name)
        prefix = self.prefix_var.get() or ""
        suffix = self.suffix_var.get() or ""
        combined = f"{prefix}{formatted}{suffix}"
        safe, mod = self.sanitize_folder_name(combined)
        if mod and combined.strip():
            warnings.append(f"Sanitized: {combined!r} → {safe!r}")
        if not safe:
            warnings.append(f"Empty after sanitize, skipped: {clean_name!r}")
        return safe, warnings

    def create_folders(self) -> dict:
        stats = {
            "total_pasted": 0,
            "valid_names": 0,
            "created": 0,
            "existed": 0,
            "invalid_skipped": 0,
            "duplicates_ignored": 0,
        }
        dest = self.destination_path.get().strip()
        if not dest:
            return stats

        raw_lines = self.names_text.get("1.0", END).splitlines()
        stats["total_pasted"] = sum(1 for ln in raw_lines if ln.strip())

        clean = self.get_clean_names()
        non_blank = [ln.strip() for ln in raw_lines if ln.strip()]
        # Pre-sanitize duplicate count (raw-level)
        raw_dupes = max(0, len(non_blank) - len(clean))
        stats["valid_names"] = len(clean)

        # Build final names and deduplicate AFTER sanitization so that two
        # raw names that resolve to the same final folder name are both counted
        # as duplicates rather than silently hitting the "existed" branch.
        seen_final: set[str] = set()
        post_sanitize_dupes = 0
        for clean_name in clean:
            final_name, warns = self._build_final_folder_name(clean_name)
            for w in warns:
                self.log_message(f"  ⚠ {w}")
            if not final_name:
                stats["invalid_skipped"] += 1
                self.log_message(f"SKIP (invalid): {clean_name!r}")
                continue
            final_key = final_name.casefold()
            if final_key in seen_final:
                post_sanitize_dupes += 1
                self.log_message(f"SKIP (duplicate after sanitize): {final_name!r}")
                continue
            seen_final.add(final_key)
            full_path = os.path.join(dest, final_name)
            try:
                if os.path.isdir(full_path):
                    stats["existed"] += 1
                    self.log_message(f"EXISTS: {final_name}")
                else:
                    os.makedirs(full_path, exist_ok=True)
                    stats["created"] += 1
                    self.log_message(f"CREATED: {final_name}")
            except OSError as e:
                stats["invalid_skipped"] += 1
                self.log_message(f"ERROR: {final_name} — {e}")

        stats["duplicates_ignored"] = raw_dupes + post_sanitize_dupes
        return stats

    def open_destination(self) -> None:
        dest = self.destination_path.get().strip()
        if not dest or not os.path.isdir(dest):
            self.log_message("Cannot open destination: invalid or missing folder.")
            return
        try:
            if sys.platform == "win32":
                try:
                    os.startfile(dest)  # type: ignore[attr-defined]
                except OSError:
                    flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
                    subprocess.run(
                        ["explorer", os.path.normpath(dest)],
                        check=False,
                        creationflags=flags,
                    )
            elif sys.platform == "darwin":
                subprocess.Popen(["open", dest], close_fds=True)
            else:
                subprocess.Popen(["xdg-open", dest], close_fds=True)
            self.log_message(f"Opened folder: {dest}")
        except Exception as e:
            self.log_message(f"Could not open folder: {e}")

    def log_message(self, msg: str) -> None:
        ts = datetime.now().strftime("%H:%M:%S")
        line = f"[{ts}] {msg}\n"
        self.log_text.configure(state="normal")
        self.log_text.insert(END, line)
        self.log_text.see(END)
        self.log_text.configure(state="disabled")
        self.status_var.set(msg[:120] + ("…" if len(msg) > 120 else ""))

    def _clear_log(self) -> None:
        self.log_text.configure(state="normal")
        self.log_text.delete("1.0", END)
        self.log_text.configure(state="disabled")

    def clear_names(self) -> None:
        self.names_text.delete("1.0", END)
        self.log_message("Names cleared.")
        self.status_var.set("Names cleared.")

    def paste_names_from_clipboard(self) -> None:
        """Replace names box with clipboard text (one name per line)."""
        try:
            text = self.clipboard_get()
        except tkinter.TclError:
            messagebox.showinfo("Paste", "Clipboard is empty or contains non-text data.")
            return
        if not text.strip():
            messagebox.showinfo("Paste", "Clipboard is empty.")
            return
        self.names_text.delete("1.0", END)
        self.names_text.insert("1.0", text.strip())
        n = len(self.get_clean_names())
        self.log_message(f"Pasted from clipboard: {n} unique name(s).")
        self.status_var.set(f"Pasted {n} name(s) from clipboard.")

    def insert_sample_names(self) -> None:
        sample = (
            "MD RAKIB\n"
            "JANNATUN NAEEM\n"
        )
        existing = self.names_text.get("1.0", END).strip()
        if existing:
            if not messagebox.askyesno(
                "Replace names?",
                "Replace the current names with sample data?",
                parent=self.winfo_toplevel(),
            ):
                return
        self.names_text.delete("1.0", END)
        self.names_text.insert("1.0", sample)
        self.log_message("Sample names inserted.")

    def export_log(self) -> None:
        try:
            path = filedialog.asksaveasfilename(
                title="Export log",
                defaultextension=".txt",
                filetypes=[("Text", "*.txt"), ("All", "*.*")],
            )
            if not path:
                return
            self.log_text.configure(state="normal")
            content = self.log_text.get("1.0", END)
            self.log_text.configure(state="disabled")
            with open(path, "w", encoding="utf-8") as f:
                f.write(content)
            self.log_message(f"Log exported to: {path}")
            messagebox.showinfo("Export", f"Log saved to:\n{path}")
        except OSError as e:
            messagebox.showerror("Export", str(e))

    def on_generate_clicked(self) -> None:
        dest = self.destination_path.get().strip()
        clean = self.get_clean_names()

        if not clean:
            messagebox.showwarning("No names", "Paste at least one student name (non-empty line).")
            self.status_var.set("No names to process.")
            return
        if not dest:
            messagebox.showwarning("No destination", "Choose a destination folder with Browse.")
            self.status_var.set("No destination selected.")
            return
        if not os.path.isdir(dest):
            messagebox.showerror("Invalid destination", "The selected path is not a valid folder.")
            return

        self._clear_log()
        self.log_message("— Starting folder generation —")

        # ── Progress bar UI ──────────────────────────────────────────────
        total = len(clean)
        self._gen_btn = None  # stash for re-enable
        # Disable Generate button while running
        for child in self.winfo_children():
            pass  # we'll find it by iterating btn_row below
        try:
            # Walk widget tree to disable the Generate button
            for w in self.winfo_children():
                for w2 in w.winfo_children():
                    if isinstance(w2, ttk.Frame):
                        for w3 in w2.winfo_children():
                            if isinstance(w3, ttk.Button) and w3.cget("text") == "Generate":
                                self._gen_btn = w3
                                w3.configure(state="disabled")
        except Exception:
            pass

        prog_frame = ttk.Frame(self)
        prog_frame.grid(row=2, column=0, sticky=(W, E), padx=16, pady=(0, 4))
        prog_frame.columnconfigure(0, weight=1)
        prog_var = DoubleVar(value=0.0)
        prog_bar = ttk.Progressbar(prog_frame, variable=prog_var, maximum=max(total, 1), length=300)
        prog_bar.grid(row=0, column=0, sticky=(W, E))
        prog_label = ttk.Label(prog_frame, text="0 / {}".format(total), style="Subtle.TLabel")
        prog_label.grid(row=0, column=1, padx=(8, 0))

        stats_holder: list[dict] = []
        error_holder: list[str] = []

        # Snapshot ALL Tkinter state needed by the worker before the thread starts.
        # Accessing Tkinter widgets from a background thread is unsafe.
        _raw_lines = self.names_text.get("1.0", END).splitlines()
        _total_pasted = sum(1 for ln in _raw_lines if ln.strip())
        _non_blank = [ln.strip() for ln in _raw_lines if ln.strip()]
        _case_mode = self.case_mode.get()
        _prefix = self.prefix_var.get() or ""
        _suffix = self.suffix_var.get() or ""

        def _build_name_thread_safe(raw_name: str) -> tuple[str, list[str]]:
            """Pure-string version of _build_final_folder_name using snapshotted settings."""
            warnings: list[str] = []
            formatted = apply_text_case(raw_name, _case_mode)
            combined = f"{_prefix}{formatted}{_suffix}"
            safe, mod = self.sanitize_folder_name(combined)
            if mod and combined.strip():
                warnings.append(f"Sanitized: {combined!r} → {safe!r}")
            if not safe:
                warnings.append(f"Empty after sanitize, skipped: {raw_name!r}")
            return safe, warnings

        def _run_in_thread() -> None:
            """Build folders one at a time, pumping progress to the UI thread."""
            stats: dict = {
                "total_pasted": _total_pasted,
                "valid_names": len(clean),
                "created": 0,
                "existed": 0,
                "invalid_skipped": 0,
                "duplicates_ignored": 0,
            }
            non_blank = _non_blank
            raw_dupes = max(0, len(non_blank) - len(clean))
            seen_final: set[str] = set()
            post_sanitize_dupes = 0

            for i, clean_name in enumerate(clean):
                final_name, warns = _build_name_thread_safe(clean_name)

                def _progress(idx=i, fn=final_name, ws=list(warns)) -> None:
                    try:
                        prog_var.set(idx + 1)
                        prog_label.configure(text=f"{idx + 1} / {total}")
                        for w in ws:
                            self.log_message(f"  ⚠ {w}")
                    except tkinter.TclError:
                        pass

                self.after(0, _progress)

                if not final_name:
                    stats["invalid_skipped"] += 1
                    self.after(0, lambda cn=clean_name: self.log_message(f"SKIP (invalid): {cn!r}"))
                    continue
                final_key = final_name.casefold()
                if final_key in seen_final:
                    post_sanitize_dupes += 1
                    self.after(0, lambda fn=final_name: self.log_message(f"SKIP (duplicate after sanitize): {fn!r}"))
                    continue
                seen_final.add(final_key)
                full_path = os.path.join(dest, final_name)
                try:
                    if os.path.isdir(full_path):
                        stats["existed"] += 1
                        self.after(0, lambda fn=final_name: self.log_message(f"EXISTS: {fn}"))
                    else:
                        os.makedirs(full_path, exist_ok=True)
                        stats["created"] += 1
                        self.after(0, lambda fn=final_name: self.log_message(f"CREATED: {fn}"))
                except OSError as e:
                    stats["invalid_skipped"] += 1
                    self.after(0, lambda fn=final_name, err=str(e): self.log_message(f"ERROR: {fn} — {err}"))

            stats["duplicates_ignored"] = raw_dupes + post_sanitize_dupes
            stats_holder.append(stats)
            self.after(0, _finish)

        def _finish() -> None:
            try:
                prog_frame.grid_remove()
            except Exception:
                pass
            if self._gen_btn:
                try:
                    self._gen_btn.configure(state="normal")
                except Exception:
                    pass
            if not stats_holder:
                messagebox.showerror("Error", "Folder generation failed unexpectedly.")
                return
            stats = stats_holder[0]
            self.log_message("")
            self.log_message("— Summary —")
            self.log_message(f"Total non-empty lines (pasted): {stats['total_pasted']}")
            self.log_message(f"Valid unique names: {stats['valid_names']}")
            self.log_message(f"Folders created: {stats['created']}")
            self.log_message(f"Already existed: {stats['existed']}")
            self.log_message(f"Invalid / skipped: {stats['invalid_skipped']}")
            self.log_message(f"Duplicate lines ignored: {stats['duplicates_ignored']}")

            summary = (
                f"Created: {stats['created']}\n"
                f"Already existed: {stats['existed']}\n"
                f"Skipped: {stats['invalid_skipped']}"
            )
            messagebox.showinfo("Done", f"Folder generation finished.\n\n{summary}")

            if self.open_after_var.get():
                self.open_destination()

            self.status_var.set(
                f"Done — created {stats['created']}, existed {stats['existed']}, skipped {stats['invalid_skipped']}"
            )

        import threading as _threading
        _threading.Thread(target=_run_in_thread, daemon=True).start()


