class PrintDialog(Toplevel):
    """Full print dialog: printer, copies, page range, orientation, fit mode."""

    def __init__(self, master, *, path: str, page_count: int = 1, current_page: int = 0) -> None:
        super().__init__(master)
        self.title("Print")
        self.transient(master)
        self.resizable(True, False)
        self.result: dict | None = None
        self._path = path
        self._page_count = page_count
        self._current_page = current_page

        try:
            px = master.winfo_rootx() + 40
            py = master.winfo_rooty() + 40
            self.geometry(f"500+{px}+{py}")
        except tkinter.TclError:
            self.geometry("500x480")

        outer = ttk.Frame(self, padding=(16, 12, 16, 12))
        outer.pack(fill=BOTH, expand=True)

        def _row(label_text, widget_fn):
            """Pack a label+widget row and return the widget."""
            row = ttk.Frame(outer)
            row.pack(fill=X, pady=3)
            ttk.Label(row, text=label_text, width=12, anchor=W).pack(side=LEFT)
            w = widget_fn(row)
            w.pack(side=LEFT, fill=X, expand=True)
            return w

        def _sep():
            ttk.Separator(outer, orient="horizontal").pack(fill=X, pady=8)

        # ── Printer ──────────────────────────────────────────────────────────
        printers = self._list_printers()
        default_p = self._default_printer()
        self._printer_var = StringVar(
            value=default_p if default_p in printers else (printers[0] if printers else "Default Printer")
        )
        _row("Printer:", lambda p: ttk.Combobox(
            p, textvariable=self._printer_var, values=printers, state="readonly"))

        # ── Copies ────────────────────────────────────────────────────────────
        self._copies_var = StringVar(value="1")
        _copies_w = _row("Copies:", lambda p: ttk.Spinbox(
            p, from_=1, to=999, textvariable=self._copies_var, width=7))
        _copies_w.pack_configure(fill=None, expand=False)

        _sep()

        # ── Page range ────────────────────────────────────────────────────────
        pages_row = ttk.Frame(outer)
        pages_row.pack(fill=X, pady=3)
        ttk.Label(pages_row, text="Pages:", width=12, anchor=W).pack(side=LEFT, anchor=N)

        range_fr = ttk.Frame(pages_row)
        range_fr.pack(side=LEFT, fill=X, expand=True)
        self._range_mode = tkinter.IntVar(value=0)
        ttk.Radiobutton(range_fr, text="All pages", variable=self._range_mode, value=0).pack(anchor=W)
        cur_lbl = (f"Current page ({self._current_page + 1})"
                   if page_count > 1 else f"Page {self._current_page + 1}")
        ttk.Radiobutton(range_fr, text=cur_lbl, variable=self._range_mode, value=1).pack(anchor=W)
        ttk.Radiobutton(range_fr, text="Custom range:", variable=self._range_mode, value=2).pack(anchor=W)
        range_entry_row = ttk.Frame(range_fr)
        range_entry_row.pack(fill=X, padx=(20, 0), pady=(2, 0))
        self._range_str = StringVar(value="1")
        self._range_entry = ttk.Entry(range_entry_row, textvariable=self._range_str, width=22)
        self._range_entry.pack(side=LEFT)
        ttk.Label(range_entry_row, text="  e.g. 1, 3, 5-7", foreground="#777").pack(side=LEFT)
        self._range_entry.bind("<FocusIn>", lambda _e: self._range_mode.set(2))

        _sep()

        # ── Orientation ───────────────────────────────────────────────────────
        orient_row = ttk.Frame(outer)
        orient_row.pack(fill=X, pady=3)
        ttk.Label(orient_row, text="Orientation:", width=12, anchor=W).pack(side=LEFT)
        self._orient_var = StringVar(value="Portrait")
        ttk.Radiobutton(orient_row, text="Portrait",  variable=self._orient_var, value="Portrait").pack(side=LEFT, padx=(0, 16))
        ttk.Radiobutton(orient_row, text="Landscape", variable=self._orient_var, value="Landscape").pack(side=LEFT)

        # ── Scale / Fit ───────────────────────────────────────────────────────
        scale_row = ttk.Frame(outer)
        scale_row.pack(fill=X, pady=3)
        ttk.Label(scale_row, text="Scale:", width=12, anchor=W).pack(side=LEFT)
        self._fit_var = StringVar(value="Fit to page")
        for lbl in ("Fit to page", "Actual size", "Fill page"):
            ttk.Radiobutton(scale_row, text=lbl, variable=self._fit_var, value=lbl).pack(side=LEFT, padx=(0, 12))

        _sep()

        # ── Buttons ───────────────────────────────────────────────────────────
        btn_row = ttk.Frame(outer)
        btn_row.pack(fill=X, pady=(0, 2))
        ttk.Button(btn_row, text="Print",  command=self._on_ok,     width=10).pack(side=RIGHT, padx=(8, 0))
        ttk.Button(btn_row, text="Cancel", command=self._on_cancel, width=10).pack(side=RIGHT)

        self.protocol("WM_DELETE_WINDOW", self._on_cancel)
        self.bind("<Return>", lambda _e: self._on_ok())
        self.bind("<Escape>", lambda _e: self._on_cancel())
        self.after_idle(lambda: self.grab_set())

    @staticmethod
    def _list_printers() -> list[str]:
        if sys.platform == "win32":
            try:
                import win32print
                return [p[2] for p in win32print.EnumPrinters(
                    win32print.PRINTER_ENUM_LOCAL | win32print.PRINTER_ENUM_CONNECTIONS)]
            except Exception:
                pass
        try:
            out = subprocess.check_output(["lpstat", "-a"], text=True, timeout=4)
            return [ln.split()[0] for ln in out.splitlines() if ln.strip()]
        except Exception:
            pass
        return ["Default Printer"]

    @staticmethod
    def _default_printer() -> str:
        if sys.platform == "win32":
            try:
                import win32print
                return win32print.GetDefaultPrinter()
            except Exception:
                pass
        try:
            out = subprocess.check_output(["lpstat", "-d"], text=True, timeout=4)
            for part in out.split(":"):
                s = part.strip()
                if s:
                    return s
        except Exception:
            pass
        return ""

    def _on_ok(self) -> None:
        try:
            copies = max(1, int(self._copies_var.get()))
        except ValueError:
            copies = 1
        mode = self._range_mode.get()
        if mode == 0:
            pages = list(range(self._page_count))
        elif mode == 1:
            pages = [self._current_page]
        else:
            ok, res = fo.parse_pdf_page_range_input(self._range_str.get(), self._page_count)
            if not ok:
                messagebox.showerror("Print", res, parent=self)
                return
            pages = res
        self.result = {
            "printer": self._printer_var.get(),
            "copies": copies,
            "pages": pages,
            "all_pages": mode == 0,
            "orientation": self._orient_var.get(),
            "fit": self._fit_var.get(),
            "path": self._path,
        }
        self.grab_release()
        self.destroy()

    def _on_cancel(self) -> None:
        self.result = None
        self.grab_release()
        self.destroy()


def _execute_print_job(result: dict, log_fn=None) -> None:
    """Send a file to the printer using the settings from PrintDialog."""
    if result is None:
        return
    path = result["path"]
    pages = result.get("pages")
    copies = result.get("copies", 1)
    orientation = result.get("orientation", "Portrait")
    fit = result.get("fit", "Fit to page")
    printer = result.get("printer", "")

    ext = os.path.splitext(path)[1].lower()
    is_pdf = ext == ".pdf"
    is_image = ext in {".jpg", ".jpeg", ".png", ".bmp", ".tif", ".tiff", ".webp", ".gif", ".jfif"}

    if is_pdf:
        # Build a temp PDF with only the selected pages if needed
        total = fo.pdf_page_count(path)
        if pages is None or sorted(pages) == list(range(total)):
            print_path = path
            temp_path = None
        else:
            ok, tmp = fo.pdf_export_selected_pages_to_tempfile(path, pages)
            if not ok:
                if log_fn:
                    log_fn("Print failed: " + tmp)
                return
            print_path = tmp
            temp_path = tmp
        # Send to printer
        if sys.platform == "win32":
            try:
                os.startfile(print_path, "print")  # type: ignore[attr-defined]
            except OSError as e:
                if log_fn:
                    log_fn("Print error: " + str(e))
        elif sys.platform == "darwin":
            cmd = ["lpr", "-#", str(copies)]
            if printer:
                cmd += ["-P", printer]
            cmd.append(print_path)
            subprocess.Popen(cmd, close_fds=True)
        else:
            cmd = ["lpr", "-#", str(copies)]
            if printer:
                cmd += ["-P", printer]
            cmd.append(print_path)
            subprocess.Popen(cmd, close_fds=True)
        if log_fn:
            log_fn("Print job sent: " + os.path.basename(path))
        if temp_path:
            import threading as _th
            t = _th.Timer(120.0, lambda p=temp_path: os.path.isfile(p) and os.unlink(p))
            t.daemon = True
            t.start()
    elif is_image:
        _print_pil_image(path, printer=printer, copies=copies,
                         orientation=orientation, fit=fit, log_fn=log_fn)
    else:
        # fallback: OS default handler
        if sys.platform == "win32":
            try:
                os.startfile(path, "print")  # type: ignore[attr-defined]
            except OSError as e:
                if log_fn:
                    log_fn("Print error: " + str(e))
        else:
            subprocess.Popen(["lpr", path], close_fds=True)


def _print_pil_image(path: str, *, printer: str = "", copies: int = 1,
                     orientation: str = "Portrait", fit: str = "Fit to page",
                     log_fn=None) -> None:
    """Print an image file using PIL + win32print on Windows, lpr elsewhere."""
    try:
        from PIL import Image
        img = Image.open(path).convert("RGB")
    except Exception as e:
        if log_fn:
            log_fn("Print image load error: " + str(e))
        return
    if orientation == "Landscape" and img.width < img.height:
        img = img.rotate(90, expand=True)
    elif orientation == "Portrait" and img.width > img.height:
        img = img.rotate(-90, expand=True)

    if sys.platform == "win32":
        try:
            import win32print, win32ui
            from PIL import ImageWin
            hprinter = win32print.OpenPrinter(printer or win32print.GetDefaultPrinter())
            try:
                hdc = win32ui.CreateDC()
                hdc.CreatePrinterDC(printer or win32print.GetDefaultPrinter())
                pw = hdc.GetDeviceCaps(110)   # HORZRES
                ph = hdc.GetDeviceCaps(111)   # VERTRES
                for _ in range(copies):
                    hdc.StartDoc(os.path.basename(path))
                    hdc.StartPage()
                    if fit == "Actual size":
                        iw, ih = img.size
                    elif fit == "Fill page":
                        scale = max(pw / img.width, ph / img.height)
                        iw, ih = int(img.width * scale), int(img.height * scale)
                    else:  # Fit to page
                        scale = min(pw / img.width, ph / img.height)
                        iw, ih = int(img.width * scale), int(img.height * scale)
                    x0 = (pw - iw) // 2
                    y0 = (ph - ih) // 2
                    dib = ImageWin.Dib(img)
                    dib.draw(hdc.GetHandleOutput(), (x0, y0, x0 + iw, y0 + ih))
                    hdc.EndPage()
                    hdc.EndDoc()
                hdc.DeleteDC()
            finally:
                win32print.ClosePrinter(hprinter)
            if log_fn:
                log_fn("Image print job sent: " + os.path.basename(path))
        except ImportError:
            # win32print not available — fall back to ShellExecute
            try:
                os.startfile(path, "print")  # type: ignore[attr-defined]
            except OSError as e:
                if log_fn:
                    log_fn("Print error: " + str(e))
        except Exception as e:
            if log_fn:
                log_fn("Print error: " + str(e))
    else:
        # Convert to temp PDF then lpr
        import tempfile
        try:
            with tempfile.NamedTemporaryFile(suffix=".pdf", delete=False) as tf:
                tmp = tf.name
            img.save(tmp, "PDF")
            cmd = ["lpr", "-#", str(copies)]
            if printer:
                cmd += ["-P", printer]
            cmd.append(tmp)
            subprocess.Popen(cmd, close_fds=True)
            import threading as _th
            t = _th.Timer(60.0, lambda p=tmp: os.path.isfile(p) and os.unlink(p))
            t.daemon = True
            t.start()
            if log_fn:
                log_fn("Image print job sent: " + os.path.basename(path))
        except Exception as e:
            if log_fn:
                log_fn("Print error: " + str(e))

class PdfPrintRangeDialog(Toplevel):
    """Choose which pages to print: all, current, or a custom 1-based range."""

    def __init__(
        self,
        master: tkinter.Misc,
        *,
        current_page_1based: int,
        page_count: int,
    ) -> None:
        super().__init__(master)
        self.title("Print PDF")
        self.choice: str | list[int] | None = None
        self.transient(master)
        self.resizable(False, False)

        try:
            px = master.winfo_rootx() + 60
            py = master.winfo_rooty() + 60
            self.geometry(f"+{px}+{py}")
        except tkinter.TclError:
            pass

        cur = max(1, min(current_page_1based, page_count))
        fr = ttk.Frame(self, padding=14)
        fr.pack(fill=BOTH, expand=True)
        ttk.Label(
            fr,
            text=f"This PDF has {page_count} page(s). What should be sent to the printer?",
            wraplength=420,
        ).pack(anchor=W, pady=(0, 10))

        mode = tkinter.IntVar(value=1)
        ttk.Radiobutton(fr, text="All pages", variable=mode, value=0).pack(anchor=W)
        ttk.Radiobutton(
            fr,
            text=f"Current page only (page {cur})",
            variable=mode,
            value=1,
        ).pack(anchor=W)
        ttk.Radiobutton(fr, text="Page range (below)", variable=mode, value=2).pack(anchor=W)

        range_row = ttk.Frame(fr)
        range_row.pack(fill=X, pady=(8, 4))
        ttk.Label(range_row, text="Pages (e.g. 1, 3, 5-7):").pack(side=LEFT)
        range_var = StringVar(value=str(cur))
        ent = ttk.Entry(range_row, textvariable=range_var, width=28)
        ent.pack(side=LEFT, padx=(8, 0))

        btn = ttk.Frame(fr)
        btn.pack(fill=X, pady=(12, 0))

        def on_ok() -> None:
            if mode.get() == 0:
                self.choice = "all"
            elif mode.get() == 1:
                self.choice = [cur - 1]
            else:
                ok, res = fo.parse_pdf_page_range_input(range_var.get(), page_count)
                if not ok:
                    messagebox.showerror("Print", res, parent=self)
                    return
                self.choice = res
            self.grab_release()
            self.destroy()

        def on_cancel() -> None:
            self.choice = None
            self.grab_release()
            self.destroy()

        ttk.Button(btn, text="Print", command=on_ok).pack(side=RIGHT, padx=(6, 0))
        ttk.Button(btn, text="Cancel", command=on_cancel).pack(side=RIGHT)

        self.protocol("WM_DELETE_WINDOW", on_cancel)
        self.bind("<Return>", lambda _e: on_ok())
        self.bind("<Escape>", lambda _e: on_cancel())
        ent.bind("<Return>", lambda _e: on_ok())
        self.after_idle(lambda: self.grab_set())


class PdfFullViewDialog(Toplevel):
    """Full-view window for a single PDF — page nav, zoom, keyboard nav."""

    ZOOM_MIN = 0.25
    ZOOM_MAX = 8.0
    ZOOM_STEP = 1.15   # multiplicative per notch — same feel as merge modal
    SUPERSAMPLE = 1.6
    PDF_MAX_ZOOM = 4.0

    def __init__(self, master: tkinter.Misc, path: str) -> None:
        super().__init__(master)
        self._path = os.path.abspath(path)
        self._page: int = 0
        self._total: int = 0
        self._zoom: float = 1.0
        self._photo = None
        self._render_job = None
        self._drag_start: tuple[int, int] | None = None
        self._drag_pan_origin: tuple[int, int] = (0, 0)
        self._pan_x: int = 0
        self._pan_y: int = 0
        self._canvas_image_id: int | None = None
        self._base_ix: int = 0
        self._base_iy: int = 0

        self._is_image = os.path.splitext(self._path)[1].lower() in {
            ".jpg", ".jpeg", ".png", ".bmp", ".tif", ".tiff", ".webp", ".gif", ".jfif"
        }
        # Adjustments state (images only)
        self._adj_brightness: float = 1.0
        self._adj_contrast: float = 1.0
        self._adj_sharpness: float = 1.0
        self._adj_saturation: float = 1.0
        self._adj_temperature: float = 0.0    # -100 cool … +100 warm
        self._adj_hue: float = 0.0            # -180 … +180 degrees
        self._adj_fine_rotate: float = 0.0    # -45 … +45 degrees
        self._adj_rotation: int = 0   # cumulative CW degrees (0/90/180/270)
        self._adj_flip_h: bool = False
        self._adj_flip_v: bool = False
        self._crop_rect: tuple[int,int,int,int] | None = None  # x1,y1,x2,y2 in image pixels
        self._crop_drag_start: tuple[int,int] | None = None
        self._crop_rect_id: int | None = None
        self._crop_mode: bool = False
        self._crop_aspect: str = "Free"
        self._pil_original = None  # cached original PIL image for adjustments
        self._resize_w_var = None
        self._resize_h_var = None
        self._resize_orig = (0, 0)
        self._resize_lock = True

        basename = os.path.basename(self._path)
        self.title(("Image" if self._is_image else "PDF") + f" — {basename}")

        # Try to size to ~85% of screen
        try:
            sw = master.winfo_screenwidth()
            sh = master.winfo_screenheight()
            w = max(860, int(sw * 0.82))
            h = max(640, int(sh * 0.85))
            x = (sw - w) // 2
            y = max(0, (sh - h) // 2 - 30)
            self.geometry(f"{w}x{h}+{x}+{y}")
        except tkinter.TclError:
            self.geometry("960x720")

        self.minsize(520, 400)
        self.resizable(True, True)

        # ── toolbar ──────────────────────────────────────────────────────────
        toolbar = ttk.Frame(self, padding=(6, 4))
        toolbar.pack(side=TOP, fill=X)

        self._page_var = StringVar(value="1")
        self._page_label = ttk.Label(toolbar, text="/ 1")

        if not self._is_image:
            ttk.Button(toolbar, text="◄  Prev", width=8, command=self._prev_page).pack(side=LEFT, padx=(0, 2))
            ttk.Button(toolbar, text="Next  ►", width=8, command=self._next_page).pack(side=LEFT, padx=(0, 10))
            self._page_entry = ttk.Entry(toolbar, textvariable=self._page_var, width=5, justify="center")
            self._page_entry.pack(side=LEFT)
            self._page_entry.bind("<Return>", self._on_page_entry_return)
            self._page_entry.bind("<KP_Enter>", self._on_page_entry_return)
            self._page_label.pack(side=LEFT, padx=(2, 14))
        else:
            self._page_entry = ttk.Entry(toolbar, textvariable=self._page_var, width=1)  # hidden placeholder

        ttk.Button(toolbar, text="−", width=3, command=self._zoom_out).pack(side=LEFT, padx=(0, 2))
        self._zoom_label = ttk.Label(toolbar, text="100%", width=6, anchor="center")
        self._zoom_label.pack(side=LEFT)
        ttk.Button(toolbar, text="+", width=3, command=self._zoom_in).pack(side=LEFT, padx=(2, 2))
        ttk.Button(toolbar, text="Fit", width=4, command=self._zoom_fit).pack(side=LEFT, padx=(4, 0))

        if self._is_image:
            ttk.Separator(toolbar, orient="vertical").pack(side=LEFT, fill=Y, padx=(8, 4), pady=3)
            ttk.Button(toolbar, text="↻ 90°", width=6, command=self._img_rotate_cw).pack(side=LEFT, padx=1)
            ttk.Button(toolbar, text="↺ 90°", width=6, command=self._img_rotate_ccw).pack(side=LEFT, padx=1)
            ttk.Separator(toolbar, orient="vertical").pack(side=LEFT, fill=Y, padx=(6, 4), pady=3)
            ttk.Button(toolbar, text="💾 Save", command=self._img_save).pack(side=LEFT, padx=2)
            ttk.Button(toolbar, text="→ JPG", command=lambda: self._img_convert_save("jpg")).pack(side=LEFT, padx=1)
            ttk.Button(toolbar, text="→ PNG", command=lambda: self._img_convert_save("png")).pack(side=LEFT, padx=1)
            ttk.Separator(toolbar, orient="vertical").pack(side=LEFT, fill=Y, padx=(6, 4), pady=3)
            ttk.Button(toolbar, text="🪪 ID Card → A4", command=self._open_id_card_layout).pack(side=LEFT, padx=2)
            ttk.Button(toolbar, text="↩ Reset All", command=self._img_reset_all).pack(side=LEFT, padx=2)

        ttk.Button(toolbar, text="🖨 Print", command=self._show_print_dialog).pack(side=RIGHT, padx=(6, 2))
        ttk.Button(toolbar, text="✕ Close", command=self.destroy).pack(side=RIGHT, padx=(6, 0))

        # ── main content area ─────────────────────────────────────────────────
        main_area = ttk.Frame(self)
        main_area.pack(fill=BOTH, expand=True)

        # Side panel (images only)
        if self._is_image:
            try:
                self._side_panel = self._build_image_side_panel(main_area)
                self._side_panel.pack(side=RIGHT, fill=Y)
            except Exception as _sp_err:
                # If side panel fails, log it but proceed — canvas still loads image
                try:
                    import traceback
                    print(f"[ImageView] Side panel error: {_sp_err}")
                    traceback.print_exc()
                except Exception:
                    pass
                self._side_panel = None

        # ── canvas + scrollbars ───────────────────────────────────────────────
        frame = ttk.Frame(main_area)
        frame.pack(side=LEFT, fill=BOTH, expand=True)
        frame.columnconfigure(0, weight=1)
        frame.rowconfigure(0, weight=1)

        self._vscroll = ttk.Scrollbar(frame, orient=VERTICAL)
        self._hscroll = ttk.Scrollbar(frame, orient=HORIZONTAL)
        self._canvas = tkinter.Canvas(
            frame,
            bg="#3c3c3c",
            highlightthickness=0,
            yscrollcommand=self._vscroll.set,
            xscrollcommand=self._hscroll.set,
        )
        self._vscroll.config(command=self._canvas.yview)
        self._hscroll.config(command=self._canvas.xview)
        self._canvas.grid(row=0, column=0, sticky=(N, S, W, E))
        self._vscroll.grid(row=0, column=1, sticky=(N, S))
        self._hscroll.grid(row=1, column=0, sticky=(W, E))

        # bindings
        self._canvas.bind("<Configure>", self._on_canvas_configure)
        self._canvas.bind("<MouseWheel>", self._on_wheel)
        self._canvas.bind("<Button-4>", self._on_wheel_linux_up)
        self._canvas.bind("<Button-5>", self._on_wheel_linux_down)
        self._canvas.bind("<ButtonPress-1>", self._img_canvas_press)
        self._canvas.bind("<B1-Motion>", self._img_canvas_motion)
        self._canvas.bind("<ButtonRelease-1>", self._img_canvas_release)
        self._canvas.bind("<ButtonPress-2>", self._on_drag_start)
        self._canvas.bind("<B2-Motion>", self._on_drag_motion)
        self._canvas.bind("<ButtonRelease-2>", self._on_drag_end)
        self.bind("<Left>", lambda _e: self._prev_page())
        self.bind("<Right>", lambda _e: self._next_page())
        self.bind("<Prior>", lambda _e: self._prev_page())    # PgUp
        self.bind("<Next>", lambda _e: self._next_page())     # PgDn
        self.bind("<Home>", lambda _e: self._go_to_page(0))
        self.bind("<End>", lambda _e: self._go_to_page(self._total - 1))
        self.bind("<Escape>", lambda _e: self.destroy())
        self.bind("<Control-plus>", lambda _e: self._zoom_in())
        self.bind("<Control-equal>", lambda _e: self._zoom_in())
        self.bind("<Control-minus>", lambda _e: self._zoom_out())
        self.bind("<Control-0>", lambda _e: self._zoom_fit())

        self._canvas.focus_set()

        # load
        if self._is_image:
            self._total = 1
            self.after_idle(self._render)
            return

        if not fo.get_fitz() or not fo.get_pillow():
            self._canvas.create_text(
                200, 120,
                text="PyMuPDF and Pillow are required for PDF preview.",
                fill="#e2e8f0", font=("Segoe UI", 11),
            )
            return

        self._total = fo.pdf_page_count(self._path)
        if self._total < 1:
            self._canvas.create_text(
                200, 120,
                text="Could not read PDF pages.",
                fill="#e2e8f0", font=("Segoe UI", 11),
            )
            return

        self._page_label.configure(text=f"/ {self._total}")
        # render after window is drawn so we know canvas size
        self.after_idle(self._render)

    # ── page navigation ───────────────────────────────────────────────────────

    def _prev_page(self) -> None:
        if self._total > 0:
            self._go_to_page(self._page - 1)

    def _next_page(self) -> None:
        if self._total > 0:
            self._go_to_page(self._page + 1)

    def _go_to_page(self, idx: int) -> None:
        if self._total < 1:
            return
        idx = max(0, min(idx, self._total - 1))
        if idx == self._page:
            return
        self._page = idx
        self._pan_x = 0
        self._pan_y = 0
        self._page_var.set(str(idx + 1))
        self._render()

    def _on_page_entry_return(self, _event=None) -> None:
        try:
            n = int(self._page_var.get())
        except ValueError:
            self._page_var.set(str(self._page + 1))
            return
        self._go_to_page(n - 1)
        self._canvas.focus_set()

    # ── zoom ─────────────────────────────────────────────────────────────────

    def _zoom_in(self) -> None:
        self._set_zoom(self._zoom * self.ZOOM_STEP)

    def _zoom_out(self) -> None:
        self._set_zoom(self._zoom / self.ZOOM_STEP)

    def _zoom_fit(self) -> None:
        self._pan_x = 0
        self._pan_y = 0
        self._set_zoom(1.0)

    def _set_zoom(self, z: float) -> None:
        z = max(self.ZOOM_MIN, min(self.ZOOM_MAX, z))
        if abs(z - self._zoom) < 0.001:
            return
        self._zoom = z
        self._pan_x = 0
        self._pan_y = 0
        self._zoom_label.configure(text=f"{z * 100:.0f}%")
        self._schedule_render()

    def _on_wheel(self, event: tkinter.Event) -> str:
        # Ctrl OR Alt = zoom (same as merge modal); plain = scroll
        if event.state & 0x0004 or event.state & 0x20000:
            delta = getattr(event, "delta", 0)
            if delta > 0:
                self._zoom_in()
            elif delta < 0:
                self._zoom_out()
            return "break"
        # plain scroll
        delta = getattr(event, "delta", 0)
        if delta:
            self._canvas.yview_scroll(int(-delta / 60), "units")
        return "break"

    def _on_wheel_linux_up(self, event: tkinter.Event) -> str:
        if event.state & 0x0004 or event.state & 0x20000:
            self._zoom_in()
        else:
            self._canvas.yview_scroll(-3, "units")
        return "break"

    def _on_wheel_linux_down(self, event: tkinter.Event) -> str:
        if event.state & 0x0004 or event.state & 0x20000:
            self._zoom_out()
        else:
            self._canvas.yview_scroll(3, "units")
        return "break"

    # ── drag-to-pan ───────────────────────────────────────────────────────────

    def _on_drag_start(self, event: tkinter.Event) -> None:
        self._drag_start = (event.x, event.y)
        self._drag_pan_origin = (self._pan_x, self._pan_y)
        self._canvas.config(cursor="fleur")

    def _on_drag_motion(self, event: tkinter.Event) -> None:
        if self._drag_start is None:
            return
        dx = event.x - self._drag_start[0]
        dy = event.y - self._drag_start[1]
        self._pan_x = self._drag_pan_origin[0] + dx
        self._pan_y = self._drag_pan_origin[1] + dy
        if self._canvas_image_id is not None:
            try:
                self._canvas.coords(
                    self._canvas_image_id,
                    self._base_ix + self._pan_x,
                    self._base_iy + self._pan_y,
                )
            except tkinter.TclError:
                pass

    def _on_drag_end(self, event: tkinter.Event) -> None:
        self._drag_start = None
        self._canvas.config(cursor="arrow")

    # ── rendering ─────────────────────────────────────────────────────────────

    def _on_canvas_configure(self, _event=None) -> None:
        self._schedule_render()

    def _schedule_render(self) -> None:
        if self._render_job is not None:
            try:
                self.after_cancel(self._render_job)
            except (ValueError, tkinter.TclError):
                pass
        self._render_job = self.after(60, self._render)

    def _render(self) -> None:
        self._render_job = None
        if self._total < 1:
            return

        import threading as _thr

        cw = max(self._canvas.winfo_width(), 200)
        ch = max(self._canvas.winfo_height(), 160)
        z = self._zoom
        page = self._page

        # Serial counter — background workers check before posting to canvas
        self._render_serial = getattr(self, "_render_serial", 0) + 1
        serial = self._render_serial

        if self._is_image:
            if self._pil_original is None:
                # First open: load the image on a background thread so the UI
                # stays responsive (large JPEGs can take 1-2 s on the main thread).
                self._canvas.delete("all")
                self._canvas.create_text(
                    cw // 2, ch // 2, text="Loading…",
                    fill="#94a3b8", font=("Segoe UI", 11),
                )
                path = self._path

                def _bg_load(p=path, s=serial):
                    try:
                        from PIL import Image as _PIL
                        pil = _PIL.open(p).convert("RGB")
                    except Exception:
                        pil = None
                    try:
                        self.after(0, lambda pil_=pil, s_=s: self._on_original_loaded(pil_, s_))
                    except Exception:
                        pass

                _thr.Thread(target=_bg_load, daemon=True).start()
                return

            # Image already cached → fast path (adjustments are cheap)
            self._render_apply(self._get_adjusted_image(), cw, ch, z, serial)

        else:
            # PDF — render the page in a background thread to avoid UI freezes
            rw = max(1, int(cw * z * self.SUPERSAMPLE))
            rh = max(1, int(ch * z * self.SUPERSAMPLE))
            path = self._path
            max_zoom = self.PDF_MAX_ZOOM

            def _bg_pdf(p=path, pg=page, w=rw, h=rh, mz=max_zoom, s=serial):
                img = _render_pdf_page_direct(p, pg, w, h, mz)
                try:
                    self.after(0, lambda img_=img, s_=s: self._render_apply(img_, cw, ch, z, s_))
                except Exception:
                    pass

            _thr.Thread(target=_bg_pdf, daemon=True).start()

    def _on_original_loaded(self, pil_original, serial: int) -> None:
        """Main-thread callback fired when a background image load completes."""
        if getattr(self, "_render_serial", 0) != serial:
            return  # superseded by a newer render request
        self._pil_original = pil_original
        cw = max(self._canvas.winfo_width(), 200)
        ch = max(self._canvas.winfo_height(), 160)
        self._render_apply(self._get_adjusted_image(), cw, ch, self._zoom, serial)

    def _render_apply(self, img, cw: int, ch: int, z: float, serial: int) -> None:
        """Paint a PIL image onto the canvas.  Must be called from the main thread."""
        if getattr(self, "_render_serial", 0) != serial:
            return  # stale render — a newer one is already in flight
        try:
            if not self.winfo_exists():
                return
        except tkinter.TclError:
            return

        from PIL import ImageTk

        if img is None:
            self._canvas.delete("all")
            self._canvas.create_text(
                cw // 2, ch // 2,
                text="Could not render image.",
                fill="#e2e8f0", font=("Segoe UI", 11),
            )
            return

        # Scale to fit the canvas at the current zoom level.
        disp_w = max(1, int(cw * z))
        disp_h = max(1, int(ch * z))
        iw_orig, ih_orig = img.size
        if self._is_image:
            scale = min(disp_w / iw_orig, disp_h / ih_orig)   # fit; allow enlarge
        else:
            scale = min(disp_w / iw_orig, disp_h / ih_orig, 1.0)  # downsample only
        iw = max(1, int(iw_orig * scale))
        ih = max(1, int(ih_orig * scale))
        if iw != iw_orig or ih != ih_orig:
            img = img.resize((iw, ih), resample=3)  # BICUBIC

        # Crop overlay (image mode only)
        if self._is_image and self._crop_mode and self._crop_rect:
            from PIL import ImageDraw
            img = img.copy()
            orig_w, orig_h = self._get_adjusted_image().size
            sx = iw / orig_w
            sy = ih / orig_h
            cx1, cy1, cx2, cy2 = self._crop_rect
            draw = ImageDraw.Draw(img)
            draw.rectangle(
                [int(cx1 * sx), int(cy1 * sy), int(cx2 * sx), int(cy2 * sy)],
                outline=(255, 80, 0), width=2,
            )

        ph = ImageTk.PhotoImage(img)
        self._photo = ph  # keep ref to prevent GC

        margin = 16
        sw = max(float(cw), float(iw + 2 * margin))
        sh = max(float(ch), float(ih + 2 * margin))
        self._canvas.configure(scrollregion=(0, 0, sw, sh))
        ix = int((sw - iw) / 2)
        iy = int((sh - ih) / 2)
        self._base_ix = ix
        self._base_iy = iy
        self._canvas.delete("all")
        self._canvas_image_id = self._canvas.create_image(
            ix + self._pan_x, iy + self._pan_y, image=ph, anchor="nw",
        )
        self._img_display_offset = (ix + self._pan_x, iy + self._pan_y, iw, ih)

        self._page_var.set(str(self._page + 1))
        if not self._is_image:
            self._page_label.configure(text=f"/ {self._total}")
        self._zoom_label.configure(text=f"{self._zoom * 100:.0f}%")
        self._canvas.config(
            cursor="crosshair" if (self._is_image and self._crop_mode) else "arrow",
        )

    def _build_image_side_panel(self, parent) -> ttk.Frame:
        """Build the right-side editing panel with all image tool sections."""
        PANEL_W = 228

        outer = ttk.Frame(parent, width=PANEL_W, relief="groove", borderwidth=1)
        outer.pack_propagate(False)

        # Scrollable inner via Canvas
        sp_canvas = tkinter.Canvas(outer, width=PANEL_W - 18, highlightthickness=0,
                                   bg="#f0f0f0")
        sp_scroll = ttk.Scrollbar(outer, orient=VERTICAL, command=sp_canvas.yview)
        sp_canvas.configure(yscrollcommand=sp_scroll.set)
        sp_scroll.pack(side=RIGHT, fill=Y)
        sp_canvas.pack(side=LEFT, fill=BOTH, expand=True)

        inner = ttk.Frame(sp_canvas)
        win_id = sp_canvas.create_window((0, 0), window=inner, anchor="nw")

        def _on_inner_cfg(e):
            sp_canvas.configure(scrollregion=sp_canvas.bbox("all"))
        def _on_sp_resize(e):
            sp_canvas.itemconfig(win_id, width=e.width)
        inner.bind("<Configure>", _on_inner_cfg)
        sp_canvas.bind("<Configure>", _on_sp_resize)

        def _sp_wheel(e):
            d = getattr(e, "delta", 0)
            if d:
                sp_canvas.yview_scroll(int(-d / 60), "units")
        sp_canvas.bind("<MouseWheel>", _sp_wheel)
        inner.bind("<MouseWheel>", _sp_wheel)

        def _sec(title):
            lf = ttk.LabelFrame(inner, text=title, padding=(6, 4))
            lf.pack(fill=X, padx=4, pady=(6, 0))
            return lf

        def _adj_slider(parent_w, label, attr, min_v, max_v, default=1.0, fmt=".2f"):
            row = ttk.Frame(parent_w)
            row.pack(fill=X, pady=2)
            ttk.Label(row, text=label, width=10, anchor=W).pack(side=LEFT)
            val_var = StringVar(value=f"{default:{fmt}}")
            ttk.Label(row, textvariable=val_var, width=6, anchor=E,
                      font=("Arial", 8)).pack(side=RIGHT)
            def _chg(v, _a=attr, _vv=val_var, _f=fmt):
                fv = float(v)
                setattr(self, _a, fv)
                _vv.set(f"{fv:{_f}}")
                self._schedule_render()
            sl = ttk.Scale(row, from_=min_v, to=max_v, orient=HORIZONTAL, command=_chg)
            sl.set(default)
            sl.pack(side=LEFT, fill=X, expand=True, padx=(4, 4))
            sl.bind("<MouseWheel>", _sp_wheel)
            setattr(self, f"_sl_{attr.lstrip('_')}", sl)
            return sl

        # ── TRANSFORM ──────────────────────────────────────────────────────────
        tf = _sec("Transform")
        r1 = ttk.Frame(tf); r1.pack(fill=X)
        ttk.Button(r1, text="↻ 90° CW",  command=self._img_rotate_cw,  width=10).pack(side=LEFT, padx=(0,2))
        ttk.Button(r1, text="↺ 90° CCW", command=self._img_rotate_ccw, width=10).pack(side=LEFT)
        r2 = ttk.Frame(tf); r2.pack(fill=X, pady=(3, 0))
        ttk.Button(r2, text="↔ Flip H", command=self._img_flip_h, width=10).pack(side=LEFT, padx=(0,2))
        ttk.Button(r2, text="↕ Flip V", command=self._img_flip_v, width=10).pack(side=LEFT)
        ttk.Label(tf, text="Fine rotation:", font=("Arial", 8), foreground="#555").pack(anchor=W, pady=(6,0))
        fr_row = ttk.Frame(tf); fr_row.pack(fill=X)
        self._fine_rot_lbl = ttk.Label(fr_row, text="0.0°", width=6, anchor=E, font=("Arial", 8))
        self._fine_rot_lbl.pack(side=RIGHT)
        self._sl_adj_fine_rotate = ttk.Scale(fr_row, from_=-45, to=45, orient=HORIZONTAL,
                                              command=self._on_fine_rotate_change)
        self._sl_adj_fine_rotate.set(0)
        self._sl_adj_fine_rotate.pack(side=LEFT, fill=X, expand=True, padx=(0, 4))
        self._sl_adj_fine_rotate.bind("<MouseWheel>", _sp_wheel)
        ttk.Button(tf, text="Reset transform", command=self._img_reset_transform).pack(fill=X, pady=(5,0))

        # ── CROP ───────────────────────────────────────────────────────────────
        cr = _sec("Crop")
        ar_row = ttk.Frame(cr); ar_row.pack(fill=X)
        ttk.Label(ar_row, text="Aspect:", width=8, anchor=W).pack(side=LEFT)
        self._crop_aspect_var = StringVar(value="Free")
        ar_cb = ttk.Combobox(ar_row, textvariable=self._crop_aspect_var, state="readonly",
                              values=["Free", "1:1 Square", "ID Card (1.59:1)", "4:3", "16:9",
                                      "A4 Portrait", "3:4 Portrait"],
                              width=13)
        ar_cb.pack(side=LEFT, padx=(4, 0))
        ar_cb.bind("<<ComboboxSelected>>",
                   lambda _e: setattr(self, "_crop_aspect", self._crop_aspect_var.get()))
        cb_row = ttk.Frame(cr); cb_row.pack(fill=X, pady=(5, 0))
        self._crop_btn = ttk.Button(cb_row, text="✂ Draw Crop", command=self._img_toggle_crop)
        self._crop_btn.pack(side=LEFT, fill=X, expand=True, padx=(0, 2))
        ttk.Button(cb_row, text="✕ Clear", command=self._img_crop_clear, width=6).pack(side=LEFT)
        ttk.Button(cr, text="Apply Crop to Image", command=self._img_apply_crop).pack(fill=X, pady=(4,0))

        # ── ADJUSTMENTS ────────────────────────────────────────────────────────
        adj = _sec("Adjustments")
        _adj_slider(adj, "Brightness",  "_adj_brightness",  0.2, 3.0, 1.0)
        _adj_slider(adj, "Contrast",    "_adj_contrast",    0.2, 3.0, 1.0)
        _adj_slider(adj, "Saturation",  "_adj_saturation",  0.0, 3.0, 1.0)
        _adj_slider(adj, "Sharpness",   "_adj_sharpness",   0.0, 3.0, 1.0)
        ttk.Button(adj, text="Reset adjustments", command=self._img_reset_adjustments).pack(fill=X, pady=(5,0))

        # ── COLOR ──────────────────────────────────────────────────────────────
        col = _sec("Color")
        ttk.Label(col, text="Temperature:", font=("Arial", 8), foreground="#555").pack(anchor=W)
        temp_row = ttk.Frame(col); temp_row.pack(fill=X)
        ttk.Label(temp_row, text="❄ Cool", foreground="#4499ff", font=("Arial", 7)).pack(side=LEFT)
        self._temp_val_lbl = ttk.Label(temp_row, text="0", width=4, anchor=CENTER, font=("Arial", 8))
        self._temp_val_lbl.pack(side=LEFT, fill=X, expand=True)
        ttk.Label(temp_row, text="Warm 🔥", foreground="#ff7733", font=("Arial", 7)).pack(side=RIGHT)
        self._sl_adj_temperature = ttk.Scale(col, from_=-100, to=100, orient=HORIZONTAL,
                                              command=self._on_temperature_change)
        self._sl_adj_temperature.set(0)
        self._sl_adj_temperature.pack(fill=X, padx=2, pady=(0,4))
        self._sl_adj_temperature.bind("<MouseWheel>", _sp_wheel)

        ttk.Label(col, text="Hue shift:", font=("Arial", 8), foreground="#555").pack(anchor=W)
        hue_row = ttk.Frame(col); hue_row.pack(fill=X)
        self._hue_val_lbl = ttk.Label(hue_row, text="0°", width=5, anchor=E, font=("Arial", 8))
        self._hue_val_lbl.pack(side=RIGHT)
        self._sl_adj_hue = ttk.Scale(hue_row, from_=-180, to=180, orient=HORIZONTAL,
                                      command=self._on_hue_change)
        self._sl_adj_hue.set(0)
        self._sl_adj_hue.pack(side=LEFT, fill=X, expand=True, padx=(0,4))
        self._sl_adj_hue.bind("<MouseWheel>", _sp_wheel)
        ttk.Button(col, text="Reset color", command=self._img_reset_color).pack(fill=X, pady=(5,0))

        # ── RESIZE ─────────────────────────────────────────────────────────────
        rs = _sec("Resize")
        try:
            from PIL import Image as _PilTmp
            _t = _PilTmp.open(self._path); ow, oh = _t.size; _t.close()
        except Exception:
            ow, oh = 0, 0
        self._resize_orig = (ow, oh)
        if ow:
            ttk.Label(rs, text=f"Original: {ow} × {oh} px",
                      font=FONT_XS, foreground=SFM_MUTED).pack(anchor=W)
        self._resize_w_var = StringVar(value=str(ow) if ow else "")
        self._resize_h_var = StringVar(value=str(oh) if oh else "")
        self._resize_lock_var = tkinter.BooleanVar(value=True)
        dim_row = ttk.Frame(rs); dim_row.pack(fill=X, pady=(4,0))
        ttk.Label(dim_row, text="W:").pack(side=LEFT)
        ttk.Entry(dim_row, textvariable=self._resize_w_var, width=6).pack(side=LEFT, padx=(2,6))
        ttk.Label(dim_row, text="H:").pack(side=LEFT)
        ttk.Entry(dim_row, textvariable=self._resize_h_var, width=6).pack(side=LEFT, padx=(2,0))
        ttk.Checkbutton(rs, text="Lock aspect ratio", variable=self._resize_lock_var).pack(anchor=W, pady=(3,0))

        def _w_trace(*_):
            if not self._resize_lock_var.get(): return
            try:
                nw = int(self._resize_w_var.get())
                ow2, oh2 = self._resize_orig
                if ow2 and oh2:
                    self._resize_h_var.set(str(int(round(nw * oh2 / ow2))))
            except (ValueError, ZeroDivisionError): pass
        def _h_trace(*_):
            if not self._resize_lock_var.get(): return
            try:
                nh = int(self._resize_h_var.get())
                ow2, oh2 = self._resize_orig
                if ow2 and oh2:
                    self._resize_w_var.set(str(int(round(nh * ow2 / oh2))))
            except (ValueError, ZeroDivisionError): pass
        self._resize_w_var.trace_add("write", _w_trace)
        self._resize_h_var.trace_add("write", _h_trace)
        ttk.Button(rs, text="Apply Resize", command=self._img_apply_resize).pack(fill=X, pady=(5,0))

        # ── ID CARD → A4 ───────────────────────────────────────────────────────
        id_sec = _sec("ID Card → A4")
        ttk.Label(id_sec,
                  text="Arrange front & back ID cards\non a single A4 page.",
                  font=("Arial", 8), foreground="#555", justify=LEFT).pack(anchor=W)
        ttk.Button(id_sec, text="🪪 Open ID Card Layout…",
                   command=self._open_id_card_layout).pack(fill=X, pady=(6,0))

        # ── RESET ALL ──────────────────────────────────────────────────────────
        ttk.Separator(inner, orient="horizontal").pack(fill=X, padx=4, pady=8)
        ttk.Button(inner, text="↩ Reset ALL edits",
                   command=self._img_reset_all).pack(fill=X, padx=4, pady=(0,10))

        return outer

    # ── side-panel callbacks ──────────────────────────────────────────────────

    def _on_fine_rotate_change(self, val) -> None:
        self._adj_fine_rotate = float(val)
        try:
            self._fine_rot_lbl.configure(text=f"{self._adj_fine_rotate:.1f}°")
        except tkinter.TclError:
            pass
        self._schedule_render()

    def _on_temperature_change(self, val) -> None:
        self._adj_temperature = float(val)
        try:
            self._temp_val_lbl.configure(text=f"{int(self._adj_temperature):+d}")
        except tkinter.TclError:
            pass
        self._schedule_render()

    def _on_hue_change(self, val) -> None:
        self._adj_hue = float(val)
        try:
            self._hue_val_lbl.configure(text=f"{int(self._adj_hue):+d}°")
        except tkinter.TclError:
            pass
        self._schedule_render()

    def _img_reset_transform(self) -> None:
        self._adj_rotation = 0
        self._adj_flip_h = self._adj_flip_v = False
        self._adj_fine_rotate = 0.0
        for sl_attr in ("_sl_adj_fine_rotate",):
            sl = getattr(self, sl_attr, None)
            if sl:
                try: sl.set(0)
                except tkinter.TclError: pass
        try: self._fine_rot_lbl.configure(text="0.0°")
        except tkinter.TclError: pass
        self._schedule_render()

    def _img_reset_adjustments(self) -> None:
        self._adj_brightness = self._adj_contrast = self._adj_sharpness = self._adj_saturation = 1.0
        for attr in ("_adj_brightness", "_adj_contrast", "_adj_sharpness", "_adj_saturation"):
            sl = getattr(self, f"_sl_{attr.lstrip('_')}", None)
            if sl:
                try: sl.set(1.0)
                except tkinter.TclError: pass
        self._schedule_render()

    def _img_reset_color(self) -> None:
        self._adj_temperature = self._adj_hue = 0.0
        for sl_attr in ("_sl_adj_temperature", "_sl_adj_hue"):
            sl = getattr(self, sl_attr, None)
            if sl:
                try: sl.set(0)
                except tkinter.TclError: pass
        try: self._temp_val_lbl.configure(text="0")
        except tkinter.TclError: pass
        try: self._hue_val_lbl.configure(text="0°")
        except tkinter.TclError: pass
        self._schedule_render()

    def _img_crop_clear(self) -> None:
        self._crop_rect = None
        self._crop_mode = False
        try: self._crop_btn.configure(text="✂ Draw Crop")
        except tkinter.TclError: pass
        self._canvas.config(cursor="arrow")
        self._schedule_render()

    def _img_apply_crop(self) -> None:
        """Bake current crop into _pil_original so it becomes the new base image."""
        if not self._crop_rect:
            messagebox.showinfo("Crop", "Draw a crop selection first.", parent=self)
            return
        img = self._get_adjusted_image()
        if img is None:
            return
        # img already has crop applied — set it as new original, clear state
        self._pil_original = img.copy()
        self._crop_rect = None
        self._crop_mode = False
        # Reset all adjustments since they're now baked in
        self._adj_brightness = self._adj_contrast = self._adj_sharpness = self._adj_saturation = 1.0
        self._adj_temperature = self._adj_hue = self._adj_fine_rotate = 0.0
        self._adj_rotation = 0
        self._adj_flip_h = self._adj_flip_v = False
        self._img_reset_adjustments()
        self._img_reset_color()
        self._img_reset_transform()
        try: self._crop_btn.configure(text="✂ Draw Crop")
        except tkinter.TclError: pass
        # Update resize info
        self._resize_orig = self._pil_original.size
        if self._resize_w_var:
            self._resize_w_var.set(str(self._pil_original.width))
        if self._resize_h_var:
            self._resize_h_var.set(str(self._pil_original.height))
        self._schedule_render()
        messagebox.showinfo("Crop Applied",
                            "Crop applied. Use 💾 Save to write to disk.", parent=self)

    def _img_apply_resize(self) -> None:
        """Resize _pil_original to the entered dimensions."""
        if self._resize_w_var is None:
            return
        try:
            nw = int(self._resize_w_var.get())
            nh = int(self._resize_h_var.get())
        except ValueError:
            messagebox.showerror("Resize", "Enter valid integer width and height.", parent=self)
            return
        if nw < 1 or nh < 1:
            messagebox.showerror("Resize", "Width and height must be ≥ 1.", parent=self)
            return
        from PIL import Image as _Pil
        try:
            if self._pil_original is None:
                self._pil_original = _Pil.open(self._path).convert("RGB")
            self._pil_original = self._pil_original.resize((nw, nh), _Pil.LANCZOS)
            self._resize_orig = (nw, nh)
            self._schedule_render()
            messagebox.showinfo("Resized",
                                "Resized to " + str(nw) + " x " + str(nh) + " px. Use Save to write to disk.",
                                parent=self)
        except Exception as ex:
            messagebox.showerror("Resize Error", str(ex), parent=self)

    def _open_id_card_layout(self) -> None:
        """Open the ID Card → A4 layout composer."""
        IdCardOnA4Dialog(self, source_path=self._path)

    def _get_adjusted_image(self):
        """Return PIL image with all current adjustments applied."""
        from PIL import Image, ImageEnhance
        try:
            if self._pil_original is None:
                self._pil_original = Image.open(self._path).convert("RGB")
            img = self._pil_original.copy()
        except Exception:
            return None

        # 1. Crop (on original coordinates)
        if self._crop_rect:
            w, h = img.size
            x1, y1, x2, y2 = self._crop_rect
            x1, x2 = max(0, min(x1, x2)), min(w, max(x1, x2))
            y1, y2 = max(0, min(y1, y2)), min(h, max(y1, y2))
            if x2 > x1 and y2 > y1:
                img = img.crop((x1, y1, x2, y2))

        # 2. 90° rotation steps
        if self._adj_rotation != 0:
            img = img.rotate(-self._adj_rotation, expand=True)

        # 3. Fine rotation (arbitrary angle)
        fine = getattr(self, "_adj_fine_rotate", 0.0)
        if abs(fine) > 0.05:
            img = img.rotate(-fine, expand=True, resample=Image.BICUBIC)

        # 4. Flips
        if self._adj_flip_h:
            img = img.transpose(Image.FLIP_LEFT_RIGHT)
        if self._adj_flip_v:
            img = img.transpose(Image.FLIP_TOP_BOTTOM)

        # 5. Brightness / Contrast / Saturation / Sharpness
        if abs(self._adj_brightness - 1.0) > 0.01:
            img = ImageEnhance.Brightness(img).enhance(self._adj_brightness)
        if abs(self._adj_contrast - 1.0) > 0.01:
            img = ImageEnhance.Contrast(img).enhance(self._adj_contrast)
        sat = getattr(self, "_adj_saturation", 1.0)
        if abs(sat - 1.0) > 0.01:
            img = ImageEnhance.Color(img).enhance(sat)
        if abs(self._adj_sharpness - 1.0) > 0.01:
            img = ImageEnhance.Sharpness(img).enhance(self._adj_sharpness)

        # 6. Color temperature (LUT channel shift — fast)
        temp = getattr(self, "_adj_temperature", 0.0)
        if abs(temp) > 0.5:
            t = temp / 100.0  # -1 … +1
            r_lut = bytes([min(255, max(0, int(i * (1.0 + t * 0.30)))) for i in range(256)])
            b_lut = bytes([min(255, max(0, int(i * (1.0 - t * 0.30)))) for i in range(256)])
            r, g, b = img.split()
            r = r.point(r_lut)
            b = b.point(b_lut)
            img = Image.merge("RGB", (r, g, b))

        # 7. Hue shift (numpy-accelerated when available, else skip gracefully)
        hue_deg = getattr(self, "_adj_hue", 0.0)
        if abs(hue_deg) > 0.5:
            try:
                import numpy as np
                arr = np.array(img, dtype=np.float32) / 255.0
                # Convert RGB→HSV vectorised
                r, g, b = arr[..., 0], arr[..., 1], arr[..., 2]
                cmax = np.maximum(np.maximum(r, g), b)
                cmin = np.minimum(np.minimum(r, g), b)
                delta = cmax - cmin
                # Hue
                h = np.zeros_like(cmax)
                mask = delta > 0
                mr = (cmax == r) & mask
                mg = (cmax == g) & mask
                mb = (cmax == b) & mask
                h[mr] = ((g[mr] - b[mr]) / delta[mr]) % 6
                h[mg] = (b[mg] - r[mg]) / delta[mg] + 2
                h[mb] = (r[mb] - g[mb]) / delta[mb] + 4
                h = (h / 6.0 + hue_deg / 360.0) % 1.0  # shift
                # Saturation
                s = np.where(cmax > 0, delta / cmax, 0.0)
                # Value
                v = cmax
                # HSV → RGB
                i = (h * 6).astype(np.int32)
                f = h * 6 - i
                p = v * (1 - s)
                q = v * (1 - f * s)
                t2 = v * (1 - (1 - f) * s)
                i6 = i % 6
                ro = np.select(
                    [i6==0, i6==1, i6==2, i6==3, i6==4, i6==5],
                    [v, q, p, p, t2, v])
                go = np.select(
                    [i6==0, i6==1, i6==2, i6==3, i6==4, i6==5],
                    [t2, v, v, q, p, p])
                bo = np.select(
                    [i6==0, i6==1, i6==2, i6==3, i6==4, i6==5],
                    [p, p, t2, v, v, q])
                out = np.stack([ro, go, bo], axis=-1)
                img = Image.fromarray((np.clip(out, 0, 1) * 255).astype(np.uint8))
            except ImportError:
                pass  # numpy not available — skip hue shift

        return img

    def _img_slider_changed(self, attr: str, val) -> None:
        setattr(self, attr, float(val))
        self._schedule_render()

    def _img_rotate_cw(self) -> None:
        self._adj_rotation = (self._adj_rotation + 90) % 360
        self._schedule_render()

    def _img_rotate_ccw(self) -> None:
        self._adj_rotation = (self._adj_rotation - 90) % 360
        self._schedule_render()

    def _img_flip_h(self) -> None:
        self._adj_flip_h = not self._adj_flip_h
        self._schedule_render()

    def _img_flip_v(self) -> None:
        self._adj_flip_v = not self._adj_flip_v
        self._schedule_render()

    def _img_reset_all(self) -> None:
        self._adj_brightness = self._adj_contrast = self._adj_sharpness = self._adj_saturation = 1.0
        self._adj_temperature = self._adj_hue = self._adj_fine_rotate = 0.0
        self._adj_rotation = 0
        self._adj_flip_h = self._adj_flip_v = False
        self._crop_rect = None
        self._crop_mode = False
        self._pil_original = None  # reload from disk
        for attr in ("_adj_brightness", "_adj_contrast", "_adj_sharpness", "_adj_saturation"):
            sl = getattr(self, f"_sl_{attr.lstrip('_')}", None)
            if sl:
                try: sl.set(1.0)
                except tkinter.TclError: pass
        for sl_attr in ("_sl_adj_temperature", "_sl_adj_hue", "_sl_adj_fine_rotate"):
            sl = getattr(self, sl_attr, None)
            if sl:
                try: sl.set(0)
                except tkinter.TclError: pass
        try: self._temp_val_lbl.configure(text="0")
        except tkinter.TclError: pass
        try: self._hue_val_lbl.configure(text="0°")
        except tkinter.TclError: pass
        try: self._fine_rot_lbl.configure(text="0.0°")
        except tkinter.TclError: pass
        try: self._crop_btn.configure(text="✂ Draw Crop")
        except tkinter.TclError: pass
        self._schedule_render()

    def _img_toggle_crop(self) -> None:
        self._crop_mode = not self._crop_mode
        if not self._crop_mode:
            self._crop_rect = None
        try:
            self._crop_btn.configure(text=("✂ Crop ●" if self._crop_mode else "✂ Crop"))
        except tkinter.TclError:
            pass
        self._canvas.config(cursor="crosshair" if self._crop_mode else "arrow")
        if not self._crop_mode:
            self._schedule_render()

    def _img_canvas_press(self, event: tkinter.Event) -> None:
        if not self._is_image or not self._crop_mode:
            self._on_drag_start(event)
            return
        self._crop_drag_start = (event.x, event.y)

    def _img_canvas_motion(self, event: tkinter.Event) -> None:
        if not self._is_image or not self._crop_mode or not self._crop_drag_start:
            self._on_drag_motion(event)
            return
        off = getattr(self, "_img_display_offset", (0, 0, 1, 1))
        ix, iy, iw, ih = off
        orig = self._pil_original
        if orig is None:
            return
        ow, oh = orig.size
        # Map from canvas coords to original image coords
        def to_img(cx, cy):
            px = (cx - ix) / iw * ow
            py = (cy - iy) / ih * oh
            return int(max(0, min(px, ow))), int(max(0, min(py, oh)))
        x1, y1 = to_img(*self._crop_drag_start)
        x2, y2 = to_img(event.x, event.y)
        self._crop_rect = (min(x1, x2), min(y1, y2), max(x1, x2), max(y1, y2))
        self._schedule_render()

    def _img_canvas_release(self, event: tkinter.Event) -> None:
        if self._is_image and self._crop_mode:
            self._crop_drag_start = None
        else:
            self._on_drag_end(event)

    def _img_save(self) -> None:
        """Save adjustments back to the original file."""
        img = self._get_adjusted_image()
        if img is None:
            return
        try:
            ext = os.path.splitext(self._path)[1].lower()
            if ext in (".jpg", ".jpeg", ".jfif"):
                img.save(self._path, "JPEG", quality=95)
            elif ext == ".png":
                img.save(self._path, "PNG")
            elif ext == ".webp":
                img.save(self._path, "WEBP", quality=95)
            elif ext in (".tif", ".tiff"):
                img.save(self._path, "TIFF")
            elif ext == ".bmp":
                img.save(self._path, "BMP")
            else:
                img.save(self._path)
            self._pil_original = img.copy()
            messagebox.showinfo("Saved", "Saved to:\n" + self._path, parent=self)
        except Exception as ex:
            messagebox.showerror("Save Error", str(ex), parent=self)

    def _img_convert_save(self, fmt: str) -> None:
        """Save adjusted image as a new file in the chosen format."""
        from tkinter.filedialog import asksaveasfilename
        ext = "." + fmt.lower()
        init_name = os.path.splitext(os.path.basename(self._path))[0] + ext
        dest = asksaveasfilename(
            parent=self,
            initialfile=init_name,
            initialdir=os.path.dirname(self._path),
            defaultextension=ext,
            filetypes=[(fmt.upper() + " files", f"*{ext}"), ("All files", "*.*")],
        )
        if not dest:
            return
        img = self._get_adjusted_image()
        if img is None:
            return
        try:
            if fmt == "jpg":
                img.save(dest, "JPEG", quality=95)
            else:
                img.save(dest, "PNG")
            messagebox.showinfo("Saved", "Saved as:\n" + dest, parent=self)
        except Exception as ex:
            messagebox.showerror("Save Error", str(ex), parent=self)


    def _show_print_dialog(self) -> None:
        """Open full print dialog for the current file."""
        dlg = PrintDialog(
            self,
            path=self._path,
            page_count=self._total,
            current_page=self._page,
        )
        dlg.wait_window()
        if dlg.result:
            _execute_print_job(dlg.result, log_fn=None)


class IdCardOnA4Dialog(Toplevel):
    """Compose front + back ID card images on a single A4 page and save / print."""

    # Standard ID card: 85.60 × 53.98 mm  →  ratio ≈ 1.586
    CARD_W_MM = 85.6
    CARD_H_MM = 54.0
    A4_W_MM   = 210.0
    A4_H_MM   = 297.0

    # Render A4 preview at this width (px); height is proportional
    PREVIEW_W = 480

    def __init__(self, master, *, source_path: str = "") -> None:
        super().__init__(master)
        self.title("ID Card → A4 Layout")
        self.transient(master)
        self.resizable(True, True)

        try:
            px = master.winfo_rootx() + 30
            py = master.winfo_rooty() + 30
            self.geometry(f"820x640+{px}+{py}")
        except tkinter.TclError:
            self.geometry("820x640")

        self.minsize(700, 520)

        # --- state ---
        self._front_path = source_path
        self._back_path  = ""
        self._margin_mm  = 10.0          # page margin
        self._gap_mm     = 5.0           # gap between cards
        self._copies     = 1             # copies of front+back pair per page
        self._landscape  = False
        self._a4_pil     = None          # cached rendered A4 PIL image
        self._preview_photo = None

        self._build_ui()
        self.after_idle(self._refresh_preview)

    # ── UI ────────────────────────────────────────────────────────────────────

    def _build_ui(self) -> None:
        # Top toolbar
        tb = ttk.Frame(self, padding=(8, 6))
        tb.pack(side=TOP, fill=X)
        ttk.Button(tb, text="💾 Save A4 as…", command=self._save_a4).pack(side=LEFT, padx=(0,4))
        ttk.Button(tb, text="🖨 Print…",       command=self._print_a4).pack(side=LEFT, padx=(0,16))
        ttk.Button(tb, text="✕ Close",         command=self.destroy).pack(side=RIGHT)

        # Main split: controls LEFT, preview RIGHT
        main = ttk.Frame(self)
        main.pack(fill=BOTH, expand=True, padx=8, pady=(0,8))

        ctrl = ttk.Frame(main, width=280)
        ctrl.pack(side=LEFT, fill=Y, padx=(0,8))
        ctrl.pack_propagate(False)
        self._build_controls(ctrl)

        # Preview canvas
        prev_fr = ttk.LabelFrame(main, text="A4 Preview")
        prev_fr.pack(side=LEFT, fill=BOTH, expand=True)
        self._prev_canvas = tkinter.Canvas(prev_fr, bg="#888", highlightthickness=0)
        self._prev_canvas.pack(fill=BOTH, expand=True, padx=4, pady=4)
        self._prev_canvas.bind("<Configure>", lambda _e: self.after(60, self._refresh_preview))

    def _build_controls(self, parent) -> None:
        def _sec(t):
            lf = ttk.LabelFrame(parent, text=t, padding=(8,6))
            lf.pack(fill=X, pady=(0,8))
            return lf

        # ── Front image ──────────────────────────────────────────────────────
        fi = _sec("Front card image")
        self._front_lbl = ttk.Label(fi, text=self._short(self._front_path) or "(none)",
                                    foreground="#444", font=("Arial", 8), wraplength=220)
        self._front_lbl.pack(anchor=W)
        ttk.Button(fi, text="Browse…", command=self._browse_front).pack(anchor=W, pady=(4,0))

        # ── Back image ───────────────────────────────────────────────────────
        bi = _sec("Back card image (optional)")
        self._back_lbl = ttk.Label(bi, text="(none)", foreground="#888",
                                   font=("Arial", 8), wraplength=220)
        self._back_lbl.pack(anchor=W)
        ttk.Button(bi, text="Browse…", command=self._browse_back).pack(anchor=W, pady=(4,0))
        ttk.Button(bi, text="✕ Remove back", command=self._clear_back).pack(anchor=W, pady=(2,0))

        # ── Layout ───────────────────────────────────────────────────────────
        lo = _sec("Layout")

        def _mm_row(lf, label, attr, lo_v, hi_v, step=0.5):
            row = ttk.Frame(lf); row.pack(fill=X, pady=2)
            ttk.Label(row, text=label, width=14, anchor=W).pack(side=LEFT)
            var = StringVar(value=str(getattr(self, attr)))
            def _apply(*_):
                try:
                    v = float(var.get())
                    setattr(self, attr, max(lo_v, min(hi_v, v)))
                except ValueError: pass
                self._refresh_preview()
            ttk.Entry(row, textvariable=var, width=7).pack(side=LEFT)
            ttk.Label(row, text="mm").pack(side=LEFT, padx=(2,0))
            var.trace_add("write", _apply)

        _mm_row(lo, "Page margin:", "_margin_mm", 0, 40)
        _mm_row(lo, "Card gap:",    "_gap_mm",    0, 20)

        cop_row = ttk.Frame(lo); cop_row.pack(fill=X, pady=2)
        ttk.Label(cop_row, text="Copies/page:", width=14, anchor=W).pack(side=LEFT)
        self._copies_var = StringVar(value="1")
        def _cop_apply(*_):
            try:
                self._copies = max(1, min(8, int(self._copies_var.get())))
            except ValueError: pass
            self._refresh_preview()
        ttk.Spinbox(cop_row, from_=1, to=8, textvariable=self._copies_var,
                    width=5, command=_cop_apply).pack(side=LEFT)
        self._copies_var.trace_add("write", _cop_apply)

        self._landscape_var = tkinter.BooleanVar(value=False)
        ttk.Checkbutton(lo, text="Landscape A4",
                        variable=self._landscape_var,
                        command=self._on_landscape_toggle).pack(anchor=W, pady=(4,0))

        # ── Card size info ───────────────────────────────────────────────────
        info = _sec("Card size")
        ttk.Label(info, text=f"Standard: {self.CARD_W_MM} × {self.CARD_H_MM} mm",
                  font=("Arial", 8), foreground="#555").pack(anchor=W)
        ttk.Label(info, text="(ISO/IEC 7810 ID-1)",
                  font=("Arial", 8), foreground="#888").pack(anchor=W)

    # ── helpers ───────────────────────────────────────────────────────────────

    @staticmethod
    def _short(path: str) -> str:
        if not path:
            return ""
        b = os.path.basename(path)
        return b if len(b) <= 28 else b[:25] + "…"

    def _browse_front(self) -> None:
        from tkinter.filedialog import askopenfilename
        p = askopenfilename(parent=self,
                            title="Select front card image",
                            filetypes=[("Images", "*.jpg *.jpeg *.png *.bmp *.tif *.tiff *.webp"),
                                       ("All files", "*.*")])
        if p:
            self._front_path = p
            self._front_lbl.configure(text=self._short(p))
            self._refresh_preview()

    def _browse_back(self) -> None:
        from tkinter.filedialog import askopenfilename
        p = askopenfilename(parent=self,
                            title="Select back card image",
                            filetypes=[("Images", "*.jpg *.jpeg *.png *.bmp *.tif *.tiff *.webp"),
                                       ("All files", "*.*")])
        if p:
            self._back_path = p
            self._back_lbl.configure(text=self._short(p))
            self._refresh_preview()

    def _clear_back(self) -> None:
        self._back_path = ""
        self._back_lbl.configure(text="(none)")
        self._refresh_preview()

    def _on_landscape_toggle(self) -> None:
        self._landscape = self._landscape_var.get()
        self._refresh_preview()

    # ── A4 composition ───────────────────────────────────────────────────────

    def _compose_a4_pil(self, out_px_w: int = 2480) -> "PIL.Image.Image | None":
        """Render an A4 PIL image (300 DPI = 2480×3508) with the cards placed."""
        from PIL import Image as Pil
        a4w_mm, a4h_mm = (self.A4_H_MM, self.A4_W_MM) if self._landscape                          else (self.A4_W_MM, self.A4_H_MM)
        scale = out_px_w / a4w_mm          # px per mm
        a4w_px = int(a4w_mm * scale)
        a4h_px = int(a4h_mm * scale)
        card_w_px = int(self.CARD_W_MM * scale)
        card_h_px = int(self.CARD_H_MM * scale)
        margin_px = int(self._margin_mm * scale)
        gap_px    = int(self._gap_mm * scale)

        a4 = Pil.new("RGB", (a4w_px, a4h_px), "white")

        # Load card images
        cards = []
        for p in ([self._front_path] + ([self._back_path] if self._back_path else [])):
            if not p or not os.path.isfile(p):
                # Placeholder grey card
                ph = Pil.new("RGB", (card_w_px, card_h_px), "#cccccc")
                cards.append(ph)
                continue
            try:
                img = Pil.open(p).convert("RGB")
                img = img.resize((card_w_px, card_h_px), Pil.LANCZOS)
                cards.append(img)
            except Exception:
                ph = Pil.new("RGB", (card_w_px, card_h_px), "#ffcccc")
                cards.append(ph)

        # Tile cards: place self._copies × (front [+ back]) pairs
        x, y = margin_px, margin_px
        for _copy in range(self._copies):
            for card in cards:
                # Wrap to next row if no horizontal space
                if x + card_w_px > a4w_px - margin_px:
                    x = margin_px
                    y += card_h_px + gap_px
                # Wrap to next page column not possible — just stop if out of vertical space
                if y + card_h_px > a4h_px - margin_px:
                    break
                a4.paste(card, (x, y))
                x += card_w_px + gap_px
            x = margin_px
            y += card_h_px + gap_px
            if y + card_h_px > a4h_px - margin_px:
                break

        return a4

    def _refresh_preview(self) -> None:
        """Render preview in the canvas."""
        from PIL import ImageTk
        cw = max(self._prev_canvas.winfo_width(), 200)
        ch = max(self._prev_canvas.winfo_height(), 200)
        try:
            a4 = self._compose_a4_pil(out_px_w=self.PREVIEW_W)
        except Exception:
            return
        if a4 is None:
            return
        # Fit into canvas
        aw, ah = a4.size
        scale = min(cw / aw, ch / ah, 1.0)
        pw, ph = max(1, int(aw * scale)), max(1, int(ah * scale))
        thumb = a4.resize((pw, ph), 1)  # LANCZOS=1
        self._preview_photo = ImageTk.PhotoImage(thumb)
        self._prev_canvas.delete("all")
        self._prev_canvas.configure(scrollregion=(0, 0, cw, ch))
        ix = (cw - pw) // 2
        iy = (ch - ph) // 2
        self._prev_canvas.create_image(ix, iy, image=self._preview_photo, anchor="nw")

    # ── output ────────────────────────────────────────────────────────────────

    def _save_a4(self) -> None:
        from tkinter.filedialog import asksaveasfilename
        dest = asksaveasfilename(
            parent=self,
            title="Save A4 layout as…",
            defaultextension=".jpg",
            filetypes=[("JPEG", "*.jpg"), ("PNG", "*.png"), ("PDF", "*.pdf"), ("All files", "*.*")],
            initialfile="id_card_a4.jpg",
        )
        if not dest:
            return
        try:
            a4 = self._compose_a4_pil(out_px_w=2480)
            ext = os.path.splitext(dest)[1].lower()
            if ext == ".pdf":
                a4.save(dest, "PDF", resolution=300)
            elif ext == ".png":
                a4.save(dest, "PNG")
            else:
                a4.save(dest, "JPEG", quality=95)
            messagebox.showinfo("Saved", "Saved to: " + dest, parent=self)
        except Exception as ex:
            messagebox.showerror("Save Error", str(ex), parent=self)

    def _print_a4(self) -> None:
        """Save to a temp file and open PrintDialog."""
        import tempfile
        try:
            a4 = self._compose_a4_pil(out_px_w=2480)
            tmp = tempfile.NamedTemporaryFile(suffix=".jpg", delete=False)
            a4.save(tmp.name, "JPEG", quality=95)
            tmp.close()
        except Exception as ex:
            messagebox.showerror("Error", str(ex), parent=self)
            return
        dlg = PrintDialog(self, path=tmp.name, page_count=1, current_page=0)
        dlg.wait_window()
        if dlg.result:
            _execute_print_job(dlg.result, log_fn=None)


class FilesWorkspaceFrame(ttk.Frame):
    """Load a folder or ZIP, show a full tree, rename files and folders (double-click or F2)."""

    # Rasterize images/PDF at this factor of the on-screen preview box, then downsample for sharp full-page fit.
    PREVIEW_SUPERSAMPLE = 1.6
    PDF_PREVIEW_MAX_ZOOM = 4.0
    # Slightly larger "fit" target than raw canvas inner size so previews fill the panel (tiny scroll if needed).
    PREVIEW_FIT_BLEED_PX = 10
    PREVIEW_ZOOM_STEP = 1.11
    PREVIEW_ZOOM_MIN = 0.3
    PREVIEW_ZOOM_MAX = 6.0
    # Keyboard zoom per key-repeat tick (smooth with OS key repeat).
    PREVIEW_ZOOM_KEY_MULTIPLIER = 1.035
    # Debounce full PDF/image reraster on zoom (reduces flicker; wheel batches while scrolling).
    PREVIEW_ZOOM_RERENDER_MS = 48
    # Large PDFs: only rasterize thumbnails in the vertical viewport (+ overscan).
    PDF_VIRTUALIZE_THRESHOLD = 20
    PDF_VIEWPORT_OVERSCAN_PAGES = 2
    # ISO A4 width:height for on-screen frame overlay (mm ratio).
    A4_LAYOUT_W_H = 210.0 / 297.0
    # Minimum fallback / canvas height so the preview column stays usable.
    PREVIEW_CANVAS_MIN_HEIGHT = 520
    MULTI_PREVIEW_NUM_SLOTS = 2
    RENAME_UNDO_LIMIT = 100
    # Crop profiles (physical output size in mm). The active profile drives the
    # crop frame aspect ratio and the exported page/image dimensions.
    # ``ID_PHOTO_MM_W`` / ``ID_PHOTO_MM_H`` / ``ID_PHOTO_ASPECT_WH`` are exposed as
    # properties below so existing call-sites keep working with the active profile.
    CROP_PROFILES = (
        ("35×45 mm (passport)", 35.0, 45.0),
        ("A4 portrait (210×297 mm)", 210.0, 297.0),
        ("A4 landscape (297×210 mm)", 297.0, 210.0),
    )
    DEFAULT_CROP_PROFILE = "35×45 mm (passport)"
    IMAGE_CROP_HANDLE = 14
    TREE_PDF_THUMB_BASE_W = 28
    TREE_PDF_THUMB_BASE_H = 36
    TREE_PDF_THUMB_SCALE_MIN = 1.0
    TREE_PDF_THUMB_SCALE_MAX = 4.0
    TREE_PDF_THUMB_SCALE_STEP = 1.12
    THUMB_LABEL_AREA_HEIGHT = 56

    def __init__(self, parent, breadcrumb_parent=None) -> None:
        super().__init__(parent)
        document_rename_load_user_templates()
        # Optional external host (the app's top bar) for the path breadcrumb so it
        # can sit beside the Files/Folders buttons instead of inside this frame.
        self._external_breadcrumb_parent = breadcrumb_parent
        self.folder_var = StringVar(value="")
        self.rename_var = StringVar(value="")

        self._root_path: str = ""

        # Explorer-style navigation history (back / forward / up).
        self._nav_history: list[str] = []
        self._nav_history_pos: int = -1
        self._nav_btn_back: ttk.Button | None = None
        self._nav_btn_fwd: ttk.Button | None = None
        self._nav_btn_up: ttk.Button | None = None

        self._fs_clipboard_paths: list[str] = []
        self._fs_clipboard_is_cut: bool = False
        self._zip_source: str | None = None
        self._temp_extract_dir: str | None = None

        # Tree node ref: ("fs", abs_path) | ("zipf", zip_abs, member) | ("zipd", zip_abs, inner_prefix/)
        self._tree_ref: dict[str, tuple] = {}
        self._tree_iid_seq = 0
        self._tree_pdf_thumb_scale: float = 2.0
        self._files_view_mode = StringVar(value="tree")
        self._thumb_gallery_zoom: float = 1.45
        self._thumb_default_cols: int = 6  # default thumbnails per row
        self._thumb_zoom_user_set: bool = False  # True once the user zooms manually
        self._thumb_zoom_apply_job: str | None = None  # debounce for smooth wheel zoom
        self._thumb_gallery_selection_order: list[tuple] = []
        self._thumb_gallery_cols: int = 1
        self._thumb_shift_anchor_ref: tuple | None = None

        self._rename_entry: tkinter.Entry | None = None
        self._rename_item: str | None = None
        self._rename_old_ref: tuple | None = None
        self._rename_suggest_popup: tkinter.Toplevel | None = None
        self._rename_suggest_listbox: tkinter.Listbox | None = None
        self._rename_suggest_rows: list[tuple[str, str, str]] = []
        self._rename_suggest_priorities: list[int] = []
        self._rename_suggest_ext: str = ""
        self._rename_suggest_anchor: tkinter.Misc | None = None
        self._rename_suggest_for_bottom: bool = False

        self._preview_photo = None
        self._pdf_path: str | None = None
        self._pdf_bytes: bytes | None = None
        self._preview_zip_temp_path: str | None = None
        self._pdf_page = 0
        self._pdf_multi_paths: list[str] = []
        self._pdf_multi_index: int = 0
        self._pdf_page_photo_refs: list = []
        self._pdf_hit_rects: list[tuple[int, float, float]] = []
        self._pdf_page_img_rects: dict[int, tuple[float, float, float, float]] = {}
        self._pdf_selected_pages: set[int] = {0}
        self._pdf_shift_anchor_page: int = 0
        self._pdf_grid_overlay_var = tkinter.BooleanVar(value=False)
        self._pdf_a4_overlay_var = tkinter.BooleanVar(value=False)
        self._pdf_text_mode_var = tkinter.BooleanVar(value=False)
        self._pdf_extracted_text: str = ""
        # ── Visual text-select state ──────────────────────────────────────
        self._pdf_textsel_binds: list = []
        self._pdf_textsel_words: dict = {}      # page_idx → [(x0,y0,x1,y1,word),…]
        self._pdf_textsel_page_pt: dict = {}    # page_idx → (pdf_w, pdf_h) in points
        self._pdf_textsel_page_rects: dict = {} # page_idx → (cx,cy,dw,dh,pw_pt,ph_pt)
        self._pdf_textsel_anchor: "tuple | None" = None
        self._pdf_textsel_end: "tuple | None" = None
        # ─────────────────────────────────────────────────────────────────
        self._pdf_text_readonly_bind_id: str | None = None
        self._pdf_viewport_refresh_job: str | None = None
        # Preview pan: middle mouse (B2) and Alt+left-drag; B2 scan_mark is lazy-seeded on first motion
        # because some Windows/Tk builds omit ButtonPress-2 for the wheel button.
        self._preview_alt_pan_drag: bool = False
        self._preview_b2_scan_seeded: bool = False
        self._tree_shift_anchor_iid: str | None = None
        self._tree_kb_focus_iid: str | None = None
        self._tree_kb_focus_tag_iid: str | None = None
        self._tree_orange_ring_pool: list[list[tkinter.Frame]] = []
        self._tree_blue_ring_parts: list[tkinter.Frame] | None = None
        self._tree_ring_refresh_job: str | None = None
        self._tree_kb_nav_active: bool = False
        self._tree_last_select_iids: frozenset[str] = frozenset()
        self._word_conversion_token: int = 0
        self._word_preview_source: str | None = None

        self._preview_mode: str = "text"
        # On-disk image path when Single preview shows a tree file (not ZIP bytes); used by AI photo tool.
        self.current_image_path: str | None = None
        # When single preview shows a ZIP member image from bytes: ("zipf", zip_path, member)
        self._preview_image_zip_member_ref: tuple[str, str, str] | None = None
        # Stable temp file for AI when preview is image-from-bytes (invalidated when bytes change).
        self._ai_bytes_material_path: str | None = None
        self._ai_bytes_material_hash: str | None = None
        self._preview_image_bytes_ext: str = ".png"
        self._active_ai_source_context: dict | None = None
        self._preview_image_path_for_rerender: str | None = None
        self._preview_image_bytes_for_rerender: bytes | None = None
        self._preview_resize_after: str | None = None
        self._preview_zoom_render_job: str | None = None
        self._preview_zoom_last_rerender_mono = 0.0
        self._preview_user_zoom = 1.0

        self._preview_image_full_pil = None
        self._preview_image_full_cache_key: object | None = None
        self._image_crop_rect_src: tuple[int, int, int, int] | None = None
        self._image_disp_ix = 0
        self._image_disp_iy = 0
        self._image_disp_w = 0
        self._image_disp_h = 0
        self._image_full_w = 0
        self._image_full_h = 0
        self._image_crop_drag: dict | None = None
        self._image_crop_enable_var = tkinter.BooleanVar(value=False)
        self._image_crop_dpi_var = StringVar(value="300")
        self._image_crop_thirds_var = tkinter.BooleanVar(value=False)
        # Active crop profile (drives aspect + exported size). See CROP_PROFILES.
        self._crop_profile_var = StringVar(value=self.DEFAULT_CROP_PROFILE)
        # Fine rotation (degrees, -180..180) applied on top of the base image.
        self._crop_rotation_var = tkinter.DoubleVar(value=0.0)
        # Suppress the Scale ``command`` callback during programmatic var resets.
        self._crop_suppress_rotation_cb = False
        # Perspective (free 4-corner quad) crop mode.
        self._crop_perspective_var = tkinter.BooleanVar(value=False)
        # Unrotated/flipped base image for the current crop source; fine rotation
        # is always re-applied from this so repeated slider moves don't degrade.
        self._crop_base_pil = None
        self._crop_base_key: object = None
        # Perspective quad in full-image source coords: [TL, TR, BR, BL].
        self._crop_quad_src: list[list[float]] | None = None
        # Tone adjustments (brightness/contrast/levels/curve) baked into the
        # working image and the cropped output. Neutral defaults = no change.
        self._adj_brightness = 1.0
        self._adj_contrast = 1.0
        self._adj_black = 0.0
        self._adj_white = 255.0
        self._adj_gamma = 1.0
        self._adj_curve_points: list[list[float]] = [[0.0, 0.0], [255.0, 255.0]]
        self._adjust_dialog = None
        self._adjust_curve_canvas = None
        self._adjust_curve_drag_idx: int | None = None
        self._pdf_crop_active = False
        self._pdf_crop_raster_key: tuple[str, int] | None = None
        # Single-entry render cache: avoids re-rasterising when size hasn't changed.
        # Key: (source_key, page_index, fit_w, fit_h)
        # Value: (ImageTk.PhotoImage, PIL.Image) — hold both to prevent GC
        self._preview_render_cache: dict = {}
        self._preview_render_cache_key: object = None
        self._pdf_crop_save_job: str | None = None
        self._pdf_crop_saving = False

        # Floating page navigator state
        self._pdf_float_nav_total: int = 0
        self._pdf_float_nav_cell_h: float = 0.0
        self._pdf_float_nav_total_h: float = 0.0
        self._pdf_float_nav_margin: int = 4
        self._pdf_float_page_var: StringVar = StringVar(value="1")
        self._pdf_pending_scroll_page: int | None = None

        self.file_search_var = StringVar(value="")
        self._last_search_match_count: int | None = None
        self._live_search_job: str | None = None
        self._suppress_live_search_schedule = False
        self._tree_select_preview_job: str | None = None
        self._tree_preview_iid_pending: str | None = None
        self._auto_refresh_tree_job: str | None = None
        self._last_auto_refresh_fingerprint: object | None = None

        self._txt_edit_path: str | None = None
        self._txt_autosave_job: str | None = None

        # Undo/redo stacks.  Each entry is (tag, payload):
        #   "rename" → (old_ref, new_ref)
        #   "crop"   → {"kind": ..., "path": ..., "data": ...}
        #   "delete" → {"moves": [(original_path, to_review_path), ...]}
        #   "move"   → {"moves": [(original_path, new_path), ...]}
        #   "merge"  → {"output": merged_path}
        #   "create" → {"paths": [created_path, ...], "label": str}
        self._undo_events: list[tuple[str, tuple | dict]] = []
        self._redo_stack: list[tuple[str, tuple | dict]] = []   # (tag, payload)
        # Paths renamed this session — kept at the end of the tree sort
        self._renamed_paths: set[str] = set()

        self.preview_notebook: ttk.Notebook | None = None
        self._single_preview_tab: ttk.Frame | None = None

        self._excel_preview_tab: ttk.Frame | None = None
        self._excel_grid: excel_grid.ExcelGridFrame | None = None
        self._multi_preview_tab: ttk.Frame | None = None
        self._multi_slot_state: list[dict] = []
        n_slots = FilesWorkspaceFrame.MULTI_PREVIEW_NUM_SLOTS
        self._multi_slot_render_job: list[str | None] = [None] * n_slots
        self._multi_slot_zoom_job: list[str | None] = [None] * n_slots
        self._multi_slot_alt_pan_drag: list[bool] = [False] * n_slots
        self._multi_slot_b2_scan_seeded: list[bool] = [False] * n_slots
        self._multi_canvas_menu_slot: int | None = None
        self._multi_canvas_menu = Menu(self, tearoff=0)
        self._multi_canvas_menu.add_command(
            label="Rotate page clockwise (saves to disk)",
            command=lambda: self._multi_canvas_menu_rotate(True),
        )
        self._multi_canvas_menu.add_command(
            label="Rotate page counter-clockwise (saves to disk)",
            command=lambda: self._multi_canvas_menu_rotate(False),
        )
        # Drag files from the tree into dual-preview panes (internal DnD).
        self._tree_drag_b1_start: tuple[int, int] | None = None
        self._tree_drag_armed: bool = False
        self._tree_drag_paths: list[str] | None = None
        self._tree_drag_snapshot_refs_list: list[tuple] = []
        self._tree_drag_temp_files: list[str] = []
        self._tree_drag_grab_active: bool = False
        self._tree_drag_press_iid: str | None = None
        self._tree_drag_preserved_multi: bool = False
        # True after internal tree drag moved enough (avoid empty-tree click → browse on same gesture).
        self._internal_tree_drag_this_button: bool = False
        # True if the current B1 press started on empty tree background (not on a row).
        self._tree_b1_press_empty: bool = False

        self.columnconfigure(0, weight=1)
        self.rowconfigure(0, weight=0)
        self.rowconfigure(1, weight=1)
        self.rowconfigure(2, weight=0)

        self._build_ui()
        self.bind("<Destroy>", self._on_frame_destroy)
        self._auto_refresh_tree_job = self.after(900, self._auto_refresh_tree_tick)
        self.log_message(f"Modules: {self._deps_summary()}")
        self.log_message("Open a folder or ZIP to begin.")

    def _deps_summary(self) -> str:
        parts = []
        parts.append("PIL✓" if fo.get_pillow() else "PIL✗")
        parts.append("MuPDF✓" if fo.get_fitz() else "MuPDF✗")
        parts.append("docx✓" if fo.get_docx() else "docx✗")
        if sys.platform == "win32":
            try:
                import win32com.client  # noqa: F401

                parts.append("win32✓")
            except ImportError:
                parts.append("win32✗")
        return " · ".join(parts)

    # ── Document alert strip ──────────────────────────────────────────────────

    def _show_doc_alert_strip(self, out_paths: list[str], report_path: str = "") -> None:
        """
        Build / refresh the color-coded document status strip above the file tree.

        Compares the basenames of *out_paths* against the master _VISA_CHECKLIST
        keyword list.  Each checklist item gets a badge:
          🟢 green  — found (required count met)
          🟡 amber  — partially found (at least one but below required count)
          🔴 red    — missing entirely
        Clicking any badge opens the checklist Word report if one was generated.
        The "Expiry Map" button triggers Feature 6 heat-map on demand.
        """
        # Remember for on-demand expiry heat map (Feature 6)
        self._doc_alert_out_paths = list(out_paths)
        checklist = fo._VISA_CHECKLIST  # type: ignore[attr-defined]
        if not checklist:
            return

        # Destroy previous badge widgets
        for w in self._doc_alert_strip.winfo_children():
            w.destroy()

        # Build set of lowercase output filenames for matching
        lower_names = [os.path.basename(p).lower() for p in out_paths]

        n_missing = 0
        n_partial = 0

        # Header label
        hdr = tkinter.Frame(self._doc_alert_strip, bg=SFM_APP_BG)
        hdr.pack(fill=X, side=TOP, padx=4, pady=(3, 1))
        tkinter.Label(
            hdr, text="Document Check  →", bg=SFM_APP_BG,
            font=("Segoe UI", 8, "bold"), fg=SFM_TEXT,
        ).pack(side=LEFT, padx=(2, 4))

        if report_path:
            tkinter.Label(
                hdr, text=f"📋 {os.path.basename(report_path)}",
                bg=SFM_APP_BG, fg=SFM_ACCENT, font=("Segoe UI", 8),
                cursor="hand2",
            ).pack(side=RIGHT, padx=4)

        # Feature 6 — Expiry heat map trigger button
        expiry_btn = tkinter.Label(
            hdr, text="📅 Expiry Map", bg=SFM_PANEL_BG, fg=SFM_ACCENT,
            font=("Segoe UI", 8, "bold"), cursor="hand2", relief="flat",
            padx=6, pady=1,
        )
        expiry_btn.pack(side=RIGHT, padx=4)
        expiry_btn.bind("<Button-1>", lambda _e: self._open_expiry_heatmap())

        close_btn = tkinter.Label(
            hdr, text="✕", bg=SFM_APP_BG, fg=SFM_MUTED,
            font=("Segoe UI", 9), cursor="hand2",
        )
        close_btn.pack(side=RIGHT)
        close_btn.bind("<Button-1>", lambda _e: self._hide_doc_alert_strip())

        # Badge row
        badge_row = tkinter.Frame(self._doc_alert_strip, bg=SFM_APP_BG)
        badge_row.pack(fill=X, side=TOP, padx=4, pady=(0, 3))

        for _no, label, req_count, keywords in checklist:
            found = sum(
                1 for name in lower_names
                if any(kw in name for kw in keywords)
            )
            if found >= req_count:
                bg, fg, icon = "#d4edda", "#155724", "✅"
            elif found > 0:
                bg, fg, icon = "#fff3cd", "#856404", "⚠"
                n_partial += 1
            else:
                bg, fg, icon = "#f8d7da", "#721c24", "❌"
                n_missing += 1

            short = label if len(label) <= 18 else label[:16] + "…"
            badge = tkinter.Label(
                badge_row,
                text=f"{icon} {short}",
                bg=bg, fg=fg,
                font=("Segoe UI", 7),
                relief="flat",
                padx=4, pady=2,
                cursor="hand2",
            )
            badge.pack(side=LEFT, padx=2, pady=1)
            badge.bind("<Enter>", lambda e, lbl=label, kw=keywords:
                       e.widget.config(text=f"  {lbl}  "))
            badge.bind("<Leave>", lambda e, ico=icon, s=short:
                       e.widget.config(text=f"{ico} {s}"))
            if report_path and os.path.isfile(report_path):
                badge.bind("<Button-1>", lambda _e, rp=report_path: _open_file_with_os(rp))

        # Update header summary
        if n_missing == 0 and n_partial == 0:
            summary = "All documents found ✅"
            fg_sum  = SFM_SUCCESS
        else:
            parts = []
            if n_missing: parts.append(f"{n_missing} missing")
            if n_partial: parts.append(f"{n_partial} incomplete")
            summary = "  ⚠  " + ", ".join(parts)
            fg_sum  = SFM_DANGER
        tkinter.Label(
            hdr, text=summary, bg=SFM_APP_BG, fg=fg_sum,
            font=("Segoe UI", 8, "bold"),
        ).pack(side=LEFT, padx=8)

        # Show the strip (insert above the tree chrome)
        self._doc_alert_strip.pack(fill=X, before=self._tree_chrome_frame, pady=(0, 2))

    def _hide_doc_alert_strip(self) -> None:
        try:
            self._doc_alert_strip.pack_forget()
        except Exception:
            pass

    def _open_expiry_heatmap(self) -> None:
        """Feature 6 — open document expiry heat map window."""
        out_paths = getattr(self, "_doc_alert_out_paths", [])
        api_key   = _load_settings().get("openai_api_key", "").strip()
        top       = self.winfo_toplevel()

        if not out_paths:
            messagebox.showinfo(
                "Expiry Heat Map",
                "Run Smart Split & Merge first to generate output documents.",
                parent=top,
            )
            return

        if not api_key:
            messagebox.showwarning(
                "Expiry Heat Map",
                "An OpenAI API key is required to extract issue dates from documents.\n\n"
                "Set your key in Settings → API Key.",
                parent=top,
            )
            return

        # Run date extraction in a background thread so the UI stays responsive
        self.files_status.set("📅 Scanning document dates…")
        self.update_idletasks()

        import threading as _th

        def _run():
            results = {}
            try:
                results = fo.get_expiry_heatmap_data(
                    out_paths, api_key, self.log_message,
                )
            except Exception as _exc:
                self.after(0, lambda: self.log_message(f"Expiry scan error: {_exc}"))
            self.after(0, lambda r=results: _show(r))

        def _show(results):
            self.files_status.set("Ready")
            _show_expiry_heatmap(top, results)

        _th.Thread(target=_run, daemon=True, name="expiry-scan").start()

