    def _build_path_breadcrumb_ui(self, folder_block, external: bool = False) -> None:
        """Path breadcrumb: light card, chip segments, horizontal scroll (Shift+wheel).

        When *external* is True the host is packed into the app top bar (beside the
        Files/Folders buttons); otherwise it is gridded inside the toolbar block.
        """
        self._breadcrumb_host = tkinter.Frame(folder_block, bg=SFM_APP_BG, highlightthickness=0)
        if external:
            self._breadcrumb_host.pack(side=LEFT, fill=BOTH, expand=True)
        else:
            self._breadcrumb_host.grid(row=1, column=0, columnspan=14, sticky=(W, E), pady=(6, 0))
        _card = tkinter.Frame(
            self._breadcrumb_host,
            bg=SFM_BREAD_BG,
            highlightthickness=1,
            highlightbackground=SFM_BREAD_BORDER,
            highlightcolor=SFM_BREAD_BORDER,
        )
        _card.pack(fill=BOTH, expand=True)
        _accent = tkinter.Frame(_card, bg=SFM_BREAD_ACCENT_BAR, height=2)
        _accent.pack(side=TOP, fill=X)
        _accent.pack_propagate(False)
        _body = tkinter.Frame(_card, bg=SFM_BREAD_BG, highlightthickness=0)
        _body.pack(fill=BOTH, expand=True, padx=10, pady=(6, 4))
        self._breadcrumb_canvas = tkinter.Canvas(
            _body,
            height=40,
            bg=SFM_BREAD_BG,
            highlightthickness=0,
            borderwidth=0,
        )
        self._breadcrumb_inner = tkinter.Frame(self._breadcrumb_canvas, bg=SFM_BREAD_BG)
        self._breadcrumb_canvas_win = self._breadcrumb_canvas.create_window(0, 0, anchor="nw", window=self._breadcrumb_inner)
        self._breadcrumb_hscroll = tkinter.Scrollbar(
            _body,
            orient=HORIZONTAL,
            command=self._breadcrumb_canvas.xview,
            troughcolor=SFM_BREAD_CHIP,
            bg=SFM_SCROLL_GREY,
            activebackground=SFM_MUTED,
            bd=0,
            width=10,
        )
        self._breadcrumb_canvas.configure(xscrollcommand=self._breadcrumb_hscroll.set)
        self._breadcrumb_canvas.pack(side=TOP, fill=BOTH, expand=True)
        self._breadcrumb_hscroll.pack(side=BOTTOM, fill=X)
        self._breadcrumb_canvas.bind("<Configure>", self._on_breadcrumb_canvas_configure)
        self._breadcrumb_inner.bind("<Configure>", self._on_breadcrumb_inner_configure)
        self._breadcrumb_canvas.bind("<Shift-MouseWheel>", self._on_breadcrumb_shift_wheel)
        self._breadcrumb_canvas.bind("<Shift-Button-4>", lambda _e: self._breadcrumb_canvas.xview_scroll(-3, "units"))
        self._breadcrumb_canvas.bind("<Shift-Button-5>", lambda _e: self._breadcrumb_canvas.xview_scroll(3, "units"))
        self._breadcrumb_segments_cache: list[tuple[str, str]] = []

    def _on_breadcrumb_canvas_configure(self, event: tkinter.Event) -> None:
        try:
            self._breadcrumb_canvas.itemconfigure(self._breadcrumb_canvas_win, width=event.width)
        except tkinter.TclError:
            pass

    def _on_breadcrumb_inner_configure(self, _event: tkinter.Event | None = None) -> None:
        try:
            self._breadcrumb_canvas.configure(scrollregion=self._breadcrumb_canvas.bbox("all"))
            h = max(32, self._breadcrumb_inner.winfo_reqheight())
            self._breadcrumb_canvas.configure(height=h + 4)
        except tkinter.TclError:
            pass

    def _on_breadcrumb_shift_wheel(self, event: tkinter.Event) -> str | None:
        d = getattr(event, "delta", 0) or 0
        if sys.platform == "darwin":
            step = -1 if d > 0 else 1
        else:
            step = int(-1 * (d / 120)) if d else 0
        if step:
            self._breadcrumb_canvas.xview_scroll(step, "units")
        return "break"

    def _bind_breadcrumb_chip_hover(
        self, chip: tkinter.Frame, base_bg: str, widgets: list[tkinter.Widget]
    ) -> None:
        def _set_bg(bg: str) -> None:
            try:
                chip.configure(bg=bg)
            except tkinter.TclError:
                pass
            for w in widgets:
                try:
                    w.configure(bg=bg)
                except tkinter.TclError:
                    pass

        def _in(_e: tkinter.Event | None = None) -> None:
            _set_bg(SFM_BREAD_HOVER)

        def _out(_e: tkinter.Event | None = None) -> None:
            _set_bg(base_bg)

        for w in (chip, *widgets):
            w.bind("<Enter>", _in)
            w.bind("<Leave>", _out)

    def _on_breadcrumb_segment_click(self, target: str) -> None:
        if target and os.path.isdir(target):
            self.load_folder_path(target)

    def _post_breadcrumb_sibling_menu(self, event: tkinter.Event, segment_index: int) -> None:
        segs = getattr(self, "_breadcrumb_segments_cache", None) or []
        if not segs or segment_index < 0 or segment_index >= len(segs):
            return
        top = self.winfo_toplevel()
        m = Menu(top, tearoff=0)
        if segment_index == 0:
            for letter in string.ascii_uppercase:
                d = f"{letter}:\\"
                if os.path.isdir(d):
                    m.add_command(label=d, command=lambda p=d: self.load_folder_path(p))
        else:
            parent = segs[segment_index - 1][1]
            cur_name = os.path.basename(segs[segment_index][1].rstrip(os.sep))
            try:
                names = sorted(
                    [n for n in os.listdir(parent) if os.path.isdir(os.path.join(parent, n))],
                    key=fo.filesystem_natural_sort_key,
                )
            except OSError:
                names = []
            for name in names[:120]:
                full = os.path.join(parent, name)
                mark = "   ✓" if name.lower() == cur_name.lower() else ""
                m.add_command(label=name + mark, command=lambda p=full: self.load_folder_path(p))
        try:
            m.tk_popup(event.x_root, event.y_root)
        finally:
            try:
                m.grab_release()
            except tkinter.TclError:
                pass

    def _rebuild_path_breadcrumb(self) -> None:
        """Refresh breadcrumb from ``_root_path`` (call after load / ZIP open)."""
        if not getattr(self, "_breadcrumb_inner", None):
            return
        for w in self._breadcrumb_inner.winfo_children():
            try:
                w.destroy()
            except tkinter.TclError:
                pass
        inner = self._breadcrumb_inner
        bg = SFM_BREAD_BG
        root_path = (self._root_path or "").strip()
        if not root_path or not os.path.isdir(root_path):
            tkinter.Label(
                inner,
                text="Open a folder — click any path segment to jump;  ▾  lists drives or sibling folders",
                fg=SFM_BREAD_DIM,
                bg=bg,
                font=("Segoe UI", 9),
            ).pack(side=LEFT, padx=(2, 8), pady=6)
            self._breadcrumb_segments_cache = []
            self.after_idle(self._on_breadcrumb_inner_configure)
            return

        segs = fs_breadcrumb_segments(root_path)
        self._breadcrumb_segments_cache = list(segs)
        last_i = len(segs) - 1

        path_chip = tkinter.Frame(inner, bg=SFM_BREAD_CHIP, highlightthickness=0)
        path_chip.pack(side=LEFT, padx=(0, 12), pady=4)
        path_icon = tkinter.Label(
            path_chip,
            text="\U0001f4c2",
            fg=SFM_BREAD_BADGE_FG,
            bg=SFM_BREAD_CHIP,
            font=("Segoe UI", 10),
        )
        path_icon.pack(side=LEFT, padx=(8, 2), pady=4)
        path_cap = tkinter.Label(
            path_chip,
            text="Path",
            fg=SFM_BREAD_DIM,
            bg=SFM_BREAD_CHIP,
            font=("Segoe UI", 8),
        )
        path_cap.pack(side=LEFT, padx=(0, 8), pady=4)

        for i, (label, full) in enumerate(segs):
            if i > 0:
                tkinter.Label(
                    inner,
                    text="\u203a",
                    fg=SFM_BREAD_ARROW,
                    bg=bg,
                    font=("Segoe UI", 11),
                ).pack(side=LEFT, padx=(2, 2), pady=6)
            is_last = i == last_i
            chip_bg = SFM_BREAD_CHIP if is_last else bg
            chip = tkinter.Frame(inner, bg=chip_bg, highlightthickness=0)
            chip.pack(side=LEFT, padx=1, pady=4)
            seg_fg = SFM_BREAD_FG if is_last else SFM_BREAD_LINK
            seg_font: tuple = ("Segoe UI", 10, "bold") if is_last else ("Segoe UI", 10)
            seg_lbl = tkinter.Label(
                chip,
                text=label,
                fg=seg_fg,
                bg=chip_bg,
                font=seg_font,
                cursor="hand2",
            )
            seg_lbl.pack(side=LEFT, padx=(10, 2), pady=3)
            seg_lbl.bind("<Button-1>", lambda _e, p=full: self._on_breadcrumb_segment_click(p))
            dd = tkinter.Label(
                chip,
                text="\u25be",
                fg=SFM_BREAD_DIM,
                bg=chip_bg,
                font=("Segoe UI", 8),
                cursor="hand2",
            )
            dd.pack(side=LEFT, padx=(0, 8), pady=3)
            dd.bind("<Button-1>", lambda e, idx=i: self._post_breadcrumb_sibling_menu(e, idx))
            self._bind_breadcrumb_chip_hover(chip, chip_bg, [seg_lbl, dd])

        self.after_idle(self._on_breadcrumb_inner_configure)

    def _build_ui(self) -> None:
        # ── Single compact top toolbar: path + buttons + search all in one row ──
        folder_block = ttk.Frame(self, style="ToolBar.TFrame", padding=(6, 3, 6, 3))
        folder_block.grid(row=0, column=0, sticky=(W, E))
        folder_block.columnconfigure(6, weight=1)  # path entry expands

        # ── Group 1: Browse ───────────────────────────────────────────────────
        _btn_folder = ttk.Button(folder_block, text="📂 Folder", command=self.browse_folder)
        _btn_folder.grid(row=0, column=0, padx=(0, SP_2))
        Tooltip(_btn_folder, "Browse for a folder (Ctrl+O)")
        _btn_zip = ttk.Button(folder_block, text="🗜 ZIP", command=self.browse_zip)
        _btn_zip.grid(row=0, column=1, padx=(0, SP_2))
        Tooltip(_btn_zip, "Open a ZIP archive as a virtual folder")
        _btn_ref = ttk.Button(folder_block, text="↺ Refresh", command=self.refresh_tree)
        _btn_ref.grid(row=0, column=2, padx=(0, SP_4))
        Tooltip(_btn_ref, "Reload folder contents from disk (F5)")
        # ── Separator ─────────────────────────────────────────────────────────
        ttk.Separator(folder_block, orient=VERTICAL).grid(
            row=0, column=3, sticky=(N, S), padx=(0, SP_4), pady=2,
        )
        # ── Group 2: Nav [◀ ▲ ▶] ─────────────────────────────────────────────
        _nav_frame = ttk.Frame(folder_block)
        _nav_frame.grid(row=0, column=4, padx=(0, SP_4))
        self._nav_btn_back = ttk.Button(_nav_frame, text="◀", width=2, command=self.nav_back)
        self._nav_btn_back.pack(side=LEFT, padx=(0, 1))
