    def _open_pdfs_with_acrobat(self, paths: list[str]) -> None:
        """Open one or more on-disk PDFs in Adobe Acrobat (multi-select supported)."""
        top = self.winfo_toplevel()
        ok, err = fo.open_paths_with_acrobat(paths, self.log_message)
        if ok:
            n = sum(
                1
                for p in paths
                if p and str(p).lower().endswith(".pdf") and os.path.isfile(os.path.abspath(p))
            )
