    def _primary_ref(self) -> tuple | None:
        sel = self.file_tree.selection()
        if not sel:
            return None
        return self._tree_ref.get(sel[0])

    def _primary_path(self) -> str | None:
        """Filesystem path for the selection, or None for entries only inside a ZIP tree."""
        ref = self._primary_ref()
        if not ref:
            return None
        if ref[0] == "fs":
            return ref[1]
        return None

    def _ordered_disk_pdf_paths_from_selection(self) -> list[str]:
        out: list[str] = []
        seen: set[str] = set()
        for iid in self.file_tree.selection():
            ref = self._tree_ref.get(iid)
            if not ref or ref[0] != "fs":
                continue
            path = ref[1]
            if not os.path.isfile(path):
                continue
            if os.path.splitext(path)[1].lower() != ".pdf":
                continue
            ap = os.path.abspath(path)
            if ap not in seen:
                seen.add(ap)
                out.append(ap)
        return out

    def _ordered_disk_image_pdf_paths_from_selection(self) -> list[str]:
        """Selected on-disk image/PDF files in tree order (for combine-to-PDF)."""
        out: list[str] = []
        seen: set[str] = set()
        for iid in self.file_tree.selection():
            ref = self._tree_ref.get(iid)
            if not ref or ref[0] != "fs":
                continue
            path = ref[1]
            if not os.path.isfile(path):
                continue
            ext = os.path.splitext(path)[1].lower()
            if ext != ".pdf" and ext not in fo.IMAGE_EXT:
                continue
            ap = os.path.abspath(path)
            if ap not in seen:
                seen.add(ap)
                out.append(ap)
        return out

    @staticmethod
    def _all_paths_same_parent_dir(paths: list[str]) -> bool:
        if len(paths) < 2:
            return True
        dirs = {os.path.normcase(os.path.abspath(os.path.dirname(p))) for p in paths}
        return len(dirs) == 1

    def _single_selected_fs_file(self) -> str | None:
        sel = self.file_tree.selection()
        if len(sel) != 1:
            return None
        ref = self._tree_ref.get(sel[0])
        if not ref or ref[0] != "fs":
            return None
        path = ref[1]
        return path if os.path.isfile(path) else None

    def _fs_parent_dir_for_new_txt(self, row_under_cursor: str | None) -> str | None:
        """Directory on disk where a new .txt should be created (Explorer-style)."""
        if not self._root_path or not os.path.isdir(self._root_path):
            return None
        root_abs = os.path.abspath(self._root_path)
        if not row_under_cursor:
            return root_abs
        ref = self._tree_ref.get(row_under_cursor)
        if not ref or ref[0] != "fs":
            return None
        path = os.path.abspath(ref[1])
        if os.path.isdir(path):
            return path
        if os.path.isfile(path):
            return os.path.dirname(path)
        return None

    def _fs_is_under_workspace(self, path: str) -> bool:
        if not self._root_path or not os.path.isdir(self._root_path):
            return False
        root = os.path.abspath(os.path.normpath(self._root_path))
        ap = os.path.abspath(os.path.normpath(path))
        try:
            return os.path.commonpath([root, ap]) == root
        except ValueError:
            return False

    @staticmethod
    def _fs_path_inside_or_equal(child_path: str, ancestor_path: str) -> bool:
        """True if ``child_path`` is the same as or nested under ``ancestor_path``."""
        ch = os.path.normcase(os.path.abspath(os.path.normpath(child_path)))
        anc = os.path.normcase(os.path.abspath(os.path.normpath(ancestor_path)))
        return ch == anc or ch.startswith(anc + os.sep)

    def _fs_filter_nested_paths(self, paths: list[str]) -> list[str]:
        """When the same folder tree is partly selected, keep only top-level paths."""
        norm = sorted({os.path.abspath(os.path.normpath(p)) for p in paths}, key=len)
        kept: list[str] = []
        for p in norm:
            if any(k != p and self._fs_path_inside_or_equal(p, k) for k in kept):
                continue
            kept.append(p)
        return kept

    def _collect_fs_paths_from_selection(self) -> list[str]:
        out: list[str] = []
        for iid in self.file_tree.selection():
            ref = self._tree_ref.get(iid)
            if not ref or ref[0] != "fs":
                continue
            ap = os.path.abspath(os.path.normpath(ref[1]))
            if os.path.isfile(ap) or os.path.isdir(ap):
                out.append(ap)
        return self._fs_filter_nested_paths(out)

    def _tree_paste_destination_dir(self) -> str | None:
        if not self._root_path or not os.path.isdir(self._root_path):
            return None
        iid = self.file_tree.focus()
        if not iid:
            sel = self.file_tree.selection()
            iid = sel[0] if sel else None
        return self._fs_parent_dir_for_new_txt(iid)

    def _fs_next_available_dest_path(self, dest_dir: str, base_name: str) -> str:
        dest_dir = os.path.abspath(dest_dir)
        candidate = os.path.join(dest_dir, base_name)
        if not os.path.exists(candidate):
            return candidate
        stem, ext = os.path.splitext(base_name)
        if base_name.endswith(os.extsep) or not ext:
            root_name = base_name
            for n in range(2, 100_000):
                c = os.path.join(dest_dir, f"{root_name} ({n})")
                if not os.path.exists(c):
                    return c
            return candidate
        for n in range(2, 100_000):
            c = os.path.join(dest_dir, f"{stem} ({n}){ext}")
            if not os.path.exists(c):
                return c
        return candidate

    def _tree_cut_selection(self) -> None:
        paths = self._collect_fs_paths_from_selection()
        top = self.winfo_toplevel()
        if not paths:
            messagebox.showinfo(
                "Cut",
                "Select one or more files or folders on disk (not inside an opened ZIP branch).",
                parent=top,
            )
            return
        for p in paths:
            if not self._fs_is_under_workspace(p):
                messagebox.showerror(
                    "Cut",
                    "Only items under the opened workspace folder can be cut.",
                    parent=top,
                )
                return
        self._fs_clipboard_paths = list(paths)
        self._fs_clipboard_is_cut = True
        self.files_status.set(f"Cut — {len(paths)} item(s) (paste to move)")
        self.log_message(f"Cut {len(paths)} path(s) to clipboard")

    def _tree_copy_selection(self) -> None:
        paths = self._collect_fs_paths_from_selection()
        top = self.winfo_toplevel()
        if not paths:
            messagebox.showinfo(
                "Copy",
                "Select one or more files or folders on disk (not inside an opened ZIP branch).",
                parent=top,
            )
            return
        for p in paths:
            if not self._fs_is_under_workspace(p):
                messagebox.showerror(
                    "Copy",
                    "Only items under the opened workspace folder can be copied.",
                    parent=top,
                )
                return
        self._fs_clipboard_paths = list(paths)
        self._fs_clipboard_is_cut = False
        self.files_status.set(f"Copy — {len(paths)} item(s) (paste to duplicate)")
        self.log_message(f"Copied {len(paths)} path(s) to clipboard")

    def _tree_paste(self) -> None:
        top = self.winfo_toplevel()
        if not self._fs_clipboard_paths:
            messagebox.showinfo("Paste", "Nothing in the clipboard. Use Cut or Copy first.", parent=top)
            return
        dest_parent = self._tree_paste_destination_dir()
        if not dest_parent or not os.path.isdir(dest_parent):
            messagebox.showinfo(
                "Paste",
                "Right-click a folder or file (or empty tree area) to choose where to paste, "
                "or focus a row and press Ctrl+V.",
                parent=top,
            )
            return
        if not self._fs_is_under_workspace(dest_parent):
            messagebox.showerror("Paste", "Cannot paste outside the opened workspace folder.", parent=top)
            return

        sources = []
        for p in self._fs_clipboard_paths:
            ap = os.path.abspath(os.path.normpath(p))
            if os.path.isfile(ap) or os.path.isdir(ap):
                sources.append(ap)
        if not sources:
            messagebox.showerror("Paste", "Clipboard paths are no longer on disk.", parent=top)
            self._fs_clipboard_paths = []
            return

        dp = os.path.abspath(dest_parent)
        for src in sources:
            sa = os.path.abspath(src)
            if self._fs_path_inside_or_equal(dp, sa):
                messagebox.showerror(
                    "Paste",
                    "Cannot paste into a folder you cut, or into a folder inside it.",
                    parent=top,
                )
                return

        is_cut = self._fs_clipboard_is_cut
        moved_or_copied: list[str] = []
        cut_move_pairs: list[tuple[str, str]] = []  # (original_src, new_dst) for undo
        errors: list[str] = []
        for src in sources:
            base = os.path.basename(src.rstrip(os.sep))
            dst = self._fs_next_available_dest_path(dp, base)
            try:
                if is_cut:
                    shutil.move(src, dst)
                    cut_move_pairs.append((src, dst))
                else:
                    if os.path.isfile(src):
                        shutil.copy2(src, dst)
                    else:
                        shutil.copytree(src, dst)
                moved_or_copied.append(dst)
            except OSError as e:
                errors.append(f"{src} → {e}")

        if moved_or_copied:
            self._build_tree()
            self._select_path_in_tree(moved_or_copied[-1])
            act = "Moved" if is_cut else "Copied"
            self.log_message(f"{act} {len(moved_or_copied)} item(s) → {dp}")
            self.files_status.set(f"Paste: {len(moved_or_copied)} item(s)")
        if is_cut and cut_move_pairs:
            self._record_event("move", {"moves": cut_move_pairs})
        if errors:
            self.log_message("Paste errors:\n" + "\n".join(errors[:15]))
            messagebox.showerror(
                "Paste",
                "Some items failed:\n" + "\n".join(errors[:8]),
                parent=top,
            )
        if is_cut and moved_or_copied and not errors:
            self._fs_clipboard_paths = []
            self._fs_clipboard_is_cut = False

    # ──────────────────────────────────────────────────────────────────────────
    # Copy To / Move To / Root  (works on selected files AND files inside
    # selected folders, even when those files span multiple different folders)
    # ──────────────────────────────────────────────────────────────────────────

    def _collect_files_expanding_folders(self) -> list[str]:
        """Return all files from selection.

        - Selected files   → included directly.
        - Selected folders → direct-child files inside that folder are included.

        Duplicate paths are silently dropped.
        """
        files: list[str] = []
        seen: set[str] = set()
        for iid in self.file_tree.selection():
            ref = self._tree_ref.get(iid)
            if not ref or ref[0] != "fs":
                continue
            ap = os.path.abspath(os.path.normpath(ref[1]))
            if os.path.isfile(ap):
                nk = os.path.normcase(ap)
                if nk not in seen:
                    seen.add(nk)
                    files.append(ap)
            elif os.path.isdir(ap):
                try:
                    for entry in os.scandir(ap):
                        if entry.is_file():
                            ep = os.path.abspath(entry.path)
                            nk = os.path.normcase(ep)
                            if nk not in seen:
                                seen.add(nk)
                                files.append(ep)
                except OSError:
                    pass
        return files

    def _copy_to_dialog(self) -> None:
        """Copy selected files (and files inside selected folders) to a chosen destination."""
        top = self.winfo_toplevel()
        files = self._collect_files_expanding_folders()
        if not files:
            messagebox.showinfo(
                "Copy To",
                "Select one or more files or folders first.",
                parent=top,
            )
            return
        dest = filedialog.askdirectory(title="Copy files to folder…", parent=top)
        if not dest:
            return
        dest = os.path.abspath(dest)
        errors: list[str] = []
        copied: list[str] = []
        for src in files:
            base = os.path.basename(src)
            dst = self._fs_next_available_dest_path(dest, base)
            try:
                shutil.copy2(src, dst)
                copied.append(dst)
            except OSError as exc:
                errors.append(f"{os.path.basename(src)}: {exc}")
        if copied:
            self._build_tree()
            self.log_message(f"Copy To: {len(copied)} file(s) → {dest}")
            self.files_status.set(f"Copied {len(copied)} file(s) to {os.path.basename(dest)}")
        if errors:
            self.log_message("Copy To errors:\n" + "\n".join(errors[:15]))
            messagebox.showerror(
                "Copy To",
                f"Copied {len(copied)} file(s). Some failed:\n\n" + "\n".join(errors[:8]),
                parent=top,
            )

    def _move_to_dialog(self) -> None:
        """Move selected files (and files inside selected folders) to a chosen destination."""
        top = self.winfo_toplevel()
        files = self._collect_files_expanding_folders()
        if not files:
            messagebox.showinfo(
                "Move To",
                "Select one or more files or folders first.",
                parent=top,
            )
            return
        for f in files:
            if not self._fs_is_under_workspace(f):
                messagebox.showerror(
                    "Move To",
                    f"Only files inside the workspace folder can be moved.\n\n{f}",
                    parent=top,
                )
                return
        dest = filedialog.askdirectory(title="Move files to folder…", parent=top)
        if not dest:
            return
        dest = os.path.abspath(dest)
        errors: list[str] = []
        moved: list[str] = []
        for src in files:
            base = os.path.basename(src)
            dst = self._fs_next_available_dest_path(dest, base)
            try:
                shutil.move(src, dst)
                moved.append(dst)
            except OSError as exc:
                errors.append(f"{os.path.basename(src)}: {exc}")
        if moved:
            self._build_tree()
            self.log_message(f"Move To: {len(moved)} file(s) → {dest}")
            self.files_status.set(f"Moved {len(moved)} file(s) to {os.path.basename(dest)}")
        if errors:
            self.log_message("Move To errors:\n" + "\n".join(errors[:15]))
            messagebox.showerror(
                "Move To",
                f"Moved {len(moved)} file(s). Some failed:\n\n" + "\n".join(errors[:8]),
                parent=top,
            )

    def _root_selected(self) -> None:
        """Move selected files (and files inside selected folders) to the workspace root."""
        top = self.winfo_toplevel()
        if not self._root_path or not os.path.isdir(self._root_path):
            messagebox.showinfo("Root", "Open a workspace folder first.", parent=top)
            return
        files = self._collect_files_expanding_folders()
        if not files:
            messagebox.showinfo(
                "Root",
                "Select one or more files or folders first.",
                parent=top,
            )
            return
        root_abs = os.path.abspath(self._root_path)
        root_norm = os.path.normcase(root_abs)
        # Skip files already sitting directly in the root
        to_move = [
            f for f in files
            if os.path.normcase(os.path.dirname(os.path.abspath(f))) != root_norm
        ]
        already_at_root = len(files) - len(to_move)
        if not to_move:
            messagebox.showinfo(
                "Root",
                "All selected files are already in the workspace root.",
                parent=top,
            )
            return
        for f in to_move:
            if not self._fs_is_under_workspace(f):
                messagebox.showerror(
                    "Root",
                    f"Only files inside the workspace folder can be moved.\n\n{f}",
                    parent=top,
                )
                return
        # Confirm
        preview = "\n".join(
            f"  {os.path.relpath(f, root_abs)}" for f in to_move[:12]
        )
        if len(to_move) > 12:
            preview += f"\n  … and {len(to_move) - 12} more"
        note = f"\n\n({already_at_root} file(s) already in root — skipped)" if already_at_root else ""
        if not messagebox.askyesno(
            "Move to Root",
            f"Move {len(to_move)} file(s) to workspace root?\n\n{preview}{note}\n\n→ {root_abs}",
            parent=top,
        ):
            return
        errors: list[str] = []
        moved: list[str] = []
        for src in to_move:
            base = os.path.basename(src)
            dst = self._fs_next_available_dest_path(root_abs, base)
            try:
                shutil.move(src, dst)
                moved.append(dst)
            except OSError as exc:
                errors.append(f"{os.path.basename(src)}: {exc}")
        if moved:
            self._build_tree()
            self.log_message(f"Root: moved {len(moved)} file(s) → {root_abs}")
            self.files_status.set(f"Moved {len(moved)} file(s) to root")
        if errors:
            self.log_message("Root errors:\n" + "\n".join(errors[:15]))
            messagebox.showerror(
                "Root",
                f"Moved {len(moved)} file(s). Some failed:\n\n" + "\n".join(errors[:8]),
                parent=top,
            )




    # ── Expand / Collapse tree folders ───────────────────────────────────────

    def _expand_all_tree(self) -> None:
        """Recursively expand every folder in the tree, loading lazy children."""
        def _expand(iid: str) -> None:
            # Load children first (replaces placeholder with real rows)
            self._tree_expand_lazy_populate(iid)
            try:
                self.file_tree.item(iid, open=True)
            except tkinter.TclError:
                pass
            for child in list(self.file_tree.get_children(iid)):
                if self._tree_row_is_folder(child):
                    _expand(child)
        for root_iid in self.file_tree.get_children(""):
            _expand(root_iid)
        self.files_status.set("Expanded all folders")

    def _collapse_all_tree(self) -> None:
        """Collapse every node in the tree."""
        def _collapse(iid: str) -> None:
            for child in list(self.file_tree.get_children(iid)):
                _collapse(child)
            try:
                self.file_tree.item(iid, open=False)
            except tkinter.TclError:
                pass
        for root_iid in self.file_tree.get_children(""):
            _collapse(root_iid)
        self.files_status.set("Collapsed all folders")

    def _expand_selected_folder(self) -> None:
        """Expand selected folder(s) and all subfolders within them."""
        def _expand(iid: str) -> None:
            self._tree_expand_lazy_populate(iid)
            try:
                self.file_tree.item(iid, open=True)
            except tkinter.TclError:
                pass
            for child in list(self.file_tree.get_children(iid)):
                if self._tree_row_is_folder(child):
                    _expand(child)
        for iid in self.file_tree.selection():
            if self._tree_row_is_folder(iid):
                _expand(iid)

    def _collapse_selected_folder(self) -> None:
        """Collapse selected folder(s) and all subfolders within them."""
        def _collapse(iid: str) -> None:
            for child in list(self.file_tree.get_children(iid)):
                _collapse(child)
            try:
                self.file_tree.item(iid, open=False)
            except tkinter.TclError:
                pass
        for iid in self.file_tree.selection():
            if self._tree_row_is_folder(iid):
                _collapse(iid)

    # ── College Photo Sheet ─────────────────────────────────────────────────
    # Select multiple photos → Photoshop JSX creates a layered PSD
    # Layout: passport-style strip, one after another with printing margin
    # ─────────────────────────────────────────────────────────────────────────


    def _make_college_photo_sheet(self) -> None:
        """Build A4 600-DPI PDF: photos flush side-by-side, 1px off-white stroke, 25px margin."""
        import math as _math

        top = self.winfo_toplevel()
        Image = fo.get_pillow()
        if Image is None:
            messagebox.showerror("College Photo Sheet",
                "Pillow is required.\n  pip install pillow", parent=top)
            return

        IMAGE_EXT = {".jpg", ".jpeg", ".png", ".bmp", ".tif", ".tiff",
                     ".webp", ".gif", ".jfif"}
        photo_paths: list[str] = []
        seen: set[str] = set()
        for iid in self.file_tree.selection():
            ref = self._tree_ref.get(iid)
            if not ref or ref[0] != "fs":
                continue
            ap = os.path.abspath(os.path.normpath(ref[1]))
            if os.path.isfile(ap) and os.path.splitext(ap)[1].lower() in IMAGE_EXT:
                nk = os.path.normcase(ap)
                if nk not in seen:
                    seen.add(nk)
                    photo_paths.append(ap)

        if not photo_paths:
            messagebox.showinfo("College Photo Sheet",
                "Select one or more image files in the tree first.",
                parent=top)
            return

        self.files_status.set("Building photo sheet...")
        top.update_idletasks()

        # Constants
        DPI        = 600
        MM         = DPI / 25.4
        A4_W       = int(round(210 * MM))   # 4961 px
        A4_H       = int(round(297 * MM))   # 7016 px
        ROW_H      = int(round(45 * MM))    # 1063 px — photo height (45 mm passport)
        MARGIN     = int(round(0.15 * DPI)) # 0.15 inch page margin on all sides (90 px)
        STROKE     = 1                      # px off-white border on each photo
        STROKE_CLR = (180, 175, 170)        # dark off-white stroke colour

        # Usable page width
        USABLE_W = A4_W - 2 * MARGIN
        USABLE_H = A4_H - 2 * MARGIN

        # Scale every photo to ROW_H, keep exact aspect ratio, add stroke border
        framed: list = []
        for src_path in photo_paths:
            try:
                img    = Image.open(src_path).convert("RGB")
                ratio  = img.width / img.height
                new_w  = max(1, int(round(ROW_H * ratio)))
                img    = img.resize((new_w, ROW_H), Image.LANCZOS)
                # Add 1px off-white stroke: create canvas 2px wider/taller
                canvas = Image.new("RGB",
                                   (new_w + 2 * STROKE, ROW_H + 2 * STROKE),
                                   STROKE_CLR)
                canvas.paste(img, (STROKE, STROKE))
                framed.append(canvas)
            except Exception as exc:
                self.log_message(f"Photo sheet skip {os.path.basename(src_path)}: {exc}")
                framed.append(None)

        # Place photos flush left-to-right inside margin, wrap at usable edge
        pages: list = []

        def new_page():
            return Image.new("RGB", (A4_W, A4_H), (255, 255, 255))

        page = new_page()
        x    = MARGIN
        y    = MARGIN

        for img in framed:
            if img is None:
                continue
            if x + img.width > MARGIN + USABLE_W:   # wrap row
                x  = MARGIN
                y += img.height
            if y + img.height > MARGIN + USABLE_H:  # new page
                pages.append(page)
                page = new_page()
                x    = MARGIN
                y    = MARGIN
            page.paste(img, (x, y))
            x += img.width

        pages.append(page)

        # Save as PDF
        out_dir  = os.path.dirname(photo_paths[0])
        pdf_path = os.path.join(out_dir, "college_photo_sheet.pdf")
        counter  = 2
        while os.path.exists(pdf_path):
            pdf_path = os.path.join(out_dir, f"college_photo_sheet_{counter}.pdf")
            counter += 1

        try:
            if len(pages) == 1:
                pages[0].save(pdf_path, "PDF", resolution=DPI)
            else:
                pages[0].save(pdf_path, "PDF", resolution=DPI,
                              save_all=True, append_images=pages[1:])
            self.log_message(f"Photo sheet PDF: {pdf_path}")
        except Exception as exc:
            messagebox.showerror("College Photo Sheet",
                f"Failed to save PDF:\n{exc}", parent=top)
            self.files_status.set("Photo sheet failed")
            return

        self._build_tree()
        self._select_path_in_tree(pdf_path)
        self.files_status.set("Photo sheet done")
        messagebox.showinfo("College Photo Sheet",
            f"{len(framed)} photo(s) → {len(pages)} page(s), 600 DPI\n\n{pdf_path}",
            parent=top)

    def _make_folder_for_each_file(self) -> None:
        """For each selected file, create a same-named folder beside it and move the file in.

        Example:  Report.pdf  ->  Report/Report.pdf
        Works for multiple selections across different parent folders.
        """
        top = self.winfo_toplevel()
        # Collect only files (not folders) from selection
        selected_files: list[str] = []
        seen: set[str] = set()
        for iid in self.file_tree.selection():
            ref = self._tree_ref.get(iid)
            if not ref or ref[0] != "fs":
                continue
            ap = os.path.abspath(os.path.normpath(ref[1]))
            nk = os.path.normcase(ap)
            if os.path.isfile(ap) and nk not in seen:
                seen.add(nk)
                selected_files.append(ap)

        if not selected_files:
            messagebox.showinfo(
                "Make Folder for File",
                "Select one or more files first.\n\n"
                "(Folders are skipped — only files get their own folder.)",
                parent=top,
            )
            return

        for f in selected_files:
            if not self._fs_is_under_workspace(f):
                messagebox.showerror(
                    "Make Folder for File",
                    f"Only files inside the workspace folder are supported.\n\n{f}",
                    parent=top,
                )
                return

        # Build preview
        preview_lines = []
        for f in selected_files[:12]:
            stem = os.path.splitext(os.path.basename(f))[0] or os.path.basename(f)
            preview_lines.append(
                f"  {os.path.basename(f)}  ->  {stem}{os.sep}{os.path.basename(f)}"
            )
        if len(selected_files) > 12:
            preview_lines.append(f"  ... and {len(selected_files) - 12} more")

        if not messagebox.askyesno(
            "Make Folder for File",
            f"Create a folder for each of {len(selected_files)} file(s) and move them in?\n\n"
            + "\n".join(preview_lines),
            parent=top,
        ):
            return

        errors: list[str] = []
        done: list[str] = []
        for src in selected_files:
            parent_dir = os.path.dirname(src)
            stem = os.path.splitext(os.path.basename(src))[0] or os.path.basename(src)
            new_folder = os.path.join(parent_dir, stem)
            if os.path.exists(new_folder) and not os.path.isdir(new_folder):
                for n in range(2, 100_000):
                    candidate = os.path.join(parent_dir, f"{stem} ({n})")
                    if not os.path.exists(candidate) or os.path.isdir(candidate):
                        new_folder = candidate
                        break
            try:
                os.makedirs(new_folder, exist_ok=True)
                dst = self._fs_next_available_dest_path(new_folder, os.path.basename(src))
                fo.invalidate_pdf_doc_cache(src)  # release preview handle before move
                shutil.move(src, dst)
                done.append(dst)
            except OSError as exc:
                errors.append(f"{os.path.basename(src)}: {exc}")

        if done:
            self._build_tree()
            self.log_message(f"Make Folder for File: {len(done)} file(s) moved into own folders")
            self.files_status.set(f"{len(done)} file(s) moved into own folders")
        if errors:
            self.log_message("Make Folder for File errors:\n" + "\n".join(errors[:15]))
            messagebox.showerror(
                "Make Folder for File",
                f"Done for {len(done)} file(s). Some failed:\n\n" + "\n".join(errors[:8]),
                parent=top,
            )


    # ── Korean name transliteration (OpenAI) ─────────────────────────────────

    def _korean_translate_rename_bar(self) -> None:
        """Transliterate the current rename-bar text to Korean via OpenAI."""
        top = self.winfo_toplevel()
        text = self.rename_var.get().strip()
        if not text:
            messagebox.showinfo("Korean Translate", "Type a name in the Rename bar first.", parent=top)
            return
        api_key = _get_openai_api_key()
        if not api_key:
            api_key = self._prompt_openai_api_key()
            if not api_key:
                return
        self.files_status.set("Translating to Korean…")
        top.update_idletasks()
        try:
            result = fo.translate_to_korean_openai([text], api_key, self.log_message)
            korean = result.get(text, text)
            if korean == text:
                # Translation returned the original — warn the user
                self.files_status.set("⚠ Translation returned same text — check API key/quota")
                messagebox.showwarning(
                    "Korean Translate",
                    "Translation succeeded but returned the same text.\n\n"
                    "This usually means the name was not recognised or the model\n"
                    "decided no transliteration was needed.\n\n"
                    "Try a different name, or check your API key and quota.",
                    parent=top,
                )
            else:
                self.rename_var.set(korean)
                self.files_status.set(f"✓ Korean: {korean}")
        except fo.KoreanTranslateError as exc:
            self.log_message(f"Korean translate: {exc}")
            messagebox.showerror("Korean Translate", str(exc), parent=top)
            self.files_status.set("Korean translation failed — see error dialog")

